  process.env.SESSION_SECRET || "dev-only-internal-secret-do-not-use-in-prod";

const requireAuth = async (req: any, res: any, next: any) => {
  const auth = getAuth(req);
  const userId = auth?.sessionClaims?.userId || auth?.userId;
  if (!userId) {
    res.status(401).json({ error: "Unauthorized" }); return;
  }
  req.clerkId = userId;

  const claims = auth?.sessionClaims as any;
  let clerkEmail = claims?.email || claims?.email_address || claims?.primary_email_address || null;
  let clerkFirstName = claims?.firstName || claims?.first_name || null;
  let clerkLastName = claims?.lastName || claims?.last_name || null;

  if (!clerkEmail) {
    try {
      const client = clerkClient;
      const clerkUser = await client.users.getUser(userId as string);
      clerkEmail = clerkUser.emailAddresses?.[0]?.emailAddress || null;
      if (!clerkFirstName) clerkFirstName = clerkUser.firstName || null;
      if (!clerkLastName) clerkLastName = clerkUser.lastName || null;
    } catch (e) {}
  }

  const adminEmails = new Set(
    (process.env.ADMIN_EMAILS || process.env.ADMIN_EMAIL || "greg@cookemedia.io")
      .split(",")
      .map((e) => e.trim().toLowerCase())
      .filter(Boolean),
  );
  const isAdminEmail = (e: string | null | undefined) => !!e && adminEmails.has(e.toLowerCase());

  const portalKeyForReq = getPortalKey(req);
  let [user] = await db.select().from(portalUsersTable).where(eq(portalUsersTable.clerkId, userId as string));
  if (!user) {
    const email = clerkEmail || `${userId}@portal.local`;
    const adminUser = isAdminEmail(email);
    // Task #505: shared lower(email)-aware upsert so a pre-existing
    // CSV-grant ghost row gets its clerk_id attached instead of producing
    // a duplicate portal_users row (Cassie's id 65 + id 132 pair).
    user = await ensurePortalUserForClerk({
      clerkId: userId as string,
      email,
      firstName: clerkFirstName,
      lastName: clerkLastName,
      portalKey: portalKeyForReq,
      isAdmin: adminUser,
    });
  } else {
    const updates: any = { lastLoginAt: new Date() };
    if (clerkEmail && user.email.endsWith("@portal.local")) {
      updates.email = clerkEmail;
    }
    const effectiveEmail = (clerkEmail || user.email || "").toLowerCase();
    if (isAdminEmail(effectiveEmail)) {
      if (user.role !== "admin") updates.role = "admin";
      if (!user.isActive) updates.isActive = true;
      if (!user.isAList) {
        updates.isAList = true;
        updates.aListJoinedAt = user.aListJoinedAt || new Date();
      }
    }
    await db.update(portalUsersTable).set(updates).where(eq(portalUsersTable.id, user.id));
    user = { ...user, ...updates };
  }

  req.portalUser = user;

  // Task #710: super-admin "view as user" swap (mirrors the shared
  // middlewares/requireAuth.ts hook). The portal-local requireAuth runs
  // its own portalUser lookup, so we must also evaluate the impersonation
  // header here. If a valid X-Impersonate-Session is attached and the
  // caller is the admin who started the session, swap req.portalUser to
  // the target. Write requests are blocked with 403 (read-only).
  try {
    // Task #796: impersonation is gated by the `users.impersonate`
    // capability, not the bare super-admin allowlist. Super-admins and
    // role==="admin" hold every capability implicitly; a "team" member
    // holds it only when it is in their granular `permissions` list. This
    // mirrors the shared middlewares/requireAuth.ts hook so a permitted
    // team member's "view as user" session resolves identically on the
    // portal-local routes (otherwise they could start a session but get
    // 403'd on every read). The portal-local requireAuth does not populate
    // req.appUser, so we derive super-admin from the Clerk-resolved email.
    const callerEmailForGate = (clerkEmail || user.email || "").toLowerCase();
    const callerIsSuperAdmin = isAdminEmail(callerEmailForGate);
    const callerMayImpersonate = hasCapability(
      user,
      "users.impersonate",
      callerIsSuperAdmin,
    );
    const ctx = await resolveImpersonationContext(
      req,
      userId as string,
      callerMayImpersonate,
    );
    if (ctx) {
      (req as any).impersonator = {
        clerkId: userId as string,
        email: ctx.adminEmail,
        sessionId: ctx.sessionId,
      };
      req.portalUser = ctx.targetPortalUser;
    }
  } catch (err) {
    if (err instanceof ImpersonationForbiddenError) {
      res.status(403).json({
        error: "impersonation_forbidden",
        reason: err.reason,
        message:
          "Your account is not authorized to impersonate other users, or the impersonation session is no longer valid.",
      });
      return;
    }
    console.warn("[portal requireAuth] impersonation resolve failed", err);
  }
  if (shouldBlockImpersonatedWrite(req)) {
    res.status(403).json({
      error: "impersonation_read_only",
      message:
        "This action is disabled while viewing the portal as another user. Click Exit in the gold banner to return to your admin session and try again.",
    });
    return;
  }

  // Task #290: fire a one-time "Welcome to Room30 AI" email the first time
  // an active, non-admin buyer actually signs in. Idempotency is enforced
  // by an atomic UPDATE ... WHERE welcome_email_sent_at IS NULL so racing
  // requests on the same Clerk session can never produce a duplicate.
  // Existing accounts are excluded by the migration's now() backfill.
  if (user.isActive && user.role !== "admin" && !user.welcomeEmailSentAt) {
    void sendWelcomeEmailIfFirstSignIn(user).catch((err) => {
      console.warn("[welcome-email] background dispatch failed", err);
    });
  }

  await db.insert(accessLogsTable).values({
    userId: user.id,
    clerkId: userId as string,
    email: user.email,
    action: `${req.method} ${req.originalUrl}`,
    resourceType: "api",
    resourceId: req.originalUrl,
    ipAddress: getIp(req),
    userAgent: req.headers["user-agent"] || "unknown",
  });

  next();
};

const requireActive = (req: any, res: any, next: any) => {
  if (!req.portalUser?.isActive) {
    res.status(403).json({ error: "Account not activated. Please complete your purchase or use an invite." }); return;
  }
  next();
};

const requireAdmin = (req: any, res: any, next: any) => {
  if (req.portalUser?.role !== "admin") {
    res.status(403).json({ error: "Forbidden" }); return;
  }
  next();
};

// Task #796: gate a staff-reachable endpoint by a single capability. Admins
// and the env-pinned super admin implicitly hold every capability, so this is
// a strict widening of `requireAdmin` for the endpoints team members may use.
// Team-management endpoints (assigning roles / permissions) stay on
// `requireAdmin` so a team member can never escalate their own powers.
const requireCapability =
  (cap: TeamCapability) => (req: any, res: any, next: any) => {
    if (hasCapability(req.portalUser, cap, !!req.appUser?.isSuperAdmin)) {
      next(); return;
    }
    res.status(403).json({ error: "Forbidden" }); return;
  };

// Task #290: send the one-time welcome email the first time a buyer signs
// in. The atomic UPDATE acts as the idempotency lock: the row only matches
// when welcome_email_sent_at is still NULL, so only one concurrent caller
// (across requests, processes, or the api/worker pair) wins the race and
// actually sends. We also re-check role/isActive inside the UPDATE so an
// admin auto-promotion or a deactivation that landed mid-request can't
// produce an unwanted welcome.
async function sendWelcomeEmailIfFirstSignIn(user: {
  id: number;
  email: string;
  firstName: string | null;
}): Promise<void> {
  const claimed = await db
    .update(portalUsersTable)
    .set({ welcomeEmailSentAt: new Date() })
    .where(
      and(
        eq(portalUsersTable.id, user.id),
        isNull(portalUsersTable.welcomeEmailSentAt),
        eq(portalUsersTable.isActive, true),
        ne(portalUsersTable.role, "admin"),
      ),
    )
    .returning({ id: portalUsersTable.id });
  if (claimed.length === 0) return;

  const baseUrl = getBrandBaseUrl();
  const dashboardUrl = `${baseUrl}/members/dashboard`;
  const firstName = (user.firstName || "").trim();
  const greeting = firstName ? `Welcome, ${firstName}.` : "Welcome to AI Influencer Portfolio.";

  const text = [
    greeting,
    "",
    "Your account is live and your training is unlocked. Inside the members portal you will find:",
    "",
    "  - The AI Influencer Portfolio masterclass, broken into bite-sized lessons.",
    "  - Your AI Influencer build with the tools to generate, edit and publish.",
    "  - AI + human support whenever you get stuck.",
    "",
    "Jump straight to your dashboard and start lesson one:",
    dashboardUrl,
    "",
    "If you ever need a hand, just reply to this email and we will sort it out.",
    "",
    "The AI Influencer Portfolio team",
  ].join("\n");

  const html = `
    <p style="margin:0 0 18px 0;">${escapeHtmlSafe(greeting)}</p>
    <p style="margin:0 0 18px 0;">Your account is live and your training is unlocked. Inside the members portal you will find:</p>
    <ul style="margin:0 0 22px 22px;padding:0;color:#E8E8E8;">
      <li style="margin:0 0 8px 0;">The AI Influencer Portfolio masterclass, broken into bite-sized lessons.</li>
      <li style="margin:0 0 8px 0;">Your AI Influencer build with the tools to generate, edit and publish.</li>
      <li style="margin:0 0 8px 0;">AI + human support whenever you get stuck.</li>
    </ul>
    <p style="margin:0 0 26px 0;">Jump straight to your dashboard and start lesson one.</p>
    <p style="margin:0 0 26px 0;">
      <a href="${escapeHtmlSafe(dashboardUrl)}" style="display:inline-block;background:#C9A44C;color:#0A0A0A;font-family:Helvetica,Arial,sans-serif;font-size:13px;letter-spacing:0.18em;text-transform:uppercase;font-weight:bold;text-decoration:none;padding:14px 26px;border-radius:8px;">Open my dashboard</a>
    </p>
    <p style="margin:0;color:rgba(255,255,255,0.55);font-size:13px;">If you ever need a hand, just reply to this email and we will sort it out.</p>
  `.trim();

  try {
    await sendEmail({
      userId: user.id,
      email: user.email,
      subject: "Welcome to AI Influencer Portfolio",
      body: text,
      bodyHtml: html,
      templateType: "portal_welcome",
      metadata: { trigger: "first_sign_in" },
    });
  } catch (err) {
    // The UPDATE has already marked the row as sent. We accept the (rare)
    // failed-send case rather than risk duplicate emails on retry; the
    // failure is logged inside sendEmail() and surfaced in email_logs.
    console.warn("[welcome-email] sendEmail threw", err);
  }
}

