portalRouter.get("/portal/me", requireAuth, async (req: any, res) => {
  const user = req.portalUser;
  const [progressCount] = await db.select({ count: count() }).from(lessonProgressTable).where(and(eq(lessonProgressTable.userId, user.id), eq(lessonProgressTable.completed, true)));
  const [totalLessons] = await db.select({ count: count() }).from(lessonsTable);
  const entitlements = await computePurchaseEntitlements(user);
  // isSuperAdmin is the env-pinned ADMIN_EMAILS owner flag (currently
  // greg@cookemedia.io). The portal "admin" role can be granted to
  // others, but only the super admin can grant the admin role itself.
  // The frontend reads this to decide whether to enable the Admin role
  // button in Manage Users.
  // Task #796: effective capability set. Admins / super-admin hold all;
  // team members hold their sanitized `permissions`; students hold none.
  // The frontend uses this to decide which admin sections to render and
  // whether to let the user into /admin at all.
  const capabilities = Array.from(
    userCapabilities(user, !!req.appUser?.isSuperAdmin),
  );
  res.json({
    user: {
      ...user,
      ...entitlements,
      isSuperAdmin: !!req.appUser?.isSuperAdmin,
      capabilities,
    },
    progress: {
      completedLessons: progressCount?.count || 0,
      totalLessons: totalLessons?.count || 0,
    },
    research: computeResearchEntitlement(user),
  });
});

// Purchase links for locked upgrade surfaces (Task #7). Returns a map of
// product slug -> GHL-hosted sales page URL for every ACTIVE product with a
// configured purchase_url. Locked sidebar rows / pages / credit panels look
// up their slug here and open the link in a new tab; entitlements then land
// via the GHL purchase webhook after checkout. Reserved slugs with no
// entitlement mapping of their own: `video-credits`, `influencer-credits`.
portalRouter.get("/portal/purchase-links", requireAuth, async (_req: any, res) => {
  const rows = await db
    .select({ slug: productsTable.slug, purchaseUrl: productsTable.purchaseUrl })
    .from(productsTable)
    .where(and(eq(productsTable.active, true), isNotNull(productsTable.purchaseUrl)));
  const links: Record<string, string> = {};
  for (const r of rows) if (r.purchaseUrl) links[r.slug] = r.purchaseUrl;
  res.json({ links });
});

// Server-side rendered VSL Masterclass PDF. The button on the VSL Masterclass
// page links straight to this URL — the browser sends Clerk cookies, we verify
// the user has paid for the VSL Vault add-on (bump1Paid), then return the
// cached PDF as a true file download. No print dialog, no client-side jspdf
// bundle, one click. The PDF is rendered with puppeteer-core driving the
// system Chromium against the same chapter data the React print page uses.
portalRouter.get("/portal/vsl-masterclass.pdf", requireAuth, async (req: any, res) => {
  try {
    const user = req.portalUser;
    const entitlements = await computePurchaseEntitlements(user);
    if (!entitlements.bump1Paid) {
      res.status(403).json({ error: "VSL Vault required to access this download." }); return;
    }
    const { getVslMasterclassPdf } = await import("../lib/vsl-masterclass-pdf");
    const { buffer, hash, cached } = await getVslMasterclassPdf();
    res.setHeader("Content-Type", "application/pdf");
    res.setHeader(
      "Content-Disposition",
      `attachment; filename="vsl-masterclass.pdf"`,
    );
    res.setHeader("Content-Length", String(buffer.length));
    res.setHeader("ETag", `"${hash}"`);
    res.setHeader("X-PDF-Cache", cached ? "HIT" : "MISS");
    // The portal router sets `Cache-Control: no-store` globally — override
    // here so browsers can keep the file in their own cache between clicks.
    res.setHeader("Cache-Control", "private, max-age=300");
    res.removeHeader("Pragma");
    res.removeHeader("Expires");
    res.end(buffer); return;
  } catch (e: any) {
    console.error("[portal] VSL Masterclass PDF render failed:", e?.message || e);
    res.status(500).json({
      error: "Could not generate PDF right now. Please try again or use the Print view.",
    }); return;
  }
});

// Apply the role and per-product grants stored on an invite to a real
// portal_users row. Used both by /portal/admin/invites (when the
// invitee's account already exists) and by /portal/enroll (when the
// invitee finally signs up). Mirrors the synthetic admin-grant order
// row pattern used by PATCH /portal/admin/users/:userId/access so
// computePurchaseEntitlements OR-aggregates these flags with any real
// Whop orders for the same email.
export async function applyInviteEntitlements(
  userId: number,
  email: string,
  role: "student" | "team" | "admin",
  grants: Record<string, boolean> | null,
  accessLevel?: string | null,
  teamRole?: string | null,
  teamPermissions?: TeamCapability[] | null,
): Promise<void> {
  // Update the role on portal_users. Skip if the row already has a
  // higher-tier role (do not silently demote an admin to student via
  // an old invite). Tier order: student < team < admin.
  const tier = (r: string) => (r === "admin" ? 2 : r === "team" ? 1 : 0);
  const [current] = await db
    .select()
    .from(portalUsersTable)
    .where(eq(portalUsersTable.id, userId));
  if (current && tier(role) > tier(current.role || "student")) {
    await db
      .update(portalUsersTable)
      .set({ role, updatedAt: new Date() })
      .where(eq(portalUsersTable.id, userId));
  }

  // Task #796: apply the team preset + capability list. We write these
  // whenever the invite is for the "team" role and the row is now at the
  // team tier (either it was already team, or the role update above just
  // promoted it). This lets a re-invite refresh a team member's
  // capabilities. We deliberately never widen below: a row sitting at the
  // admin tier keeps its implicit full powers and we leave its team
  // columns untouched.
  if (role === "team" && current && tier(current.role || "student") <= 1) {
    await db
      .update(portalUsersTable)
      .set({
        teamRole: teamRole ?? "custom",
        permissions: sanitizeCapabilities(teamPermissions ?? []),
        updatedAt: new Date(),
      })
      .where(eq(portalUsersTable.id, userId));
  }

  // isAList lives directly on portal_users (not on the synthetic order
  // row) because the existing toggleAList endpoint writes there.
  if (grants && grants.isAList === true) {
    await db
      .update(portalUsersTable)
      .set({ isAList: true, updatedAt: new Date() })
      .where(eq(portalUsersTable.id, userId));
  }

  // Per-product grants -> synthetic admin-grant order row.
  if (!grants) return;
  const productKeys = [
    "bump1Paid",
    "bump2Paid",
    "bump3Paid",
    "upsell1Paid",
    "upsell2Paid",
    "upsell3Paid",
    "downsell1Paid",
    // New sidebar add-on flags. Admins can comp these via invite or the
    // access toggles even before pricing is wired in.
    "tiktokSlideshowPaid",
    "hookDemoPaid",
    "doneForYouPackPaid",
    "portfolioPaid",
    "platinumPaid",
  ] as const;
  const productPatch: Record<string, boolean> = {};
  for (const k of productKeys) {
    if (grants[k] === true) productPatch[k] = true;
  }
  if (Object.keys(productPatch).length === 0) return;

  const syntheticId = `admin-grant-${userId}`;
  const [existing] = await db
    .select()
    .from(ordersTable)
    .where(eq(ordersTable.id, syntheticId));
  if (existing) {
    await db
      .update(ordersTable)
      .set({ ...productPatch, updatedAt: new Date() })
      .where(eq(ordersTable.id, syntheticId));
  } else {
    await db.insert(ordersTable).values({
      id: syntheticId,
      email,
      currentStep: "admin-granted",
      mainProductPaid: false,
      ...productPatch,
    });
  }

}

export async function computePurchaseEntitlements(user: any): Promise<{
  hasMarketingTool: boolean;
  mainProductPaid: boolean;
  bump1Paid: boolean;
  bump2Paid: boolean;
  bump3Paid: boolean;
  upsell1Paid: boolean;
  upsell2Paid: boolean;
  upsell3Paid: boolean;
  downsell1Paid: boolean;
  // New paid-upsell entitlements surfaced in the Room30 Portal sidebar.
  // Until pricing/Stripe is wired in these are admin-only or manual-grant
  // only — the portal charge-addon endpoint refuses new slugs.
  tiktokSlideshowPaid: boolean;
  hookDemoPaid: boolean;
  doneForYouPackPaid: boolean;
  portfolioPaid: boolean;
  platinumPaid: boolean;
  // Task #283 / #718: number of bonus AR influencer generations the buyer
  // is entitled to on top of the 1 free build everyone gets. +5 per paid
  // "extra influencers" SKU (currently upsell2 = VSL Templates Pack, and
  // portfolio = Our Portfolio add-on). Stacks across SKUs. Total cap =
  // 1 + bonusInfluencerQuota.
  bonusInfluencerQuota: number;
  whopUserId: string | null;
}> {
  const isAdmin = user?.role === "admin";
  const empty = {
    hasMarketingTool: isAdmin,
    mainProductPaid: isAdmin,
    bump1Paid: isAdmin,
    bump2Paid: isAdmin,
    bump3Paid: isAdmin,
    upsell1Paid: isAdmin,
    upsell2Paid: isAdmin,
    upsell3Paid: isAdmin,
    downsell1Paid: isAdmin,
    tiktokSlideshowPaid: isAdmin,
    hookDemoPaid: isAdmin,
    doneForYouPackPaid: isAdmin,
    portfolioPaid: isAdmin,
    platinumPaid: isAdmin,
    // Task #718: admins are treated as if they hold every paid
    // "extras" SKU (upsell2 + portfolio = +10), matching the real
    // branch below so admin previews of the page agree with the paid
    // cap. SKUs audited and excluded as NOT promising extra influencers:
    // bump1/bump2/bump3, upsell1, upsell3, downsell1, tiktokSlideshow,
    // hookDemo, doneForYouPack, platinum. Re-audit before changing.
    bonusInfluencerQuota: computeBonusInfluencerQuota({
      isAdmin,
      bonusInfluencerQuota: user?.bonusInfluencerQuota,
    }),
    whopUserId: null as string | null,
  };
  if (!user || !user.email) return empty;
  // Case-insensitive match - portal_users.email is always lowercased at
  // setup-account time, but legacy orders.email rows from before the
  // funnel insert was normalised may be mixed-case. Without lower(),
  // those buyers log in and see zero entitlements.
  const normEmail = String(user.email).trim().toLowerCase();
  // Task #730: verified-email fan-out. A buyer may have paid orders
  // (or an admin-grant row) keyed under a Clerk-verified email that is
  // not currently `portal_users.email` (Clerk email rename, secondary
  // verified email added later, duplicate portal_users row stamped
  // with the old address, etc). Pull every verified email from Clerk
  // and OR them into the match so those orders still surface. Failure
  // is silent - if Clerk is unreachable we just fall back to the
  // primary-email match below.
  const emailSet = new Set<string>([normEmail]);
  if (user.clerkId) {
    try {
      const cu: any = await (clerkClient as any).users.getUser(user.clerkId);
      const addrs: any[] = Array.isArray(cu?.emailAddresses)
        ? cu.emailAddresses
        : [];
      for (const a of addrs) {
        const verified = !!a?.verification?.status?.startsWith?.("verified");
        if (!verified) continue;
        const v = (a?.emailAddress || "").trim().toLowerCase();
        if (v) emailSet.add(v);
      }
    } catch {
      // ignore - keep primary-email-only match
    }
  }
  const emailList = Array.from(emailSet).filter((e) => e.length > 0);
  // Belt-and-braces (Jess / David / Eimy / Olli lockout bug, Nov 2026):
  // also OR-in the synthetic admin-grant row by id. The PATCH
  // /portal/admin/users/:userId/access endpoint upserts a row with
  // id=`admin-grant-<userId>` whose `email` column is stamped from
  // portal_users.email at grant time. If portal_users.email later
  // diverges from the buyer's actual sign-in email (Clerk email rename,
  // legacy lowercase normalisation, duplicate portal_users row, or a
  // grant performed against a sibling row), the lower(email)=lower(email)
  // join silently misses the synthetic row and the buyer sees locked
  // content despite the admin panel showing every flag as true. Adding
  // the id-keyed OR makes admin grants apply unconditionally as long as
  // we hold the user's portal_users.id - which is exactly what
  // /portal/me has via req.portalUser.
  const syntheticGrantId =
    typeof user.id === "number" ? `admin-grant-${user.id}` : null;
  const emailClause =
    emailList.length > 1
      ? sql`lower(${ordersTable.email}) IN (${sql.join(
          emailList.map((e) => sql`${e}`),
          sql`, `,
        )})`
      : sql`lower(${ordersTable.email}) = ${normEmail}`;
  const orders = await db
    .select()
    .from(ordersTable)
    .where(
      syntheticGrantId
        ? or(emailClause, eq(ordersTable.id, syntheticGrantId))
        : emailClause,
    );
  if (orders.length === 0) return empty;
  const any = (k: keyof typeof orders[number]) => orders.some((o: any) => o[k] === true);
  const customer = orders.find((o: any) => !!o.whopUserId)?.whopUserId || null;
  return {
    hasMarketingTool: isAdmin || any("upsell1Paid"),
    mainProductPaid: isAdmin || any("mainProductPaid"),
    // bump1 (legacy $47 VSL Vault bump) and upsell2 (current $297 5x VSL
    // Templates Pack) deliver the same product. Either purchase unlocks the
    // VSL Templates Pack and VSL Masterclass entitlement everywhere
    // downstream (sidebar, page gates, masterclass PDF endpoint).
    bump1Paid: isAdmin || any("bump1Paid") || any("upsell2Paid"),
    bump2Paid: isAdmin || any("bump2Paid"),
    bump3Paid: isAdmin || any("bump3Paid"),
    upsell1Paid: isAdmin || any("upsell1Paid"),
    upsell2Paid: isAdmin || any("upsell2Paid"),
    upsell3Paid: isAdmin || any("upsell3Paid"),
    downsell1Paid: isAdmin || any("downsell1Paid"),
    tiktokSlideshowPaid: isAdmin || any("tiktokSlideshowPaid"),
    hookDemoPaid: isAdmin || any("hookDemoPaid"),
    doneForYouPackPaid:
      isAdmin || any("doneForYouPackPaid") || any("upsell1Paid") || any("downsell1Paid"),
    portfolioPaid: isAdmin || any("portfolioPaid") || any("upsell2Paid"),
    platinumPaid: isAdmin || any("platinumPaid") || any("upsell3Paid"),
    // Task #283 / #718: each paid "extra influencers" SKU grants +5 AR
    // influencer generations on top of the 1 free build, and SKUs stack:
    //   - upsell2 (VSL Templates Pack) → +5
    //   - portfolio (Our Portfolio add-on) → +5
    //   - admin override / Buyer Access stamp (portal_users.bonus_influencer_quota) → +N
    // Admins are treated as if they hold every "extras" SKU.
    // SKUs audited and excluded as NOT promising extra influencers:
    // bump1/bump2/bump3, upsell1, upsell3, downsell1, tiktokSlideshow,
    // hookDemo, doneForYouPack, platinum. If any of those start
    // promising extras, sum them here so the cap stays in one place.
    bonusInfluencerQuota: computeBonusInfluencerQuota({
      isAdmin,
      upsell2Paid: any("upsell2Paid"),
      portfolioPaid: any("portfolioPaid"),
      bonusInfluencerQuota: user?.bonusInfluencerQuota,
    }),
    whopUserId: customer,
  };
}

export async function computeMarketingToolEntitlement(user: any): Promise<boolean> {
  const e = await computePurchaseEntitlements(user);
  return e.hasMarketingTool;
}

