// Returns whether the current portal user has an existing booking on the
// 1-on-1 Strategy Call event in Calendly. Used by the strategy-call page to
// (a) hide the inline widget if they've already booked, and (b) enforce the
// "one booking per member, ever" cap by counting both active AND canceled
// scheduled events. Admins are always treated as not-booked so Greg can keep
// testing the embedded widget.
// We accept the strategy call event type secret as either:
//  - A full canonical URI:  https://api.calendly.com/event_types/<uuid>
//  - A slug:                1-1-call-with-greg-limited-exclusive-offer
// The Calendly API requires the canonical URI for scheduled_events filtering,
// so when the secret is a slug we resolve it once per process by listing the
// authenticated user's event types and matching by slug. Both the resolved
// URI and the resulting scheduling URL are cached for the lifetime of the
// process.
let cachedEventTypeUri: string | null = null;
let cachedSchedulingUrl: string | null = null;

async function resolveStrategyCallEventType(
  token: string,
  rawValue: string,
): Promise<{ uri: string | null; schedulingUrl: string | null }> {
  if (cachedEventTypeUri) {
    return { uri: cachedEventTypeUri, schedulingUrl: cachedSchedulingUrl };
  }

  const headers = { Authorization: `Bearer ${token}` };
  const isFullUri = /^https?:\/\/api\.calendly\.com\/event_types\//.test(rawValue);

  try {
    if (isFullUri) {
      const r = await fetch(rawValue, { headers });
      if (!r.ok) return { uri: null, schedulingUrl: null };
      const data: any = await r.json();
      cachedEventTypeUri = data?.resource?.uri || rawValue;
      cachedSchedulingUrl = data?.resource?.scheduling_url || null;
      return { uri: cachedEventTypeUri, schedulingUrl: cachedSchedulingUrl };
    }

    // Treat the value as a slug: look up the authenticated user, then list
    // their event types and find the one whose slug matches.
    const meRes = await fetch("https://api.calendly.com/users/me", { headers });
    if (!meRes.ok) return { uri: null, schedulingUrl: null };
    const me: any = await meRes.json();
    const userUri = me?.resource?.uri;
    if (!userUri) return { uri: null, schedulingUrl: null };

    const listUrl = new URL("https://api.calendly.com/event_types");
    listUrl.searchParams.set("user", userUri);
    listUrl.searchParams.set("count", "100");
    const listRes = await fetch(listUrl.toString(), { headers });
    if (!listRes.ok) return { uri: null, schedulingUrl: null };
    const list: any = await listRes.json();
    const collection: any[] = Array.isArray(list?.collection) ? list.collection : [];
    const match = collection.find((e: any) => e?.slug === rawValue);
    if (!match) {
      console.warn(
        `[strategy-call] no Calendly event type with slug "${rawValue}" found for current user`,
      );
      return { uri: null, schedulingUrl: null };
    }
    cachedEventTypeUri = match.uri || null;
    cachedSchedulingUrl = match.scheduling_url || null;
    return { uri: cachedEventTypeUri, schedulingUrl: cachedSchedulingUrl };
  } catch (e) {
    console.warn("[strategy-call] resolveStrategyCallEventType failed", e);
    return { uri: null, schedulingUrl: null };
  }
}

portalRouter.get("/portal/strategy-call/booking-status", requireAuth, async (req: any, res) => {
  const user = req.portalUser;
  const isAdmin = user?.role === "admin";

  const token = process.env.CALENDLY_API_TOKEN;
  const rawEventType = process.env.CALENDLY_STRATEGY_CALL_EVENT_TYPE_URI;
  if (!token || !rawEventType) {
    console.warn(
      "[strategy-call] CALENDLY_API_TOKEN or CALENDLY_STRATEGY_CALL_EVENT_TYPE_URI not configured; failing open.",
    );
    res.json({
      hasBooking: false,
      booking: null,
      schedulingUrl: null,
      apiError: true,
    }); return;
  }

  // Resolve the canonical event type URI (and its scheduling URL) up front so
  // the widget always has a target, regardless of whether the user has booked
  // or is an admin.
  const { uri: eventTypeUri, schedulingUrl } = await resolveStrategyCallEventType(
    token,
    rawEventType,
  );

  if (!eventTypeUri) {
    console.warn(
      "[strategy-call] could not resolve event type URI from CALENDLY_STRATEGY_CALL_EVENT_TYPE_URI; failing open.",
    );
    res.json({
      hasBooking: false,
      booking: null,
      schedulingUrl,
      apiError: true,
    }); return;
  }

  if (isAdmin) {
    res.json({
      hasBooking: false,
      booking: null,
      schedulingUrl,
      isAdmin: true,
    }); return;
  }

  if (!user?.email) {
    res.json({ hasBooking: false, booking: null, schedulingUrl }); return;
  }

  const headers = {
    Authorization: `Bearer ${token}`,
    "Content-Type": "application/json",
  } as const;

  // Calendly returns scheduled events filtered by invitee email + event type.
  // We have to ask twice — once for active and once for canceled — because
  // cancelled bookings should still count toward the one-booking-ever cap.
  const fetchEvents = async (status: "active" | "canceled") => {
    const url = new URL("https://api.calendly.com/scheduled_events");
    url.searchParams.set("invitee_email", user.email);
    url.searchParams.set("event_type", eventTypeUri);
    url.searchParams.set("status", status);
    url.searchParams.set("count", "10");
    url.searchParams.set("sort", "start_time:desc");
    const r = await fetch(url.toString(), { headers });
    if (!r.ok) {
      const body = await r.text().catch(() => "");
      throw new Error(`Calendly scheduled_events ${status} ${r.status}: ${body.slice(0, 200)}`);
    }
    const data: any = await r.json();
    return Array.isArray(data?.collection) ? data.collection : [];
  };

  try {
    const [active, canceled] = await Promise.all([
      fetchEvents("active"),
      fetchEvents("canceled"),
    ]);
    const all = [...active, ...canceled];
    if (all.length === 0) {
      res.json({ hasBooking: false, booking: null, schedulingUrl }); return;
    }

    // Prefer an active booking over a canceled one when surfacing the
    // confirmation panel. Within each group we already sort by start_time desc
    // so the most recent wins.
    const chosen = active[0] || canceled[0];
    const eventUri: string = chosen?.uri || "";

    let rescheduleUrl: string | null = null;
    let cancelUrl: string | null = null;

    // The reschedule/cancel URLs live on the invitee record, not the
    // scheduled_event itself. Fetch the first invitee to surface them.
    if (eventUri) {
      try {
        const inviteesUrl = `${eventUri}/invitees`;
        const ir = await fetch(inviteesUrl, { headers });
        if (ir.ok) {
          const idata: any = await ir.json();
          const invitee = Array.isArray(idata?.collection) ? idata.collection[0] : null;
          rescheduleUrl = invitee?.reschedule_url || null;
          cancelUrl = invitee?.cancel_url || null;
        }
      } catch (e) {
        // Non-fatal: still show the confirmation, just without management links.
        console.warn("[strategy-call] failed to fetch invitee details", e);
      }
    }

    res.json({
      hasBooking: true,
      schedulingUrl,
      booking: {
        startTime: chosen?.start_time || null,
        endTime: chosen?.end_time || null,
        eventUri,
        rescheduleUrl,
        cancelUrl,
        status: chosen?.status || (active.length > 0 ? "active" : "canceled"),
      },
    }); return;
  } catch (err: any) {
    console.error("[strategy-call] Calendly API error:", err?.message || err);
    res.json({
      hasBooking: false,
      booking: null,
      schedulingUrl,
      apiError: true,
    }); return;
  }
});

// 1-1 Onboarding Call (GHL booking widget eUBO2GGTIzk59M2DGrN1).
//
// `shouldPrompt` drives the one-time first-login popup: it only fires for
// brand-new buyers (created on/after the launch cutoff) who have neither
// dismissed the popup before nor already booked. Existing accounts are
// excluded purely by the createdAt cutoff - no backfill migration needed.
//
// `hasBooked` is cached permanently onto portal_users.onboarding_call_booked_at
// the first time GHL reports a live booking, so the sidebar link and the
// repeat-booking guard never need another GHL round-trip for that buyer.
const ONBOARDING_CALL_LAUNCH_CUTOFF_MS = Date.parse("2026-06-03T00:00:00Z");

portalRouter.get("/portal/onboarding-call/status", requireAuth, async (req: any, res) => {
  const user = req.portalUser;
  const isAdmin = user?.role === "admin";
  const configured = ghlConfigured();
  const bookingUrl = ONBOARDING_CALL_BOOKING_URL;
  const promptSeen = !!user?.onboardingCallPromptSeenAt;

  // Already cached as booked - short-circuit, no GHL call.
  if (user?.onboardingCallBookedAt) {
    res.json({
      configured,
      hasBooked: true,
      shouldPrompt: false,
      bookingUrl,
      promptSeen,
      apiError: false,
    });
    return;
  }

  let hasBooked = false;
  let apiError = false;
  if (configured && !isAdmin && user?.email) {
    const result = await hasBookedOnboardingCall(user.email);
    hasBooked = result.hasBooked;
    apiError = result.error;
    if (hasBooked && user?.id) {
      // Cache permanently so future loads skip GHL entirely.
      try {
        await db
          .update(portalUsersTable)
          .set({ onboardingCallBookedAt: new Date() })
          .where(
            and(
              eq(portalUsersTable.id, user.id),
              isNull(portalUsersTable.onboardingCallBookedAt),
            ),
          );
      } catch (err: any) {
        console.warn("[onboarding-call] failed to cache booked state", err?.message || err);
      }
    }
  }

  const createdAtMs = user?.createdAt ? new Date(user.createdAt).getTime() : NaN;
  const isNewUser =
    Number.isFinite(createdAtMs) &&
    Number.isFinite(ONBOARDING_CALL_LAUNCH_CUTOFF_MS) &&
    createdAtMs >= ONBOARDING_CALL_LAUNCH_CUTOFF_MS;
  const shouldPrompt = configured && !isAdmin && isNewUser && !promptSeen && !hasBooked;

  res.json({ configured, hasBooked, shouldPrompt, bookingUrl, promptSeen, apiError });
});

// Atomically stamp that the one-time first-login onboarding-call popup has
// been shown so it never auto-fires again. WHERE ... IS NULL preserves the
// first-seen timestamp across racing requests on the same session.
portalRouter.post("/portal/onboarding-call/prompt-seen", requireAuth, async (req: any, res) => {
  const user = req.portalUser;
  if (user?.id) {
    try {
      await db
        .update(portalUsersTable)
        .set({ onboardingCallPromptSeenAt: new Date() })
        .where(
          and(
            eq(portalUsersTable.id, user.id),
            isNull(portalUsersTable.onboardingCallPromptSeenAt),
          ),
        );
    } catch (err: any) {
      console.warn("[onboarding-call] failed to mark prompt seen", err?.message || err);
    }
  }
  res.json({ ok: true });
});

// Live Whop verification fallback for the post-purchase /thankyou setup
// flow (Task #456). When the Whop webhook hasn't arrived yet, or it
// arrived with a drifted plan id (e.g. Whop mints a discounted plan id
// when MAY2026 promo is applied inside the iframe so the saved
// `whop_bundle_plan_id` no longer matches), `mainProductPaid` stays
// false and `/portal/setup-account` would 403 a paying customer.
//
// This helper asks Whop directly. It tries, in order:
//   1. `getReceipt(order.whopReceiptId)` if a receipt id is stored.
//   2. `listReceipts({ status: "paid" })` over a window starting at
//      `order.createdAt`, scanning a few pages and matching on
//      `metadata.orderId === order.id`.
//
// If a paid receipt is found, the order row is back-filled with
// `mainProductPaid = true`, the discovered `whopReceiptId`,
// `whopUserId`, and (when missing) `totalAmount`. When the matched plan
// is a dynamic bundle plan (not in WHOP_PRODUCTS), each selected bump
// in `productSlugs` is also flipped paid so the buyer's entitlements
// match what they were charged. Finally `enrollPurchaserAndSendEmail`
// fires (idempotent on email+orderId) so the buyer still gets the
// canonical "set your password" mail.
//
// Returns the updated order row on success, or null when verification
// failed (genuine no-purchase case, transient Whop outage, etc.).
async function tryVerifyOrderPaidWithWhop(
  _order: typeof ordersTable.$inferSelect,
  _log?: any,
): Promise<typeof ordersTable.$inferSelect | null> {
  // The live-Whop verification fallback (getReceipt / listReceipts) is
  // retired with the legacy purchasing stack. Order paid-state is now the
  // source of truth (written by the GoHighLevel purchase flows), so this
  // self-heal path is a no-op.
  return null;
}

// Public endpoint used by the post-purchase /thankyou page.
// Creates a Clerk account with email + password (gated by a paid order),
// then returns a one-time sign-in ticket so the customer lands directly
// in /portal/dashboard already authenticated.
portalRouter.post("/portal/setup-account", async (req: any, res) => {
  try {
    const password = typeof req.body?.password === "string" ? req.body.password : "";
    const oid = typeof req.body?.oid === "string" ? req.body.oid.trim() : null;
    const clientEmail = typeof req.body?.email === "string" ? req.body.email.trim().toLowerCase() : "";

    if (!password || password.length < 8) {
      res.status(400).json({ error: "invalid_password", message: "Password must be at least 8 characters." }); return;
    }

    // Resolve the order row from the order id (the public order endpoint
    // intentionally does not return email to avoid PII exposure). The oid
    // is the canonical identifier minted at checkout, so we trust the
    // database row over any client-supplied email.
    //
    // We deliberately accept a row whose `mainProductPaid` is still false
    // here so the live-Whop verification fallback (Task #456) below has a
    // chance to run. The fallback flips the flag if Whop confirms the
    // buyer actually paid; only after that fallback also fails do we
    // return a 403 to the buyer.
    let order: typeof ordersTable.$inferSelect | undefined;
    if (oid) {
      const [row] = await db.select().from(ordersTable).where(eq(ordersTable.id, oid));
      if (row) order = row;
    }
    // Fallback: legacy callers that still pass an email but no oid.
    if (!order && clientEmail && /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(clientEmail)) {
      const candidates = await db
        .select()
        .from(ordersTable)
        .where(sql`lower(${ordersTable.email}) = ${clientEmail}`);
      // Prefer a paid row; otherwise the most recently-created candidate so
      // the live-Whop fallback can verify it.
      order =
        candidates.find((o) => o.mainProductPaid) ||
        candidates
          .slice()
          .sort(
            (a, b) =>
              (b.createdAt?.getTime?.() ?? 0) - (a.createdAt?.getTime?.() ?? 0),
          )[0] ||
        undefined;
    }
    // The legacy Whop-based self-heal fallbacks (free-promo reconcile and
    // email-only membership minting) are retired with the purchasing
    // stack. Order paid-state is now the source of truth (written by the
    // GoHighLevel purchase flows), so no live-provider lookup runs here.
    const whopOnlyLookupSummary: null = null;

    if (!order) {
      // Task #483: the bare "no_paid_order" copy is the customer-visible
      // signature we are trying to eliminate. We still emit a structured
      // log line so we can confirm in production how often this branch
      // fires (and which inputs reach it), and we still keep the
      // `no_paid_order` error code so tests / clients can branch on it,
      // but the message itself is always the friendlier
      // payment_pending_verification copy so the buyer never sees the
      // bare "contact support" string again.
      // Pull a small, PII-light summary of every candidate row we
      // considered (oid lookup + email lookup) so we can tell from logs
      // alone whether the buyer hit the no-row branch because no row
      // exists at all, or because a row exists but is unpaid in a way
      // even the live-Whop and email-only fallbacks could not recover.
      let candidateSummary: Array<{
        id: string;
        mainProductPaid: boolean | null;
        currentStep: string | null;
        hasReceiptId: boolean;
        hasBundlePlan: boolean;
        createdAt: string | null;
      }> = [];
      try {
        const rows: typeof ordersTable.$inferSelect[] = [];
        if (oid) {
          const [byOid] = await db.select().from(ordersTable).where(eq(ordersTable.id, oid));
          if (byOid) rows.push(byOid);
        }
        if (clientEmail && /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(clientEmail)) {
          const byEmail = await db
            .select()
            .from(ordersTable)
            .where(sql`lower(${ordersTable.email}) = ${clientEmail}`);
          rows.push(...byEmail);
        }
        const seen = new Set<string>();
        candidateSummary = rows
          .filter((r) => {
            if (seen.has(r.id)) return false;
            seen.add(r.id);
            return true;
          })
          .slice(0, 10)
          .map((r) => ({
            id: r.id,
            mainProductPaid: r.mainProductPaid ?? null,
            currentStep: r.currentStep ?? null,
            hasReceiptId: !!r.whopReceiptId,
            hasBundlePlan: !!r.whopBundlePlanId,
            createdAt: r.createdAt ? new Date(r.createdAt).toISOString() : null,
          }));
      } catch {
        // best-effort: diagnostics must never fail the request
      }
      req.log?.warn?.(
        {
          oidPresent: !!oid,
          emailPresent: !!clientEmail,
          oid: oid || null,
          email: clientEmail || null,
          query: req.query || null,
          userAgent: req.headers?.["user-agent"] || null,
          referrer: req.headers?.referer || req.headers?.referrer || null,
          candidateCount: candidateSummary.length,
          candidates: candidateSummary,
          whopOnlyLookup: whopOnlyLookupSummary,
        },
        "[setup-account] no-order-row reached",
      );
      const identifier = oid || clientEmail || "(unknown)";
      res.status(403).json({
        error: "no_paid_order",
        orderId: oid || null,
        message:
          "We could not find a paid order for you yet. If you just completed checkout, give it a moment and try again. If it still does not let you in, reach out through the support chat with your order id " +
          identifier +
          " and we will get you in within minutes.",
      });
      return;
    }

    // Live payment-provider verification fallbacks (Stripe PI retrieve /
    // Whop receipt lookup) are retired with the legacy purchasing stack.
    // Order paid-state is now the source of truth, written by the
    // GoHighLevel purchase flows before the buyer reaches this endpoint.

    // Live Whop verification fallback (Task #456). When the webhook has
    // not landed yet, or it fired with a drifted plan id (MAY2026 promo
    // -> Whop mints a discounted plan id that no longer matches our
    // saved bundle plan), `mainProductPaid` is still false at the
    // moment the buyer hits this endpoint. Before returning a 403 we
    // ask Whop directly whether the order has a paid receipt and, if
    // so, back-fill the row and continue as if the webhook had run.
    if (!order.mainProductPaid) {
      const verified = await tryVerifyOrderPaidWithWhop(order, req.log);
      if (verified) {
        order = verified;
      } else {
        const promoOnOrder = ((order.productSlugs || "") as string)
          .split(",")
          .map((s) => s.trim())
          .find((s) => /^promo:/i.test(s)) || null;
        req.log?.warn?.(
          {
            orderId: order.id,
            promo: promoOnOrder,
            hasReceiptId: !!order.whopReceiptId,
            hasBundlePlan: !!order.whopBundlePlanId,
          },
          "[setup-account] live-whop fallback could not verify order; returning friendlier 403",
        );
        res.status(403).json({
          error: "payment_pending_verification",
          orderId: order.id,
          message:
            "We are still confirming your payment. This usually takes only a few seconds - please wait a moment and try again. If it still does not let you in, reach out through the support chat with your order id " +
            order.id +
            " and we will get you in within minutes.",
        });
        return;
      }
    }
    const rawEmail = (order.email || "").trim().toLowerCase();
    if (!rawEmail || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(rawEmail)) {
      res.status(500).json({
        error: "order_missing_email",
        message: "We could not find an email on this order. Please contact support.",
      }); return;
    }

    // With Replit Auth there is no password to set here. We prepare (or
    // refresh) the portal_users shell row for the purchase email; the row is
    // claimed by email the first time the buyer signs in with Replit.
    const [existingRow] = await db
      .select({ id: portalUsersTable.id })
      .from(portalUsersTable)
      .where(sql`lower(${portalUsersTable.email}) = ${rawEmail}`);
    if (existingRow) {
      await db.update(portalUsersTable).set({
        isActive: true,
        orderId: order.id,
        whopUserId: order.whopUserId || null,
        updatedAt: new Date(),
      }).where(eq(portalUsersTable.id, existingRow.id));
    } else {
      await db.insert(portalUsersTable).values({
        email: rawEmail,
        role: "user",
        portalKey: getPortalKey(req),
        isActive: true,
        orderId: order.id,
        whopUserId: order.whopUserId || null,
      });
    }

    // Confirmation email so they always have a way back in
    try {
      await sendEmail({
        email: rawEmail,
        subject: "Your Members Portal Access",
        body: [
          "Welcome to the members portal.",
          "",
          "Sign in with this email: " + rawEmail,
          "Sign in here: /members/sign-in",
          "",
          "Inside you will find the masterclass, your AI Influencer build, and AI + human support.",
          "",
          "If you ever need a hand, just reply to this email and we will sort it out.",
        ].join("\n"),
        templateType: "portal_account_created",
        metadata: { orderId: order.id },
      });
    } catch (e) {
      // Email failures should not block the sign-in flow
      console.warn("[setup-account] confirmation email failed", e);
    }

    // Send buyers to the Clerk sign-in page; their access row is claimed by
    // email the moment they finish authenticating.
    const loginUrl = `/members/sign-in`;

    res.json({
      success: true,
      ticketUrl: loginUrl,
      redirectUrl: loginUrl,
    }); return;
  } catch (e: any) {
    console.error("[setup-account] unexpected error", e?.message || e);
    res.status(500).json({ error: "server_error", message: "Something went wrong. Please try again." }); return;
  }
});

portalRouter.post("/portal/enroll", requireAuth, async (req: any, res) => {
  const user = req.portalUser;
  const email = user.email;

  if (user.isActive) {
    res.json({ enrolled: true, alreadyActive: true }); return;
  }

  const orders = await db.select().from(ordersTable).where(eq(ordersTable.email, email));
  const paidOrder = orders.find((o: any) => o.mainProductPaid);

  if (paidOrder) {
    await db.update(portalUsersTable).set({
      whopUserId: paidOrder.whopUserId,
      orderId: paidOrder.id,
      isActive: true,
      updatedAt: new Date(),
    }).where(eq(portalUsersTable.id, user.id));
    res.json({ enrolled: true, orderId: paidOrder.id }); return;
  }

  // Claim the most recent unclaimed invite for this email AND for the
  // portal the user actually signed up on. The portal_key filter is
  // critical: without it, a Room30 sign-up could claim a pending Apex
  // invite for the same email and inherit Apex grants (or vice versa).
  // Older invites without portal_key default to "main" via the migration.
  const enrollPortalKey = getPortalKey(req);
  const [invite] = await db
    .select()
    .from(invitesTable)
    .where(
      and(
        eq(invitesTable.email, email),
        eq(invitesTable.portalKey, enrollPortalKey),
        ne(invitesTable.status, "claimed"),
      ),
    )
    .orderBy(desc(invitesTable.createdAt))
    .limit(1);
  if (invite) {
    await db.update(invitesTable).set({
      status: "claimed",
      claimedAt: new Date(),
    }).where(eq(invitesTable.id, invite.id));
    await db.update(portalUsersTable).set({
      isActive: true,
      inviteToken: invite.token,
      invitedAt: invite.createdAt,
      updatedAt: new Date(),
    }).where(eq(portalUsersTable.id, user.id));
    // Apply role + per-product grants stored on the invite. Older
    // invites have role=null and grants=null; the helper treats that
    // as "no overrides" (defaults to "student", no extra access).
    await applyInviteEntitlements(
      user.id,
      email,
      ((invite.role as "student" | "team" | "admin") || "student"),
      (invite.grants as Record<string, boolean> | null) || null,
      invite.accessLevel ?? null,
    );
    res.json({ enrolled: true, via: "invite" }); return;
  }

  res.json({ enrolled: false, message: "No purchase or invite found for this email." });
});

portalRouter.get("/portal/course", requireAuth, requireActive, async (req: any, res) => {
  const portalKey = getPortalKey(req);
  const phases = await db.select().from(coursePhasesTable)
    .where(eq(coursePhasesTable.portalKey, portalKey))
    .orderBy(asc(coursePhasesTable.sortOrder));
  const lessons = await db.select().from(lessonsTable)
    .where(eq(lessonsTable.portalKey, portalKey))
    .orderBy(asc(lessonsTable.sortOrder));
  const progress = await db.select().from(lessonProgressTable).where(eq(lessonProgressTable.userId, req.portalUser.id));

  const progressMap = new Map(progress.map(p => [p.lessonId, p]));

  const course = phases.map(phase => ({
    ...phase,
    lessons: lessons.filter(l => l.phaseId === phase.id).map(l => ({
      ...l,
      progress: progressMap.get(l.id) || null,
    })),
  }));

  res.json(course);
});

// Public, token-gated read of a lesson for screenshot capture from the landing page crawler.
// Returns the same payload as the authenticated endpoint but skips access logging and progress.
portalRouter.get("/portal/screenshot/lessons/:slug", async (req: any, res) => {
  const expected = process.env.LESSON_SCREENSHOT_TOKEN;
  const provided = (req.query?.token as string) || (req.headers["x-screenshot-token"] as string);
  if (!expected || !provided || provided !== expected) {
    res.status(401).json({ error: "Unauthorized" }); return;
  }
  const [lesson] = await db.select().from(lessonsTable).where(eq(lessonsTable.slug, req.params.slug));
  if (!lesson) { res.status(404).json({ error: "Lesson not found" }); return; }
  res.json({ lesson, progress: null });
});

// Public, token-gated read of the full course tree (phases + lessons) for the screenshot route's sidebar.
portalRouter.get("/portal/screenshot/course", async (req: any, res) => {
  const expected = process.env.LESSON_SCREENSHOT_TOKEN;
  const provided = (req.query?.token as string) || (req.headers["x-screenshot-token"] as string);
  if (!expected || !provided || provided !== expected) {
    res.status(401).json({ error: "Unauthorized" }); return;
  }
  const portalKey = getPortalKey(req);
  const phases = await db.select().from(coursePhasesTable)
    .where(eq(coursePhasesTable.portalKey, portalKey))
    .orderBy(asc(coursePhasesTable.sortOrder));
  const lessons = await db.select().from(lessonsTable)
    .where(eq(lessonsTable.portalKey, portalKey))
    .orderBy(asc(lessonsTable.sortOrder));
  const course = phases.map(phase => ({
    ...phase,
    lessons: lessons.filter(l => l.phaseId === phase.id).map(l => ({ ...l, completed: false, locked: false })),
  }));
  res.json(course);
});

portalRouter.get("/portal/lessons/:slug", requireAuth, requireActive, async (req: any, res) => {
  // Scope by portal so a course-portal user (no header → 'main') can never
  // resolve a Room30 lesson by guessing its r30- slug, and vice versa.
  const portalKey = getPortalKey(req);
  const requestedSlug = resolveRoom30LessonSlug(req.params.slug, portalKey);
  const [lesson] = await db.select().from(lessonsTable)
    .where(and(eq(lessonsTable.slug, requestedSlug), eq(lessonsTable.portalKey, portalKey)));
  if (!lesson) { res.status(404).json({ error: "Lesson not found" }); return; }

  const [progress] = await db.select().from(lessonProgressTable).where(and(eq(lessonProgressTable.userId, req.portalUser.id), eq(lessonProgressTable.lessonId, lesson.id)));

  await db.insert(accessLogsTable).values({
    userId: req.portalUser.id,
    clerkId: req.clerkId,
    email: req.portalUser.email,
    action: "lesson_view",
    resourceType: "lesson",
    resourceId: lesson.slug,
    resourcePath: `/lesson/${lesson.slug}`,
    ipAddress: getIp(req),
    userAgent: req.headers["user-agent"] || "unknown",
  });

  res.json({ lesson, progress: progress || null });
});

portalRouter.post("/portal/lessons/:slug/progress", requireAuth, requireActive, async (req: any, res) => {
  // Scope by portal so progress writes can never land on the other portal's
  // lesson row (would inflate completion counts in the wrong tenant).
  const portalKey = getPortalKey(req);
  const requestedSlug = resolveRoom30LessonSlug(req.params.slug, portalKey);
  const [lesson] = await db.select().from(lessonsTable)
    .where(and(eq(lessonsTable.slug, requestedSlug), eq(lessonsTable.portalKey, portalKey)));
  if (!lesson) { res.status(404).json({ error: "Lesson not found" }); return; }

  const { completed, actionTaskCompleted, watchTimeSeconds, lastPosition, promptData } = req.body;

  const [existing] = await db.select().from(lessonProgressTable).where(and(eq(lessonProgressTable.userId, req.portalUser.id), eq(lessonProgressTable.lessonId, lesson.id)));

  if (existing) {
    const [updated] = await db.update(lessonProgressTable).set({
      completed: completed ?? existing.completed,
      actionTaskCompleted: actionTaskCompleted ?? existing.actionTaskCompleted,
      watchTimeSeconds: watchTimeSeconds ?? existing.watchTimeSeconds,
      lastPosition: lastPosition ?? existing.lastPosition,
      promptData: promptData ?? existing.promptData,
      completedAt: completed ? new Date() : existing.completedAt,
      updatedAt: new Date(),
    }).where(eq(lessonProgressTable.id, existing.id)).returning();
    res.json(updated); return;
  }

  const [created] = await db.insert(lessonProgressTable).values({
    userId: req.portalUser.id,
    lessonId: lesson.id,
    completed: completed || false,
    actionTaskCompleted: actionTaskCompleted || false,
    watchTimeSeconds: watchTimeSeconds || 0,
    lastPosition: lastPosition || 0,
    promptData: promptData || null,
    completedAt: completed ? new Date() : null,
  }).returning();
  res.json(created);
});

portalRouter.get("/portal/admin/users", requireAuth, requireCapability("users.view"), async (req: any, res) => {
  // Admin views are per-portal: a course-portal admin sees completion stats
  // against the 'main' curriculum; a Room30 admin sees them against the
  // 'room30' curriculum. Without scoping, totals and percentages would mix
  // both portals' lessons together and read as nonsense in either UI.
  const portalKey = getPortalKey(req);
  // Room30 admins see every portal user across portals so the Room30
  // owner can manage the whole customer base from one screen. Apex
  // Offers / other portal admins stay scoped to their own portal so
  // they don't see unrelated buyers. Per-portal totals (lesson
  // completion) below remain scoped to the viewing portal, so a user
  // from another portal correctly shows 0 progress against this
  // portal's curriculum -- their portalKey is included on the row so
  // the UI can badge it.
  // Only the env-pinned Room30 super admin can see users from every
  // portal in one list. A regular Room30 admin (i.e. someone the super
  // admin granted the Admin role to) stays scoped to their own portal
  // so they cannot manage unrelated customers. Per-user admin
  // endpoints below enforce the same rule, so a row the list returns
  // is always a row the same caller is allowed to open.
  const canSeeAllPortals = portalKey === "room30" && !!req.appUser?.isSuperAdmin;
  const users = canSeeAllPortals
    ? await db.select().from(portalUsersTable).orderBy(desc(portalUsersTable.createdAt))
    : await db
        .select()
        .from(portalUsersTable)
        .where(eq(portalUsersTable.portalKey, portalKey))
        .orderBy(desc(portalUsersTable.createdAt));

  const allProgress = await db.select({
    userId: lessonProgressTable.userId,
    completedCount: count(),
  })
    .from(lessonProgressTable)
    .innerJoin(lessonsTable, eq(lessonProgressTable.lessonId, lessonsTable.id))
    .where(and(eq(lessonProgressTable.completed, true), eq(lessonsTable.portalKey, portalKey)))
    .groupBy(lessonProgressTable.userId);

  // Coerce Drizzle's count() (bigint, returned as string by node-postgres)
  // into a plain number so the UI's `${u.progressPercent}%` width and the
  // `X/Y` label always render as real numerics rather than concatenated
  // strings. The previous code only coerced inside the percent calc, which
  // left completedLessons as a string and made any downstream arithmetic
  // (or strict equality checks) on the client subtly wrong.
  const progressMap = new Map(allProgress.map(p => [p.userId, Number(p.completedCount) || 0]));
  const [totalLessons] = await db.select({ count: count() })
    .from(lessonsTable)
    .where(eq(lessonsTable.portalKey, portalKey));

  const total = Number(totalLessons?.count) || 0;
  const usersWithProgress = users.map(u => {
    const completed = progressMap.get(u.id) || 0;
    return {
      ...u,
      completedLessons: completed,
      totalLessons: total,
      progressPercent: total > 0 ? Math.round((completed / total) * 100) : 0,
    };
  });

  // Disambiguate "everyone shows 0/N" between a real
  // nobody-has-completed-anything state and a portal_key scoping bug
  // that drops legitimate completions. We compare two counts:
  //   - completionsAfterPortalJoin: completed lesson_progress rows that
  //     join to a lesson with this portal_key (what feeds the UI)
  //   - completionsForVisibleUsers: completed lesson_progress rows for
  //     the SAME users this admin can see, ignoring lessons.portal_key
  // If usersWithCompletions === 0 but completionsForVisibleUsers > 0,
  // the join is silently filtering real data out -- emit a warn so the
  // admin doesn't sit and stare at an ambiguous 0/N grid.
  const usersWithCompletions = usersWithProgress.filter(u => u.completedLessons > 0).length;
  const completionsAfterPortalJoin = Array.from(progressMap.values()).reduce((a, b) => a + b, 0);
  // Only the users whose portal_key matches the active portal are
  // expected to have completions on this portal's curriculum. Room30
  // admins see users from every portal but their progress against
  // Room30 is legitimately 0, so excluding them from the mismatch
  // probe avoids false positives where a main-portal user's
  // main-portal completion would otherwise look like a "dropped" row.
  const inPortalUserIds = users
    .filter(u => (u.portalKey || "main") === portalKey)
    .map(u => u.id);
  let completionsForVisibleUsers = 0;
  if (inPortalUserIds.length > 0) {
    const [unfiltered] = await db
      .select({ c: count() })
      .from(lessonProgressTable)
      .where(
        and(
          eq(lessonProgressTable.completed, true),
          inArray(lessonProgressTable.userId, inPortalUserIds),
        ),
      );
    completionsForVisibleUsers = Number(unfiltered?.c) || 0;
  }
  const progressDiagnostic = {
    portalKey,
    totalLessons: total,
    totalUsers: usersWithProgress.length,
    usersWithCompletions,
    completionsAfterPortalJoin,
    completionsForVisibleUsers,
  };
  if (
    usersWithCompletions === 0 &&
    completionsForVisibleUsers > 0
  ) {
    // (a > 0 && b = 0): real completions exist for these users but
    // none survive the lessons.portal_key='${portalKey}' join. Most
    // likely cause is a portal_key mismatch on the lessons rows or
    // lesson_progress rows pointing at a different portal's lessons.
    req.log.warn(
      progressDiagnostic,
      "admin.users.progress.portal_key_mismatch",
    );
  } else {
    req.log.info(progressDiagnostic, "admin.users.progress.summary");
  }

  res.json(usersWithProgress);
});

// Task #774: on-demand health audits for the admin dashboard. Runs the
// same four read-only audits the daily scheduler runs, so an admin can see
// the current prevention-layer state without waiting for the next Slack
// alert. Read-only; safe to call anytime.
portalRouter.get("/portal/admin/health-check", requireAuth, requireAdmin, async (req: any, res) => {
  try {
    const report = await runHealthAudits();
    res.json(report);
  } catch (err: any) {
    req.log?.error?.(
      { err: err?.message },
      "[health-check] admin run failed",
    );
    res.status(500).json({ error: err?.message || "Health check failed" });
  }
});

portalRouter.get("/portal/admin/analytics", requireAuth, requireAdmin, async (req: any, res) => {
  // Same per-portal scoping as /portal/admin/users: lesson totals,
  // completion counts, and per-lesson breakdowns must all reflect the
  // portal the admin is currently viewing, not the union of both.
  const portalKey = getPortalKey(req);
  // All six reads below are independent, so run them concurrently instead of
  // sequentially. The wall time used to be the SUM of every query (~11s in
  // prod, growing with access_logs), which made the admin dashboard appear
  // "stuck on refresh" while it blocked on this endpoint. Promise.all makes it
  // the MAX of the slowest single query instead.
  const [
    [totalUsers],
    [totalLessons],
    [totalCompletions],
    recentActivity,
    lessonCompletionRates,
    allLessons,
  ] = await Promise.all([
    db.select({ count: count() }).from(portalUsersTable).where(eq(portalUsersTable.portalKey, portalKey)),
    db.select({ count: count() })
      .from(lessonsTable)
      .where(eq(lessonsTable.portalKey, portalKey)),
    db.select({ count: count() })
      .from(lessonProgressTable)
      .innerJoin(lessonsTable, eq(lessonProgressTable.lessonId, lessonsTable.id))
      .where(and(eq(lessonProgressTable.completed, true), eq(lessonsTable.portalKey, portalKey))),
    // Recent activity: scope to users in the current portal so a Room30
    // admin never sees Apex Offers customers' activity rows (and vice
    // versa). access_logs has no portal_key column, so we join through
    // portal_users.
    db
      .select({
        id: accessLogsTable.id,
        userId: accessLogsTable.userId,
        email: accessLogsTable.email,
        action: accessLogsTable.action,
        resourceType: accessLogsTable.resourceType,
        resourceId: accessLogsTable.resourceId,
        ipAddress: accessLogsTable.ipAddress,
        userAgent: accessLogsTable.userAgent,
        createdAt: accessLogsTable.createdAt,
      })
      .from(accessLogsTable)
      .innerJoin(portalUsersTable, eq(portalUsersTable.id, accessLogsTable.userId))
      .where(eq(portalUsersTable.portalKey, portalKey))
      .orderBy(desc(accessLogsTable.createdAt))
      .limit(50),
    db.select({
      lessonId: lessonProgressTable.lessonId,
      completions: count(),
    })
      .from(lessonProgressTable)
      .innerJoin(lessonsTable, eq(lessonProgressTable.lessonId, lessonsTable.id))
      .where(and(eq(lessonProgressTable.completed, true), eq(lessonsTable.portalKey, portalKey)))
      .groupBy(lessonProgressTable.lessonId),
    db.select().from(lessonsTable)
      .where(eq(lessonsTable.portalKey, portalKey))
      .orderBy(asc(lessonsTable.sortOrder)),
  ]);

  const completionMap = new Map(lessonCompletionRates.map(r => [r.lessonId, Number(r.completions)]));
  const lessonCompletions = allLessons.map(l => ({
    lessonId: l.id,
    title: l.title,
    completions: completionMap.get(l.id) || 0,
  }));

  const totalU = Number(totalUsers?.count || 0);
  const totalC = Number(totalCompletions?.count || 0);
  const totalL = Number(totalLessons?.count || 0);
  const averageProgress = totalU > 0 && totalL > 0 ? (totalC / (totalU * totalL)) * 100 : 0;

  res.json({
    totalUsers: totalU,
    totalLessons: totalL,
    totalCompletions: totalC,
    averageProgress,
    recentActivity,
    lessonCompletions,
  });
});

// GET /portal/admin/checkout-conversion
//
// Funnel checkout conversion dashboard: how many checkouts STARTED vs PAID
// vs ABANDONED, bucketed by hour or day, so a real conversion drop is
// obvious at a glance instead of having to read Stripe's raw "Incomplete"
// list.
//
// Definitions (all derived from the orders table - the funnel mints one
// `orders` row the moment a visitor reaches /checkout and fills in their
// contact info, BEFORE they pay):
//   started   = every real funnel order row created in the window
//   paid      = started rows with main_product_paid = true
//   abandoned = started - paid (created but never completed the main charge)
//
// Excluded so the numbers reflect genuine /checkout funnel activity only.
// All of these are synthetic rows minted AFTER a payment that happened
// elsewhere - they never passed through /checkout, so counting them would
// inflate both "started" and "paid" with ~100%-conversion noise:
//   - smoke-test orders (email like 'smoke+...@room30.ai')
//   - synthetic admin grants (id like 'admin-grant-%')
//   - GHL-enrolled synthetic rows (id like 'ghl:%')
//   - Whop reconciler recovery rows (id like 'recovery-%' - minted by the
//     free-promo / whop reconciliation schedulers from a deterministic
//     sha1(email), see whop-reconciliation-scheduler.ts).
//
// Query params:
//   range  = today | 24h | 7d | 30d   (default 7d)
//   bucket = hour | day               (default hour for today/24h, else day)
//
// All timestamps are UTC; the bucket key is an ISO string the frontend
// renders in the admin's locale.
portalRouter.get("/portal/admin/checkout-conversion", requireAuth, requireAdmin, async (req: any, res) => {
  const range = ["today", "24h", "7d", "30d"].includes(req.query.range) ? req.query.range : "7d";

  const now = new Date();
  let since: Date;
  if (range === "today") {
    since = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate()));
  } else if (range === "24h") {
    since = new Date(now.getTime() - 24 * 3600 * 1000);
  } else if (range === "30d") {
    since = new Date(now.getTime() - 30 * 24 * 3600 * 1000);
  } else {
    since = new Date(now.getTime() - 7 * 24 * 3600 * 1000);
  }

  const defaultBucket = range === "today" || range === "24h" ? "hour" : "day";
  const bucketUnit = req.query.bucket === "hour" || req.query.bucket === "day" ? req.query.bucket : defaultBucket;

  const bucketExpr = sql<string>`date_trunc(${bucketUnit}, ${ordersTable.createdAt})`;

  const baseWhere = and(
    gte(ordersTable.createdAt, since),
    sql`${ordersTable.id} not like 'admin-grant-%'`,
    sql`${ordersTable.id} not like 'ghl:%'`,
    sql`${ordersTable.id} not like 'recovery-%'`,
    sql`${ordersTable.email} not ilike 'smoke+%@room30.ai'`,
  );

  const rows = await db
    .select({
      bucket: bucketExpr,
      started: count(),
      paid: sql<number>`count(*) filter (where ${ordersTable.mainProductPaid})`,
      revenueCents: sql<number>`coalesce(sum(${ordersTable.effectiveMainAmountCents}) filter (where ${ordersTable.mainProductPaid}), 0)`,
    })
    .from(ordersTable)
    .where(baseWhere)
    .groupBy(bucketExpr)
    .orderBy(bucketExpr);

  const series = rows.map((r) => {
    const started = Number(r.started) || 0;
    const paid = Number(r.paid) || 0;
    const revenueCents = Number(r.revenueCents) || 0;
    return {
      bucket: new Date(r.bucket as any).toISOString(),
      started,
      paid,
      abandoned: Math.max(0, started - paid),
      revenueCents,
      conversionPct: started > 0 ? Math.round((paid / started) * 1000) / 10 : 0,
    };
  });

  const startedTotal = series.reduce((s, r) => s + r.started, 0);
  const paidTotal = series.reduce((s, r) => s + r.paid, 0);
  const revenueCentsTotal = series.reduce((s, r) => s + r.revenueCents, 0);

  res.json({
    range,
    bucket: bucketUnit,
    since: since.toISOString(),
    generatedAt: now.toISOString(),
    totals: {
      started: startedTotal,
      paid: paidTotal,
      abandoned: Math.max(0, startedTotal - paidTotal),
      revenueCents: revenueCentsTotal,
      conversionPct: startedTotal > 0 ? Math.round((paidTotal / startedTotal) * 1000) / 10 : 0,
    },
    series,
  });
});

// GET /portal/admin/logs
//
// Site-wide access-log viewer for CS / dispute defense. Backs the
// Access Logs admin page (search by email, action, IP, path; export the
// current filtered slice to PDF). Portal-scoped via the inner join on
// portal_users so the room30 tenant never sees rows from another portal.
//
// Query params:
//   page    (default 1)
//   limit   (default 50; capped at 1000 so the PDF "export current view"
//           button can pull a single big page without paginating)
//   email   ILIKE substring match on the buyer's email
//   q       ILIKE substring match against action / resource_id /
//           resource_path (use for "show me every hit on /upsell-3"
//           or "every login" style queries)
//   action  exact match on action (e.g. "lesson_view", "login")
//   ip      exact match on ip_address
//   since   ISO date - inclusive lower bound on created_at
//   until   ISO date - exclusive upper bound on created_at
portalRouter.get("/portal/admin/logs", requireAuth, requireCapability("logs.view"), async (req: any, res) => {
  const page = Math.max(1, parseInt(req.query.page || "1"));
  const limit = Math.min(1000, Math.max(1, parseInt(req.query.limit || "50")));
  const offset = (page - 1) * limit;
  // Same portal-scope as /admin/analytics recentActivity: never let the
  // log viewer surface rows from users in the other business.
  const portalKey = getPortalKey(req);

  const emailQ = typeof req.query.email === "string" && req.query.email.trim() ? req.query.email.trim() : null;
  const q = typeof req.query.q === "string" && req.query.q.trim() ? req.query.q.trim() : null;
  const action = typeof req.query.action === "string" && req.query.action.trim() ? req.query.action.trim() : null;
  const ip = typeof req.query.ip === "string" && req.query.ip.trim() ? req.query.ip.trim() : null;
  const parseDate = (v: any): Date | null => {
    if (typeof v !== "string" || !v.trim()) return null;
    const d = new Date(v);
    return isNaN(d.getTime()) ? null : d;
  };
  const since = parseDate(req.query.since);
  const until = parseDate(req.query.until);

  const conds: any[] = [eq(portalUsersTable.portalKey, portalKey)];
  if (emailQ) {
    // Match either the join-table email (portal_users) or the snapshot
    // stamped on the access_logs row at write time. Buyers occasionally
    // get their portal_users.email rewritten by support, so falling back
    // to the log-row email keeps history searchable by the address the
    // bank reviewer sees on the chargeback.
    conds.push(or(
      ilike(portalUsersTable.email, `%${emailQ}%`),
      ilike(accessLogsTable.email, `%${emailQ}%`),
    ));
  }
  if (action) conds.push(eq(accessLogsTable.action, action));
  if (ip) conds.push(eq(accessLogsTable.ipAddress, ip));
  if (since) conds.push(gte(accessLogsTable.createdAt, since));
  if (until) conds.push(lt(accessLogsTable.createdAt, until));
  if (q) {
    const pat = `%${q}%`;
    conds.push(or(
      ilike(accessLogsTable.action, pat),
      ilike(accessLogsTable.resourceId, pat),
      ilike(accessLogsTable.resourcePath, pat),
    ));
  }
  const where = conds.length === 1 ? conds[0] : and(...conds);

  const [logs, totalRow] = await Promise.all([
    db
      .select({
        id: accessLogsTable.id,
        userId: accessLogsTable.userId,
        email: accessLogsTable.email,
        action: accessLogsTable.action,
        resourceType: accessLogsTable.resourceType,
        resourceId: accessLogsTable.resourceId,
        resourcePath: accessLogsTable.resourcePath,
        ipAddress: accessLogsTable.ipAddress,
        userAgent: accessLogsTable.userAgent,
        createdAt: accessLogsTable.createdAt,
      })
      .from(accessLogsTable)
      .innerJoin(portalUsersTable, eq(portalUsersTable.id, accessLogsTable.userId))
      .where(where)
      .orderBy(desc(accessLogsTable.createdAt))
      .limit(limit)
      .offset(offset),
    db
      .select({ count: count() })
      .from(accessLogsTable)
      .innerJoin(portalUsersTable, eq(portalUsersTable.id, accessLogsTable.userId))
      .where(where),
  ]);

  const total = Number(totalRow[0]?.count) || 0;
  const formattedLogs = logs.map(log => ({
    ...log,
    userEmail: log.email,
    // Prefer the explicit resource_path column; fall back to resource_id
    // for legacy rows that pre-date the column.
    resourcePath: log.resourcePath || log.resourceId,
  }));

  res.json({
    logs: formattedLogs,
    total,
    page,
    limit,
    totalPages: Math.max(1, Math.ceil(total / limit)),
  });
});

