// Lists recent unpaid orders whose buyer email Whop does NOT recognize as
// an active member of the main product. These are the genuinely stuck
// cohort: every self-heal path (webhook, setup-account, sweep) correctly
// does nothing for them because the buyer was never enrolled in Whop in
// the first place. Surfacing them here gives admins a one-stop view to
// triage manually (e.g., refund, re-create the Whop checkout, etc.).
//
// Per request we cap the candidate set so we don't blow up the Whop API
// rate budget on every dashboard refresh. Lookback defaults to 30 days
// and limit to 50; both are clamped to safe maxima.
portalRouter.get("/portal/admin/free-promo-stuck-orders", requireAuth, requireAdmin, async (req: any, res) => {
  const lookbackDays = Math.min(90, Math.max(1, parseInt(req.query.lookbackDays || "30") || 30));
  const limit = Math.min(100, Math.max(1, parseInt(req.query.limit || "50") || 50));
  const since = new Date(Date.now() - lookbackDays * 24 * 60 * 60 * 1000);

  const candidates = await db
    .select({
      id: ordersTable.id,
      email: ordersTable.email,
      productSlugs: ordersTable.productSlugs,
      whopBundlePlanId: ordersTable.whopBundlePlanId,
      totalAmount: ordersTable.totalAmount,
      createdAt: ordersTable.createdAt,
    })
    .from(ordersTable)
    .where(
      and(
        eq(ordersTable.mainProductPaid, false),
        gte(ordersTable.createdAt, since),
        sql`${ordersTable.email} IS NOT NULL AND length(${ordersTable.email}) > 0`,
      ),
    )
    .orderBy(desc(ordersTable.createdAt))
    .limit(limit);

  // Live Whop membership classification is retired with the legacy
  // purchasing stack, so we can no longer distinguish "genuinely stuck"
  // from "in Whop but unpaid", nor surface Whop-only enrollments. We
  // return the raw unpaid-order candidate set (DB source of truth) so
  // admins can still triage manually.
  const stuck = candidates;

  res.json({
    lookbackDays,
    limit,
    consideredCount: candidates.length,
    stuckCount: stuck.length,
    inWhopButUnpaidCount: 0,
    lookupErrors: 0,
    stuck,
    whopOnly: [],
    whopOnlyConsideredMemberships: 0,
    whopOnlyLookupErrors: 0,
    whopOnlyCount: 0,
  });
});

// One-click "retry sweep" for a single order. Calls the same self-heal
// path the periodic sweep uses (`reconcileIfWhopGrantedMain`), so a buyer
// who was always in Whop but whose order row never flipped gets recovered
// immediately. Returns the full reconcile result so the UI can show a
// toast that distinguishes the three outcomes (flipped / already paid /
// not in Whop).
portalRouter.post(
  "/portal/admin/free-promo-orders/:orderId/sweep",
  requireAuth,
  requireAdmin,
  async (req: any, res) => {
    const orderId = String(req.params.orderId || "").trim();
    if (!orderId) {
      res.status(400).json({ error: "orderId required" });
      return;
    }
    const [row] = await db
      .select({ id: ordersTable.id, email: ordersTable.email, mainProductPaid: ordersTable.mainProductPaid })
      .from(ordersTable)
      .where(eq(ordersTable.id, orderId))
      .limit(1);
    if (!row) {
      res.status(404).json({ error: "order_not_found" });
      return;
    }
    if (row.mainProductPaid) {
      res.json({ flipped: false, alreadyPaid: true, orderId, email: row.email, reason: "already_paid" });
      return;
    }
    const email = (row.email || "").trim().toLowerCase();
    if (!email) {
      res.status(400).json({ error: "order_has_no_email" });
      return;
    }
    // The live-Whop reconciliation sweep is retired with the legacy
    // purchasing stack. Order paid-state is now the source of truth
    // (written by the GoHighLevel purchase flows), so there is no
    // provider to re-verify against here.
    res.status(410).json({
      flipped: false,
      alreadyPaid: false,
      orderId,
      email,
      reason: "reconciliation_retired",
      message:
        "Automatic order reconciliation has been retired. Grant access manually if the buyer's payment is confirmed.",
    });
    return;
  },
);

// Task #515: Buyer-access diagnostic + resync endpoint.
//
// One-stop admin view of a buyer's entitlement state across our DB and
// Whop's truth. The GET returns:
//   - every orders row for the email (paid flags, slugs, total, ids)
//   - the (now-unique) portal_users row
//   - every valid Whop membership the buyer holds (product / status)
//   - the issued Platinum Founder Code if one exists
// The POST resync calls `reconcileBuyerFromWhop` so the exact same
// helper used by the webhook fallback + the MAY2026 cohort backfill is
// what the admin button hits -- guaranteeing they cannot diverge.
portalRouter.get(
  "/portal/admin/buyer-access",
  requireAuth,
  requireAdmin,
  async (req: any, res) => {
    const email = ((req.query.email as string | undefined) || "")
      .trim()
      .toLowerCase();
    if (!email || !/^\S+@\S+\.\S+$/.test(email)) {
      res.status(400).json({ error: "invalid_email" });
      return;
    }
    try {
      const orders = await db
        .select({
          id: ordersTable.id,
          email: ordersTable.email,
          productSlugs: ordersTable.productSlugs,
          mainProductPaid: ordersTable.mainProductPaid,
          bump1Paid: ordersTable.bump1Paid,
          bump2Paid: ordersTable.bump2Paid,
          bump3Paid: ordersTable.bump3Paid,
          upsell1Paid: ordersTable.upsell1Paid,
          downsell1Paid: ordersTable.downsell1Paid,
          upsell2Paid: ordersTable.upsell2Paid,
          upsell3Paid: ordersTable.upsell3Paid,
          whopUserId: ordersTable.whopUserId,
          whopReceiptId: ordersTable.whopReceiptId,
          whopBundlePlanId: ordersTable.whopBundlePlanId,
          totalAmount: ordersTable.totalAmount,
          createdAt: ordersTable.createdAt,
        })
        .from(ordersTable)
        .where(sql`lower(${ordersTable.email}) = ${email}`)
        .orderBy(desc(ordersTable.createdAt));

      const portalUser = await db
        .select({
          id: portalUsersTable.id,
          email: portalUsersTable.email,
          portalKey: portalUsersTable.portalKey,
          clerkId: portalUsersTable.clerkId,
          whopUserId: portalUsersTable.whopUserId,
          isActive: portalUsersTable.isActive,
          isAList: portalUsersTable.isAList,
          createdAt: portalUsersTable.createdAt,
          bonusInfluencerQuota: portalUsersTable.bonusInfluencerQuota,
        })
        .from(portalUsersTable)
        .where(sql`lower(${portalUsersTable.email}) = ${email}`)
        .limit(1);

      let whopMemberships: Array<{
        id: string;
        product_id?: string;
        status: string;
        valid: boolean;
        created_at?: number | string;
      }> = [];
      // Live Whop membership lookup is retired with the legacy purchasing
      // stack. The diagnostic now reflects DB state only.
      const whopLookupError: string | null =
        "Live Whop membership lookup retired; showing DB state only.";

      const founderCode = await getPlatinumCodeForEmail(email);

      // Receipts surface: for the low-ticket cohort the
      // authoritative receipt id lives on `orders.whopReceiptId`,
      // and for the high-ticket coaching cohort it lives on the
      // coaching_agreements row (whop_session_id +
      // whop_membership_id are the receipt + membership pair
      // returned by Whop's checkout API). Surface both projections
      // so an admin can confirm "a real Whop receipt exists" for
      // this buyer without leaving the panel.
      type LowTicketReceipt = {
        source: "orders";
        orderId: string;
        whopReceiptId: string | null;
        whopBundlePlanId: string | null;
        createdAt: Date | null;
      };
      type HighTicketReceipt = {
        source: "coaching_agreements";
        agreementId: number;
        agreementType: string | null;
        status: string | null;
        whopReceiptId: string | null;
        whopMembershipId: string | null;
        paidAt: Date | null;
        createdAt: Date | null;
      };
      const lowTicketReceipts: LowTicketReceipt[] = orders.map((o) => ({
        source: "orders" as const,
        orderId: o.id,
        whopReceiptId: o.whopReceiptId ?? null,
        whopBundlePlanId: o.whopBundlePlanId ?? null,
        createdAt: o.createdAt ?? null,
      }));
      let highTicketReceipts: HighTicketReceipt[] = [];
      try {
        const rows = await db
          .select({
            id: coachingAgreementsTable.id,
            agreementType: coachingAgreementsTable.agreementType,
            status: coachingAgreementsTable.status,
            whopSessionId: coachingAgreementsTable.whopSessionId,
            whopMembershipId: coachingAgreementsTable.whopMembershipId,
            paidAt: coachingAgreementsTable.paidAt,
            createdAt: coachingAgreementsTable.createdAt,
          })
          .from(coachingAgreementsTable)
          .where(sql`lower(${coachingAgreementsTable.email}) = ${email}`);
        highTicketReceipts = rows.map((r) => ({
          source: "coaching_agreements" as const,
          agreementId: r.id,
          agreementType: r.agreementType ?? null,
          status: r.status ?? null,
          whopReceiptId: r.whopSessionId ?? null,
          whopMembershipId: r.whopMembershipId ?? null,
          paidAt: r.paidAt ?? null,
          createdAt: r.createdAt ?? null,
        }));
      } catch {
        // High-ticket receipts are non-essential; leave empty on
        // failure so the rest of the diagnostic view still renders.
      }
      const receipts = {
        lowTicket: lowTicketReceipts,
        highTicket: highTicketReceipts,
      };

      // Computed entitlements: side-by-side "what Whop says you
      // should have" vs "what the orders row currently has". Driven
      // by the same slugToOrdersField mapping as the resync helper
      // so a divergence here is exactly what `Resync from Whop`
      // would correct.
      type FieldKey =
        | "mainProductPaid"
        | "bump1Paid"
        | "bump2Paid"
        | "bump3Paid"
        | "upsell1Paid"
        | "downsell1Paid"
        | "upsell2Paid"
        | "upsell3Paid";
      const FIELD_KEYS: FieldKey[] = [
        "mainProductPaid",
        "bump1Paid",
        "bump2Paid",
        "bump3Paid",
        "upsell1Paid",
        "downsell1Paid",
        "upsell2Paid",
        "upsell3Paid",
      ];
      const expected: Record<FieldKey, boolean> = {
        mainProductPaid: false,
        bump1Paid: false,
        bump2Paid: false,
        bump3Paid: false,
        upsell1Paid: false,
        downsell1Paid: false,
        upsell2Paid: false,
        upsell3Paid: false,
      };
      // "Expected from Whop" was derived from the buyer's live Whop
      // memberships, which are no longer available. Left all-false so the
      // panel simply shows the DB (actual) state without a drift signal.
      const unmappedFromWhop: string[] = [];
      const actual: Record<FieldKey, boolean> = {
        mainProductPaid: false,
        bump1Paid: false,
        bump2Paid: false,
        bump3Paid: false,
        upsell1Paid: false,
        downsell1Paid: false,
        upsell2Paid: false,
        upsell3Paid: false,
      };
      for (const o of orders) {
        for (const f of FIELD_KEYS) {
          if ((o as Record<FieldKey, boolean | null>)[f]) actual[f] = true;
        }
      }
      const drift: Array<{ field: FieldKey; expected: boolean; actual: boolean }> = [];
      for (const f of FIELD_KEYS) {
        if (expected[f] !== actual[f]) {
          drift.push({ field: f, expected: expected[f], actual: actual[f] });
        }
      }

      res.json({
        email,
        orders,
        portalUser: portalUser[0] || null,
        whopMemberships,
        whopLookupError,
        receipts,
        computedEntitlements: {
          expectedFromWhop: expected,
          actualOnOrders: actual,
          drift,
          unmappedFromWhop,
        },
        founderCode: founderCode
          ? {
              code: founderCode.code,
              status: founderCode.status,
              redeemedAt: founderCode.redeemedAt,
              redeemedForProductSlug: founderCode.redeemedForProductSlug,
            }
          : null,
      });
      return;
    } catch (e: any) {
      req.log?.error?.({ err: e, email }, "[t515] buyer-access GET failed");
      res.status(500).json({ error: "lookup_failed", message: e?.message || String(e) });
      return;
    }
  },
);

portalRouter.post(
  "/portal/admin/buyer-access/resync",
  requireAuth,
  requireAdmin,
  async (req: any, res) => {
    const email = ((req.body?.email as string | undefined) || "")
      .trim()
      .toLowerCase();
    const orderId = ((req.body?.orderId as string | undefined) || "").trim() || null;
    if (!email || !/^\S+@\S+\.\S+$/.test(email)) {
      res.status(400).json({ error: "invalid_email" });
      return;
    }
    // Resync-from-Whop reconciliation is retired with the legacy purchasing
    // stack. Order paid-state is now the source of truth (written by the
    // GoHighLevel purchase flows), so there is no provider to reconcile
    // against. Grant access manually if a buyer's payment is confirmed.
    req.log?.warn?.({ email, orderId }, "[t515] buyer-access resync hit after retirement");
    res.status(410).json({
      error: "resync_retired",
      message:
        "Resync from Whop has been retired. Grant access manually if the buyer's payment is confirmed.",
    });
    return;
  },
);

// Diagnostic endpoint for the recurring "admin shows active but buyer
// sees locked" lockout bug (Jess Nov 2026, also David / Eimy / Olli).
// Returns the complete entitlement picture for an email in one shot:
//   - every portal_users row for that email (catches duplicates)
//   - every orders row that the buyer's /portal/me query WOULD see
//     for each portal_users row (lower(email) match + the synthetic
//     admin-grant-<userId> row by id)
//   - the computed entitlement object per portal_users row
//   - the per-product "would the portal UI unlock?" decision matching
//     the exact lock checks in done-for-you-pack.tsx / follower-hijack.tsx
//     / tiktok-slideshow-masterclass.tsx / our-portfolio.tsx /
//     platinum-club.tsx, with a human-readable reason
// Admin-only. Read-only. Safe to call any time without side effects.
portalRouter.get(
  "/portal/admin/access-debug",
  requireAuth,
  requireAdmin,
  async (req: any, res) => {
    const email = ((req.query.email as string | undefined) || "")
      .trim()
      .toLowerCase();
    if (!email || !/^\S+@\S+\.\S+$/.test(email)) {
      res.status(400).json({ error: "invalid_email" }); return;
    }
    try {
      const portalUsers = await db
        .select()
        .from(portalUsersTable)
        .where(sql`lower(${portalUsersTable.email}) = ${email}`)
        .orderBy(asc(portalUsersTable.id));

      const syntheticIds = portalUsers
        .map((u) => `admin-grant-${u.id}`);
      const ordersRows = syntheticIds.length > 0
        ? await db
            .select()
            .from(ordersTable)
            .where(
              or(
                sql`lower(${ordersTable.email}) = ${email}`,
                inArray(ordersTable.id, syntheticIds),
              ),
            )
            .orderBy(desc(ordersTable.createdAt))
        : await db
            .select()
            .from(ordersTable)
            .where(sql`lower(${ordersTable.email}) = ${email}`)
            .orderBy(desc(ordersTable.createdAt));

      // Flags the portal UI actually cares about for paywall decisions.
      // Keep in sync with PRODUCT_FLAGS in
      // artifacts/room30-portal/src/pages/* lock logic.
      const FLAG_KEYS = [
        "mainProductPaid",
        "bump1Paid",
        "bump2Paid",
        "bump3Paid",
        "upsell1Paid",
        "downsell1Paid",
        "upsell2Paid",
        "upsell3Paid",
        "tiktokSlideshowPaid",
        "hookDemoPaid",
        "doneForYouPackPaid",
        "portfolioPaid",
        "platinumPaid",
      ] as const;
      type FlagKey = (typeof FLAG_KEYS)[number];

      // For each portal_users row, replay computePurchaseEntitlements
      // and produce the per-flag attribution (which orders.id contributed
      // each true flag) so support can tell at a glance "the admin grant
      // is being seen / not seen by /portal/me for this user".
      const perPortalUser = await Promise.all(
        portalUsers.map(async (u) => {
          const ent = await computePurchaseEntitlements(u);
          const syntheticId = `admin-grant-${u.id}`;
          const norm = String(u.email || "").trim().toLowerCase();
          const visible = ordersRows.filter(
            (o) =>
              (o.email || "").toLowerCase() === norm ||
              o.id === syntheticId,
          );
          const contributions: Partial<Record<FlagKey, string[]>> = {};
          for (const k of FLAG_KEYS) {
            const ids = visible
              .filter((o) => (o as any)[k] === true)
              .map((o) => o.id);
            if (ids.length > 0) contributions[k] = ids;
          }
          // Per-product UI lock decision: which sidebar / page would
          // unlock for this portal_users row. Mirrors the EXACT
          // entitlement predicates in the portal page components as of
          // Nov 2026 - keep these in sync with src/pages/*. Note:
          // entitlement-only. Prelaunch / runtime locks (isPrelaunchLocked)
          // are NOT factored in here, so a product can show
          // `unlocked: true` while the page still renders a paywall for
          // prelaunch reasons. Use the "Prelaunch lock" toggle in admin
          // to distinguish.
          const productDecisions = {
            // done-for-you-pack.tsx: paid = !!user?.doneForYouPackPaid
            "done-for-you-pack": {
              unlocked: !!ent.doneForYouPackPaid,
              reason: ent.doneForYouPackPaid
                ? "doneForYouPackPaid=true"
                : "doneForYouPackPaid=false on every visible order",
            },
            // tiktok-slideshow-masterclass.tsx:
            //   paid = !!user?.bump3Paid || !!user?.tiktokSlideshowPaid
            "tiktok-slideshow-masterclass": {
              unlocked: !!ent.bump3Paid || !!ent.tiktokSlideshowPaid,
              reason:
                ent.bump3Paid || ent.tiktokSlideshowPaid
                  ? `bump3Paid=${ent.bump3Paid} || tiktokSlideshowPaid=${ent.tiktokSlideshowPaid}`
                  : "both bump3Paid and tiktokSlideshowPaid are false",
            },
            // follower-hijack.tsx:
            //   paid = !!user?.bump3Paid || !!user?.tiktokSlideshowPaid
            "follower-hijack": {
              unlocked: !!ent.bump3Paid || !!ent.tiktokSlideshowPaid,
              reason:
                ent.bump3Paid || ent.tiktokSlideshowPaid
                  ? `bump3Paid=${ent.bump3Paid} || tiktokSlideshowPaid=${ent.tiktokSlideshowPaid}`
                  : "both bump3Paid and tiktokSlideshowPaid are false",
            },
            // our-portfolio.tsx: paid = !!user?.portfolioPaid
            "our-portfolio": {
              unlocked: !!ent.portfolioPaid,
              reason: ent.portfolioPaid
                ? "portfolioPaid=true"
                : "portfolioPaid=false on every visible order",
            },
            // platinum-club.tsx: paid = !!user?.platinumPaid
            "platinum-club": {
              unlocked: !!ent.platinumPaid,
              reason: ent.platinumPaid
                ? "platinumPaid=true"
                : "platinumPaid=false on every visible order",
            },
            // hook-demo-library.tsx: paid = !!user?.bump2Paid
            //   (the standalone `hookDemoPaid` flag is legacy and is
            //   NOT consulted by the live page - admin grants of it
            //   alone will NOT unlock the page; only bump2 does.)
            "hook-demo-library": {
              unlocked: !!ent.bump2Paid,
              reason: ent.bump2Paid
                ? "bump2Paid=true"
                : ent.hookDemoPaid
                  ? "bump2Paid=false (note: hookDemoPaid=true is set but the page does NOT check this flag; grant bump2Paid to unlock)"
                  : "bump2Paid=false on every visible order",
            },
          };
          return {
            portalUserId: u.id,
            email: u.email,
            portalKey: u.portalKey,
            clerkId: u.clerkId,
            role: u.role,
            isActive: u.isActive,
            entitlements: ent,
            visibleOrderIds: visible.map((o) => o.id),
            syntheticGrantRowExists: ordersRows.some(
              (o) => o.id === syntheticId,
            ),
            contributions,
            productDecisions,
          };
        }),
      );

      // Drift detector: when more than one portal_users row exists for
      // this email, surface whether they DISAGREE on any flag. This is
      // the exact failure mode that hit Jess - admin granted on row A,
      // user logs in via row B, and the buyer's "me" call hits row B's
      // entitlements which don't include the synthetic grant from A.
      const drift: Array<{ field: FlagKey; perUser: Array<{ id: number; value: boolean }> }> = [];
      if (perPortalUser.length > 1) {
        for (const k of FLAG_KEYS) {
          const vals = perPortalUser.map((p) => ({
            id: p.portalUserId,
            value: !!(p.entitlements as any)[k],
          }));
          const distinct = new Set(vals.map((v) => v.value));
          if (distinct.size > 1) drift.push({ field: k, perUser: vals });
        }
      }

      // Trim orders rows to the columns that matter for entitlement
      // debugging so the response stays small.
      const trimmedOrders = ordersRows.map((o) => ({
        id: o.id,
        email: o.email,
        currentStep: o.currentStep,
        mainProductPaid: !!o.mainProductPaid,
        bump1Paid: !!o.bump1Paid,
        bump2Paid: !!o.bump2Paid,
        bump3Paid: !!o.bump3Paid,
        upsell1Paid: !!o.upsell1Paid,
        downsell1Paid: !!o.downsell1Paid,
        upsell2Paid: !!o.upsell2Paid,
        upsell3Paid: !!o.upsell3Paid,
        tiktokSlideshowPaid: !!(o as any).tiktokSlideshowPaid,
        hookDemoPaid: !!(o as any).hookDemoPaid,
        doneForYouPackPaid: !!o.doneForYouPackPaid,
        portfolioPaid: !!o.portfolioPaid,
        platinumPaid: !!o.platinumPaid,
        stripePaymentIntentId: (o as any).stripePaymentIntentId ?? null,
        whopReceiptId: (o as any).whopReceiptId ?? null,
        paymentSourceType: (o as any).paymentSourceType ?? null,
        createdAt: o.createdAt,
        updatedAt: o.updatedAt,
      }));

      res.json({
        email,
        portalUserCount: portalUsers.length,
        orderCount: ordersRows.length,
        perPortalUser,
        drift,
        orders: trimmedOrders,
      });
      return;
    } catch (e: any) {
      req.log?.error?.(
        { err: e?.message || String(e), email },
        "[access-debug] lookup failed",
      );
      res
        .status(500)
        .json({ error: "lookup_failed", message: e?.message || String(e) });
      return;
    }
  },
);

// GET /portal/admin/users/:userId/logs
//
// Paginated, filterable activity log for a single portal user. CS uses this
// to answer "what pages did this buyer actually visit, from what IP, on
// what device, when?" without needing to dig into raw DB. Every row carries
// action + resource path + IP + user-agent + metadata.
//
// Query params:
//   page         (default 1)
//   limit        (default 100, max 500)
//   action       exact match on action (e.g. "lesson_view", "page_view")
//   resourceType exact match on resource_type (e.g. "lesson", "page", "api")
//   q            ILIKE substring match against action / resource_id /
//                resource_path (use this for "find every hit on
//                /upsell-3" style queries)
//   since        ISO date - inclusive lower bound on created_at
//   until        ISO date - exclusive upper bound on created_at
//   ip           exact match on ip_address
//
// Returns: { logs, total, page, limit, totalPages }
portalRouter.get("/portal/admin/users/:userId/logs", requireAuth, requireCapability("logs.view"), async (req: any, res) => {
  const userId = parseInt(req.params.userId);
  if (isNaN(userId)) { res.status(400).json({ error: "Invalid user ID" }); return; }
  // Cross-portal isolation: 404 if the user belongs to a different portal.
  const [u] = await db.select({ portalKey: portalUsersTable.portalKey }).from(portalUsersTable).where(eq(portalUsersTable.id, userId));
  if (!u || !(req.appUser?.isSuperAdmin && getPortalKey(req) === "room30") && (u.portalKey || "main") !== getPortalKey(req)) {
    res.status(404).json({ error: "User not found" }); return;
  }

  const page = Math.max(1, parseInt(req.query.page || "1"));
  const limit = Math.min(500, Math.max(1, parseInt(req.query.limit || "100")));
  const offset = (page - 1) * limit;
  const action = typeof req.query.action === "string" && req.query.action.trim() ? req.query.action.trim() : null;
  const resourceType = typeof req.query.resourceType === "string" && req.query.resourceType.trim() ? req.query.resourceType.trim() : null;
  const ip = typeof req.query.ip === "string" && req.query.ip.trim() ? req.query.ip.trim() : null;
  const q = typeof req.query.q === "string" && req.query.q.trim() ? req.query.q.trim() : null;
  const parseDate = (v: any): Date | null => {
    if (typeof v !== "string" || !v.trim()) return null;
    const d = new Date(v);
    return isNaN(d.getTime()) ? null : d;
  };
  const since = parseDate(req.query.since);
  const until = parseDate(req.query.until);

  const conds: any[] = [eq(accessLogsTable.userId, userId)];
  if (action) conds.push(eq(accessLogsTable.action, action));
  if (resourceType) conds.push(eq(accessLogsTable.resourceType, resourceType));
  if (ip) conds.push(eq(accessLogsTable.ipAddress, ip));
  if (since) conds.push(gte(accessLogsTable.createdAt, since));
  if (until) conds.push(lt(accessLogsTable.createdAt, until));
  if (q) {
    const pat = `%${q}%`;
    conds.push(or(
      ilike(accessLogsTable.action, pat),
      ilike(accessLogsTable.resourceId, pat),
      ilike(accessLogsTable.resourcePath, pat),
    ));
  }
  const where = conds.length === 1 ? conds[0] : and(...conds);

  const [logs, totalRow] = await Promise.all([
    db.select().from(accessLogsTable).where(where).orderBy(desc(accessLogsTable.createdAt)).limit(limit).offset(offset),
    db.select({ count: count() }).from(accessLogsTable).where(where),
  ]);
  const total = Number(totalRow[0]?.count) || 0;
  res.json({
    logs,
    total,
    page,
    limit,
    totalPages: Math.max(1, Math.ceil(total / limit)),
  });
});

// GET /portal/admin/users/:userId/activity-summary
//
// Aggregate view of a single user's activity. Designed for CS to glance at
// a buyer and immediately see: how long they've been active, how many
// distinct IPs / devices they've signed in from, which pages they hit
// most, and a 30-day activity sparkline. Cheap to call - all aggregations
// run against access_logs and are bounded by the user's own row count.
portalRouter.get("/portal/admin/users/:userId/activity-summary", requireAuth, requireAdmin, async (req: any, res) => {
  const userId = parseInt(req.params.userId);
  if (isNaN(userId)) { res.status(400).json({ error: "Invalid user ID" }); return; }
  const [u] = await db.select({ portalKey: portalUsersTable.portalKey }).from(portalUsersTable).where(eq(portalUsersTable.id, userId));
  if (!u || !(req.appUser?.isSuperAdmin && getPortalKey(req) === "room30") && (u.portalKey || "main") !== getPortalKey(req)) {
    res.status(404).json({ error: "User not found" }); return;
  }

  const where = eq(accessLogsTable.userId, userId);

  const [
    totalRow,
    firstLastRow,
    topIps,
    topAgents,
    topPaths,
    topActions,
    daily,
  ] = await Promise.all([
    db.select({ count: count() }).from(accessLogsTable).where(where),
    db.select({
      first: sql<Date | null>`min(${accessLogsTable.createdAt})`,
      last: sql<Date | null>`max(${accessLogsTable.createdAt})`,
      distinctIps: sql<number>`count(distinct ${accessLogsTable.ipAddress})`,
      distinctAgents: sql<number>`count(distinct ${accessLogsTable.userAgent})`,
    }).from(accessLogsTable).where(where),
    db.select({
      ipAddress: accessLogsTable.ipAddress,
      count: count(),
      lastSeen: sql<Date | null>`max(${accessLogsTable.createdAt})`,
    }).from(accessLogsTable).where(where).groupBy(accessLogsTable.ipAddress).orderBy(desc(count())).limit(20),
    db.select({
      userAgent: accessLogsTable.userAgent,
      count: count(),
      lastSeen: sql<Date | null>`max(${accessLogsTable.createdAt})`,
    }).from(accessLogsTable).where(where).groupBy(accessLogsTable.userAgent).orderBy(desc(count())).limit(20),
    db.select({
      resourcePath: accessLogsTable.resourcePath,
      resourceId: accessLogsTable.resourceId,
      count: count(),
      lastSeen: sql<Date | null>`max(${accessLogsTable.createdAt})`,
    }).from(accessLogsTable).where(where).groupBy(accessLogsTable.resourcePath, accessLogsTable.resourceId).orderBy(desc(count())).limit(30),
    db.select({
      action: accessLogsTable.action,
      count: count(),
      lastSeen: sql<Date | null>`max(${accessLogsTable.createdAt})`,
    }).from(accessLogsTable).where(where).groupBy(accessLogsTable.action).orderBy(desc(count())).limit(20),
    db.select({
      day: sql<string>`to_char(date_trunc('day', ${accessLogsTable.createdAt}), 'YYYY-MM-DD')`,
      count: count(),
    }).from(accessLogsTable)
      .where(and(where, gte(accessLogsTable.createdAt, new Date(Date.now() - 30 * 24 * 60 * 60 * 1000))))
      .groupBy(sql`date_trunc('day', ${accessLogsTable.createdAt})`)
      .orderBy(sql`date_trunc('day', ${accessLogsTable.createdAt})`),
  ]);

  res.json({
    userId,
    totalEvents: Number(totalRow[0]?.count) || 0,
    firstSeenAt: firstLastRow[0]?.first ?? null,
    lastSeenAt: firstLastRow[0]?.last ?? null,
    distinctIpCount: Number(firstLastRow[0]?.distinctIps) || 0,
    distinctUserAgentCount: Number(firstLastRow[0]?.distinctAgents) || 0,
    topIps: topIps.map(r => ({ ipAddress: r.ipAddress, count: Number(r.count), lastSeen: r.lastSeen })),
    topUserAgents: topAgents.map(r => ({ userAgent: r.userAgent, count: Number(r.count), lastSeen: r.lastSeen })),
    topPaths: topPaths.map(r => ({ resourcePath: r.resourcePath, resourceId: r.resourceId, count: Number(r.count), lastSeen: r.lastSeen })),
    topActions: topActions.map(r => ({ action: r.action, count: Number(r.count), lastSeen: r.lastSeen })),
    dailyCounts: daily.map(r => ({ day: r.day, count: Number(r.count) })),
  });
});

// GET /portal/admin/users/lookup?email=<buyer>
//
// Email -> portal_users[] resolver for CS. The buyer just gives an email;
// CS pastes it here, gets back the matching userId(s), then loads each
// one's logs / activity-summary. Returns every row regardless of
// portal_key for super-admins (mirrors the access-debug diagnostic
// pattern - multi-row drift is a real failure mode and CS needs to see
// all of it). Non-super admins are scoped to their own portal.
portalRouter.get("/portal/admin/users/lookup", requireAuth, requireAdmin, async (req: any, res) => {
  const rawEmail = typeof req.query.email === "string" ? req.query.email.trim().toLowerCase() : "";
  if (!rawEmail || rawEmail.length > 254) {
    res.status(400).json({ error: "Provide an email query param." }); return;
  }
  const portalKey = getPortalKey(req);
  const isSuper = !!req.appUser?.isSuperAdmin && portalKey === "room30";
  const conds: any[] = [eq(portalUsersTable.email, rawEmail)];
  if (!isSuper) conds.push(eq(portalUsersTable.portalKey, portalKey));
  const users = await db.select({
    id: portalUsersTable.id,
    email: portalUsersTable.email,
    firstName: portalUsersTable.firstName,
    lastName: portalUsersTable.lastName,
    clerkId: portalUsersTable.clerkId,
    portalKey: portalUsersTable.portalKey,
    role: portalUsersTable.role,
    isActive: portalUsersTable.isActive,
    createdAt: portalUsersTable.createdAt,
    lastLoginAt: portalUsersTable.lastLoginAt,
  }).from(portalUsersTable).where(and(...conds)).orderBy(desc(portalUsersTable.createdAt));
  res.json({ email: rawEmail, users, drift: users.length > 1 });
});

// POST /portal/track
//
// Lightweight client-side event emitter the portal SPA calls on every
// route change ("page_view") and on tracked UI clicks ("click"). Without
// this, access_logs only sees raw API URLs - the auto-logging middleware
// records `GET /api/portal/lessons/r30-p2-bridge-page-build`, not "user
// visited /lesson/r30-p2-bridge-page-build". This endpoint lets the SPA
// stamp the actual route the user navigated to and any in-page click
// metadata, so CS can answer "what page were they on when they clicked
// X" without reverse-engineering API URLs.
//
// Body (all optional except action):
//   { action: "page_view" | "click" | "<custom>",
//     path: string,                  // e.g. "/lesson/r30-p2-bridge-page-build"
//     resourceType?: string,         // e.g. "page" | "button" | "video"
//     resourceId?: string,           // e.g. button id / lesson slug
//     metadata?: object }            // free-form JSON, capped at 4 KB
//
// Server stamps IP + UA from the request itself (never trust client).
// Action is whitelisted to a short prefix-allowed set so a malicious
// client cannot spam arbitrary actions.
const TRACK_ACTION_PREFIXES = ["page_view", "click", "ui_", "feature_"];
portalRouter.post("/portal/track", requireAuth, requireActive, async (req: any, res) => {
  const body = (req.body ?? {}) as {
    action?: unknown; path?: unknown; resourceType?: unknown;
    resourceId?: unknown; metadata?: unknown;
  };
  const action = typeof body.action === "string" ? body.action.trim().slice(0, 64) : "";
  if (!action || !TRACK_ACTION_PREFIXES.some(p => action === p || action.startsWith(p))) {
    res.status(400).json({ error: "Invalid action." }); return;
  }
  const path = typeof body.path === "string" ? body.path.slice(0, 512) : null;
  const resourceType = typeof body.resourceType === "string" ? body.resourceType.slice(0, 64) : null;
  const resourceId = typeof body.resourceId === "string" ? body.resourceId.slice(0, 256) : null;
  let metadata: any = null;
  if (body.metadata && typeof body.metadata === "object") {
    try {
      const serialized = JSON.stringify(body.metadata);
      if (serialized.length <= 4096) metadata = body.metadata;
    } catch { /* drop unserializable metadata */ }
  }

  await db.insert(accessLogsTable).values({
    userId: req.portalUser.id,
    clerkId: req.clerkId,
    email: req.portalUser.email,
    action,
    resourceType,
    resourceId,
    resourcePath: path,
    ipAddress: getIp(req),
    userAgent: req.headers["user-agent"] || "unknown",
    metadata,
  });
  res.json({ ok: true });
});

portalRouter.post("/portal/admin/invites", requireAuth, requireCapability("users.invite"), async (req: any, res) => {
  const { email, role: rawRole, grants: rawGrants, teamRole: rawTeamRole, permissions: rawPermissions } = req.body || {};
  if (!email || typeof email !== "string") { res.status(400).json({ error: "Valid email required" }); return; }

  // Stamp the invite with the inviting admin's portal so every downstream
  // step (sign-up URL, email branding, /portal/enroll claim filter)
  // routes the recipient back into the right portal. Without this the
  // invite would default to "main" and a Room30 admin's invite would
  // ship an Apex Offers branded email that drops the user into the
  // course-portal dashboard. See migration 0043_invites_portal_key.sql.
  const invitePortalKey = getPortalKey(req);
  // invitePortalKey is still recorded on the invite/email_logs metadata
  // below for historical isolation guards, but every invite now renders
  // as Room30 AI regardless of value (Task #661).

  // Validate role. Same three-tier system as the role PATCH endpoint.
  // Only the env-pinned super admin can pre-assign the "admin" role
  // via an invite, mirroring the in-page role guard.
  const allowedRoles = ["student", "team", "admin"] as const;
  const role: "student" | "team" | "admin" = allowedRoles.includes(rawRole)
    ? rawRole
    : "student";
  if (role === "admin" && !req.appUser?.isSuperAdmin) {
    res.status(403).json({ error: "Only the portal owner can invite an Admin." }); return;
  }

  // Task #796 security: assigning a team/admin role or any team capability is
  // team-management and stays admin-only (mirrors the role / team-permissions
  // PATCH endpoints, which are both requireAdmin). A "team" member who holds
  // only `users.invite` can invite/resend STUDENTS but must never be able to
  // mint staff or attach capabilities - otherwise they could escalate their
  // own powers by inviting their own email as a team member with a broad
  // permission set (applyInviteEntitlements writes those onto the matching
  // portal_users row immediately). `requireCapability("users.invite")` alone
  // is intentionally not enough for the team path.
  const callerIsAdmin =
    req.portalUser?.role === "admin" || !!req.appUser?.isSuperAdmin;
  const wantsTeamManagement =
    role === "team" ||
    role === "admin" ||
    rawTeamRole !== undefined ||
    rawPermissions !== undefined;
  if (wantsTeamManagement && !callerIsAdmin) {
    res.status(403).json({
      error: "Only an admin can invite team members or assign capabilities.",
    });
    return;
  }

  // Task #796: team preset + capability list. Only meaningful for the
  // "team" role; for any other role we deliberately store null so a stale
  // permission set can never leak onto a student/admin. Capabilities are
  // sanitized against the canonical allowlist. When a known preset is sent
  // with no explicit permissions, seed from the preset's capability set.
  let teamRole: string | null = null;
  let teamPermissions: TeamCapability[] | null = null;
  if (role === "team") {
    const teamRoleKey: TeamRoleKey = isTeamRoleKey(rawTeamRole)
      ? rawTeamRole
      : "custom";
    teamRole = teamRoleKey;
    if (Array.isArray(rawPermissions)) {
      teamPermissions = sanitizeCapabilities(rawPermissions);
    } else if (teamRoleKey !== "custom") {
      teamPermissions = [...TEAM_ROLE_PRESETS[teamRoleKey].capabilities];
    } else {
      teamPermissions = [];
    }
  }

  // Whitelist the boolean access grants. Anything else is dropped so a
  // malicious payload cannot inject arbitrary JSON.
  const grantKeys = [
    "bump1Paid",
    "bump2Paid",
    "bump3Paid",
    "upsell1Paid",
    "upsell2Paid",
    "upsell3Paid",
    "downsell1Paid",
    "tiktokSlideshowPaid",
    "hookDemoPaid",
    "doneForYouPackPaid",
    "portfolioPaid",
    "platinumPaid",
    "isAList",
  ] as const;
  const grants: Record<string, boolean> = {};
  for (const k of grantKeys) {
    if (rawGrants && typeof rawGrants[k] === "boolean") grants[k] = rawGrants[k];
  }
  const grantsToStore = Object.keys(grants).length > 0 ? grants : null;

  const token = crypto.randomBytes(32).toString("hex");
  const expiresAt = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000);
  const normalisedEmail = email.trim().toLowerCase();

  // Re-send safety: if there is already an unclaimed invite for this email
  // we UPDATE it in place instead of inserting a duplicate. The previous
  // implementation always inserted, which caused a critical bug: an admin
  // who sent an invite with no grants and then re-sent the same invite
  // with grants ticked would end up with two rows for the same email.
  // The /portal/enroll claim picked the FIRST returned (oldest) row and
  // left the newer "real" grants orphaned. That left buyers with no
  // upgrades unlocked and forced support to fix it manually.
  //
  // The upsert below makes the latest send the source of truth: same
  // email, latest role + grants, fresh token + expiry, status reset to
  // "sent" so it can be claimed. This is also what the admin actually
  // wants when they hit Send Invite again with different toggles.
  const [existingInvite] = await db
    .select()
    .from(invitesTable)
    .where(
      and(
        eq(invitesTable.email, normalisedEmail),
        ne(invitesTable.status, "claimed"),
      ),
    )
    .orderBy(desc(invitesTable.createdAt))
    .limit(1);

  // accessLevel column kept for back-compat with the invites table schema
  // but no longer surfaced in the admin UI. Always defaults to "main".
  // portal_key is the source of truth for which portal this invite is for.
  let invite;
  if (existingInvite) {
    [invite] = await db
      .update(invitesTable)
      .set({
        token,
        accessLevel: "main",
        portalKey: invitePortalKey,
        status: "sent",
        sentBy: req.portalUser.id,
        expiresAt,
        role,
        grants: grantsToStore,
        teamRole,
        permissions: teamPermissions,
        usedAt: null,
      })
      .where(eq(invitesTable.id, existingInvite.id))
      .returning();
  } else {
    [invite] = await db
      .insert(invitesTable)
      .values({
        email: normalisedEmail,
        token,
        accessLevel: "main",
        portalKey: invitePortalKey,
        status: "sent",
        sentBy: req.portalUser.id,
        expiresAt,
        role,
        grants: grantsToStore,
        teamRole,
        permissions: teamPermissions,
      })
      .returning();
  }

  // If a portal_users row already exists for this email AND it belongs
  // to the SAME portal as this invite, apply the role + grants right
  // away instead of waiting for the next /portal/enroll call. The
  // portal-scoped lookup is critical: without it, a Room30 admin
  // inviting a user who already has an Apex account by the same email
  // would silently grant them Apex entitlements (or vice versa).
  const [existingUser] = await db
    .select()
    .from(portalUsersTable)
    .where(
      and(
        eq(portalUsersTable.email, normalisedEmail),
        eq(portalUsersTable.portalKey, invitePortalKey),
      ),
    );
  if (existingUser) {
    await applyInviteEntitlements(
      existingUser.id,
      existingUser.email,
      role,
      grantsToStore,
      invite?.accessLevel ?? null,
      teamRole,
      teamPermissions,
    );
  }

  // Every invite renders as Room30 AI (Task #661). The Apex Offers
  // product was retired in Task #491; legacy `"main"` portal_users rows
  // still exist in the DB but no longer select an Apex sign-up page.
  const signupUrl = "https://room30.ai/members/sign-up";
  const niceExpiry = expiresAt.toLocaleDateString("en-GB", {
    day: "numeric",
    month: "long",
    year: "numeric",
  });

  const recipientEmail = email.trim().toLowerCase();
  const escapedRecipient = recipientEmail
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;");
  const escapedExpiry = niceExpiry
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;");

  // Room30 AI is the only live product (Task #661); every invite renders
  // with the same copy regardless of the recipient's legacy portal_key.
  const brandName = "AI Influencer Portfolio";
  const teamSignoff = "The AI Influencer Portfolio team";
  const subjectLine = `You have been invited to the ${brandName} portal`;

  // Branded HTML body. The outer wrapper (logo, dark card, gold accent,
  // footer) is added automatically by sendEmail using the same `brand`
  // value passed below, so this only renders the inner content: intro
  // copy, a purple-gradient CTA, and the fine-print.
  const inviteBodyHtml = `
    <p style="margin:0 0 18px 0;">You have been invited to the ${brandName} portal.</p>
    <p style="margin:0 0 28px 0;">Click the button below to set up your account. Use this same email address (<strong style="color:#ffffff;">${escapedRecipient}</strong>) when you sign up so your access is matched automatically.</p>
    <table role="presentation" cellpadding="0" cellspacing="0" border="0" style="margin:0 auto 28px auto;">
      <tr>
        <td align="center" style="border-radius:12px;background:linear-gradient(135deg,#7c3aed 0%,#a855f7 50%,#c026d3 100%);box-shadow:0 12px 32px rgba(124,58,237,0.35);">
          <a href="${signupUrl}" style="display:inline-block;padding:16px 36px;font-family:Helvetica,Arial,sans-serif;font-size:13px;font-weight:bold;letter-spacing:0.18em;text-transform:uppercase;color:#ffffff;text-decoration:none;border-radius:12px;">
            Create Your Account
          </a>
        </td>
      </tr>
    </table>
    <p style="margin:0 0 8px 0;font-size:13px;color:rgba(255,255,255,0.55);">If the button does not work, copy and paste this link into your browser:</p>
    <p style="margin:0 0 24px 0;font-size:13px;word-break:break-all;"><a href="${signupUrl}" style="color:#C9A44C;text-decoration:underline;">${signupUrl}</a></p>
    <p style="margin:0 0 6px 0;font-size:13px;color:rgba(255,255,255,0.55);">This invite is valid until <strong style="color:#ffffff;">${escapedExpiry}</strong>.</p>
    <p style="margin:24px 0 0 0;">See you inside.<br /><span style="color:rgba(255,255,255,0.55);">${teamSignoff}</span></p>
  `;

  const sendResult = await sendEmail({
    email: recipientEmail,
    subject: subjectLine,
    body: `You have been invited to the ${brandName} portal.\n\nCreate your account here:\n${signupUrl}\n\nUse this same email address (${recipientEmail}) when you sign up so your access is matched automatically. This invite is valid until ${niceExpiry}.\n\nSee you inside.\n${teamSignoff}`,
    bodyHtml: inviteBodyHtml,
    templateType: "invite_sent",
    brand: "room30",
    metadata: { inviteId: invite.id, sentBy: req.portalUser.id, signupUrl, portalKey: invitePortalKey },
  });

  // The invite ROW is already persisted to Postgres above and the
  // entitlements have been applied to any existing portal_users row.
  // Whether or not Resend accepts the message is orthogonal: the admin
  // can resend the email later (or paste the signup URL directly into
  // chat / WhatsApp). Returning 502 here was wrong because:
  //
  //   1. The 502 made the admin think the WHOLE invite failed and
  //      try again, creating duplicate (or upserted-over) invites.
  //   2. The client error wrapper only surfaces `body.error`, so the
  //      admin saw the generic "API error: 502" with no clue why -
  //      they had no way to know it was an email-delivery problem,
  //      not a server crash, and no actionable next step.
  //
  // Return 200 with `emailStatus: "failed"` instead. The client
  // mutation's onSuccess inspects the field and shows the real
  // reason (Resend message, suppression list, etc.).
  res.json({
    ...invite,
    emailStatus: sendResult.status === "failed" ? "failed" : "sent",
    emailError:
      sendResult.status === "failed"
        ? sendResult.error || "Email provider rejected the message."
        : undefined,
  });
});

portalRouter.get("/portal/admin/invites", requireAuth, requireCapability("users.invite"), async (_req, res) => {
  const invites = await db.select().from(invitesTable).orderBy(desc(invitesTable.createdAt));
  res.json(invites);
});

// POST /portal/admin/users/manual
// Creates a portal_users row directly — no email sent. The user can sign
// up later using the same email address, at which point ensurePortalUserForClerk
// claims the row via the email-match path and links their Clerk ID.
portalRouter.post("/portal/admin/users/manual", requireAuth, requireCapability("users.invite"), async (req: any, res) => {
  const { email, firstName, lastName, role: rawRole, grants: rawGrants, teamRole: rawTeamRole, permissions: rawPermissions } = req.body || {};
  if (!email || typeof email !== "string") { res.status(400).json({ error: "Valid email required" }); return; }

  const callerIsAdmin = req.portalUser?.role === "admin" || !!req.appUser?.isSuperAdmin;
  const allowedRoles = ["student", "team", "admin"] as const;
  const role: "student" | "team" | "admin" = allowedRoles.includes(rawRole) ? rawRole : "student";

  if (role === "admin" && !req.appUser?.isSuperAdmin) {
    res.status(403).json({ error: "Only the portal owner can add an Admin." }); return;
  }
  if ((role === "team" || role === "admin") && !callerIsAdmin) {
    res.status(403).json({ error: "Only an admin can add team members." }); return;
  }

  const grantKeys = [
    "bump1Paid","bump2Paid","bump3Paid","upsell1Paid","upsell2Paid","upsell3Paid",
    "downsell1Paid","tiktokSlideshowPaid","hookDemoPaid","doneForYouPackPaid",
    "portfolioPaid","platinumPaid","isAList",
  ] as const;
  const grants: Record<string, boolean> = {};
  for (const k of grantKeys) {
    if (rawGrants && typeof rawGrants[k] === "boolean") grants[k] = rawGrants[k];
  }
  const grantsToStore = Object.keys(grants).length > 0 ? grants : null;

  let teamRole: string | null = null;
  let teamPermissions: TeamCapability[] | null = null;
  if (role === "team") {
    const teamRoleKey: TeamRoleKey = isTeamRoleKey(rawTeamRole) ? rawTeamRole : "custom";
    teamRole = teamRoleKey;
    if (Array.isArray(rawPermissions)) {
      teamPermissions = sanitizeCapabilities(rawPermissions);
    } else if (teamRoleKey !== "custom") {
      teamPermissions = [...TEAM_ROLE_PRESETS[teamRoleKey].capabilities];
    } else {
      teamPermissions = [];
    }
  }

  const normalisedEmail = email.trim().toLowerCase();
  const portalKey = getPortalKey(req);

  // Check if a portal_users row already exists for this email + portal.
  const [existing] = await db
    .select()
    .from(portalUsersTable)
    .where(
      and(
        sql`lower(${portalUsersTable.email}) = lower(${normalisedEmail})`,
        eq(portalUsersTable.portalKey, portalKey),
      ),
    )
    .limit(1);

  let user;
  if (existing) {
    // Apply entitlements to the existing row (same logic as invite claim).
    await applyInviteEntitlements(existing.id, existing.email, role, grantsToStore, null, teamRole, teamPermissions);
    if (firstName || lastName) {
      await db.update(portalUsersTable).set({
        ...(firstName ? { firstName } : {}),
        ...(lastName ? { lastName } : {}),
        updatedAt: new Date(),
      }).where(eq(portalUsersTable.id, existing.id));
    }
    const [refreshed] = await db.select().from(portalUsersTable).where(eq(portalUsersTable.id, existing.id));
    user = refreshed;
  } else {
    // Insert a brand-new pre-created account (no Clerk ID yet).
    const [inserted] = await db
      .insert(portalUsersTable)
      .values({
        email: normalisedEmail,
        firstName: firstName ?? null,
        lastName: lastName ?? null,
        role,
        portalKey,
        isActive: true,
        ...(role === "team" ? { teamRole, permissions: teamPermissions } : {}),
      })
      .returning();
    user = inserted;
    // Apply grants (isAList + synthetic order row) using the shared helper.
    if (grantsToStore) {
      await applyInviteEntitlements(user.id, user.email, role, grantsToStore, null, teamRole, teamPermissions);
    }
  }

  res.json({ user, created: !existing });
});

portalRouter.patch("/portal/admin/users/:userId/role", requireAuth, requireAdmin, async (req: any, res) => {
  const userId = parseInt(req.params.userId);
  if (isNaN(userId)) { res.status(400).json({ error: "Invalid user ID" }); return; }
  // Cross-portal isolation: a portal admin can only mutate the role of
  // users in their own portal. Without this guard a Room30 admin could
  // demote/promote an Apex Offers user (or vice versa) just by knowing
  // their numeric id.
  const [targetUser] = await db.select({ portalKey: portalUsersTable.portalKey }).from(portalUsersTable).where(eq(portalUsersTable.id, userId));
  if (!targetUser || !(req.appUser?.isSuperAdmin && getPortalKey(req) === "room30") && (targetUser.portalKey || "main") !== getPortalKey(req)) {
    res.status(404).json({ error: "User not found" }); return;
  }
  const { role, teamRole: rawTeamRole, permissions: rawPermissions } = req.body;
  // Three-tier role system. "team" is an internal staff label that sits
  // between student and admin. Since Task #796 a "team" member carries a
  // granular capability list (`permissions`) that requireCapability gates
  // against; "admin" still implicitly holds every capability.
  const validRoles = ["student", "team", "admin"];
  if (!validRoles.includes(role)) { res.status(400).json({ error: "Invalid role" }); return; }
  // Only the super admin (env-pinned ADMIN_EMAILS owner) may grant the
  // "admin" role. Other portal admins can promote/demote between
  // student and team only. This stops a portal admin from minting
  // additional portal admins.
  if (role === "admin" && !req.appUser?.isSuperAdmin) {
    res.status(403).json({ error: "Only the portal owner can grant the Admin role." }); return;
  }

  // Task #796: keep the team columns coherent with the role.
  //   - role=team  -> store the preset + sanitized capability list (seed
  //                   from the preset when no explicit list is sent).
  //   - role!=team -> clear both columns so a demoted member can never
  //                   retain stale staff capabilities.
  const patch: Record<string, unknown> = { role, updatedAt: new Date() };
  if (role === "team") {
    const teamRole = isTeamRoleKey(rawTeamRole) ? rawTeamRole : "custom";
    let permissions: TeamCapability[];
    if (Array.isArray(rawPermissions)) {
      permissions = sanitizeCapabilities(rawPermissions);
    } else if (teamRole !== "custom") {
      permissions = [...TEAM_ROLE_PRESETS[teamRole].capabilities];
    } else {
      permissions = [];
    }
    patch.teamRole = teamRole;
    patch.permissions = permissions;
  } else {
    patch.teamRole = null;
    patch.permissions = null;
  }

  const [updated] = await db.update(portalUsersTable).set(patch).where(eq(portalUsersTable.id, userId)).returning();
  res.json(updated);
});

// Task #796: update an existing team member's preset + capability list
// without touching their role. Admin / super-admin only (a team member can
// never edit capabilities - their own or anyone else's). Returns 400 if the
// target is not currently a "team" member so this can't be used to silently
// attach capabilities to a student or admin row.
portalRouter.patch("/portal/admin/users/:userId/team-permissions", requireAuth, requireAdmin, async (req: any, res) => {
  const userId = parseInt(req.params.userId);
  if (isNaN(userId)) { res.status(400).json({ error: "Invalid user ID" }); return; }
  const [user] = await db.select().from(portalUsersTable).where(eq(portalUsersTable.id, userId));
  if (!user) { res.status(404).json({ error: "User not found" }); return; }
  // Cross-portal isolation, mirroring the other per-user admin endpoints.
  if (!(req.appUser?.isSuperAdmin && getPortalKey(req) === "room30") && (user.portalKey || "main") !== getPortalKey(req)) {
    res.status(404).json({ error: "User not found" }); return;
  }
  if (user.role !== "team") {
    res.status(400).json({ error: "User is not a team member. Set their role to Team first." }); return;
  }
  const { teamRole: rawTeamRole, permissions: rawPermissions } = req.body || {};
  const teamRole = isTeamRoleKey(rawTeamRole) ? rawTeamRole : "custom";
  let permissions: TeamCapability[];
  if (Array.isArray(rawPermissions)) {
    permissions = sanitizeCapabilities(rawPermissions);
  } else if (teamRole !== "custom") {
    permissions = [...TEAM_ROLE_PRESETS[teamRole].capabilities];
  } else {
    permissions = [];
  }
  const [updated] = await db
    .update(portalUsersTable)
    .set({ teamRole, permissions, updatedAt: new Date() })
    .where(eq(portalUsersTable.id, userId))
    .returning();
  res.json(updated);
});

// Read what a user currently has access to. Combines real Whop order
// rows (from computePurchaseEntitlements) with the synthetic
// admin-grant order row used for manual grants. Returned shape matches
// what the admin UI toggles render.
portalRouter.get("/portal/admin/users/:userId/access", requireAuth, requireCapability("users.view"), async (req: any, res) => {
  const userId = parseInt(req.params.userId);
  if (isNaN(userId)) { res.status(400).json({ error: "Invalid user ID" }); return; }
  const [user] = await db.select().from(portalUsersTable).where(eq(portalUsersTable.id, userId));
  if (!user) { res.status(404).json({ error: "User not found" }); return; }
  // Cross-portal isolation: a portal admin can only see/touch users who
  // belong to their own portal. The super admin is no exception - the
  // portal switcher is the source of truth, and crossing it requires
  // switching portals, not bypassing the guard.
  if (!(req.appUser?.isSuperAdmin && getPortalKey(req) === "room30") && (user.portalKey || "main") !== getPortalKey(req)) {
    res.status(404).json({ error: "User not found" }); return;
  }
  const entitlements = await computePurchaseEntitlements(user);
  res.json({
    userId,
    email: user.email,
    isAList: !!user.isAList,
    mainProductPaid: entitlements.mainProductPaid,
    bump1Paid: entitlements.bump1Paid,
    bump2Paid: entitlements.bump2Paid,
    bump3Paid: entitlements.bump3Paid,
    upsell1Paid: entitlements.upsell1Paid,
    upsell2Paid: entitlements.upsell2Paid,
    upsell3Paid: entitlements.upsell3Paid,
    downsell1Paid: entitlements.downsell1Paid,
    tiktokSlideshowPaid: entitlements.tiktokSlideshowPaid,
    hookDemoPaid: entitlements.hookDemoPaid,
    doneForYouPackPaid: entitlements.doneForYouPackPaid,
    portfolioPaid: entitlements.portfolioPaid,
    platinumPaid: entitlements.platinumPaid,
    // Raw per-user counter (not the computed total bonus). The admin
    // UI sums this with the upsell2-derived +5 itself to render the
    // total cap. Reads straight off the portal_users row so the input
    // always reflects what the operator last typed, regardless of
    // whether the user's Upsell 2 flag changed in the meantime.
    bonusInfluencerQuota: user.bonusInfluencerQuota ?? 0,
  });
});

// Grant or revoke individual entitlements for a user. Writes to a
// synthetic order row (id = `admin-grant-<userId>`) so real Whop order
// rows are never mutated. computePurchaseEntitlements ORs across all
// rows for an email, so the synthetic row's flags add to whatever the
// user already has from real purchases. To revoke an entitlement that
// came from a real Whop order we cannot remove it here (we will not
// touch real orders); the toggle will simply remain on. The UI shows
// a hint when that is the case.
portalRouter.patch("/portal/admin/users/:userId/access", requireAuth, requireCapability("users.grant_access"), async (req: any, res) => {
  const userId = parseInt(req.params.userId);
  if (isNaN(userId)) { res.status(400).json({ error: "Invalid user ID" }); return; }
  const [user] = await db.select().from(portalUsersTable).where(eq(portalUsersTable.id, userId));
  if (!user) { res.status(404).json({ error: "User not found" }); return; }
  // Cross-portal isolation: a portal admin can only see/touch users who
  // belong to their own portal. Super admin still scoped to the
  // requested portal so the portal switcher remains authoritative.
  if (!(req.appUser?.isSuperAdmin && getPortalKey(req) === "room30") && (user.portalKey || "main") !== getPortalKey(req)) {
    res.status(404).json({ error: "User not found" }); return;
  }

  const allowedKeys = [
    "mainProductPaid",
    "bump1Paid",
    "bump2Paid",
    "bump3Paid",
    "upsell1Paid",
    "upsell2Paid",
    "upsell3Paid",
    "downsell1Paid",
    "tiktokSlideshowPaid",
    "hookDemoPaid",
    "doneForYouPackPaid",
    "portfolioPaid",
    "platinumPaid",
  ] as const;
  type AccessFlagKey = (typeof allowedKeys)[number];
  const patch: Partial<Record<AccessFlagKey, boolean>> = {};
  for (const k of allowedKeys) {
    if (typeof req.body?.[k] === "boolean") patch[k] = req.body[k];
  }
  if (Object.keys(patch).length === 0) {
    res.status(400).json({ error: "No valid access flags provided" }); return;
  }

  const syntheticId = `admin-grant-${userId}`;
  const [existing] = await db.select().from(ordersTable).where(eq(ordersTable.id, syntheticId));
  // Task #646: detect any flag flipped from true -> false so we can
  // mirror the admin revoke into the internal Sales CRM after the
  // write lands. Computed before the UPDATE so we can compare against
  // the prior synthetic-row state. All keys in `patch` are constrained
  // to `AccessFlagKey`, which are all real boolean columns on the
  // orders table, so the indexed read is fully typed.
  const revokedFlags: AccessFlagKey[] = [];
  if (existing) {
    for (const k of allowedKeys) {
      if (patch[k] === false && existing[k] === true) {
        revokedFlags.push(k);
      }
    }
  }
  if (existing) {
    await db
      .update(ordersTable)
      .set({ ...patch, updatedAt: new Date() })
      .where(eq(ordersTable.id, syntheticId));
  } else {
    // mainProductPaid defaults to FALSE on the synthetic row. Task #668
    // allows admins to flip it to TRUE here as a manual comp of the
    // $27 AI Influencer Masterclass; in that case `...patch` overrides
    // the default below. Even when true the synthetic row is never
    // mistaken for a real paid main order: it carries no Stripe / GHL /
    // Whop receipt id and its provenance is `admin_grant`, so the
    // enrol / setup / verify flows that key off receipt ids continue
    // to ignore it.
    await db.insert(ordersTable).values({
      id: syntheticId,
      email: user.email,
      currentStep: "admin-granted",
      mainProductPaid: false,
      ...patch,
    });
  }

  // If the user is inactive and at least one flag is being turned ON,
  // auto-activate them so the grants immediately take effect. Manually
  // created users (no Clerk ID yet) start with isActive=false; granting
  // access without activating leaves the account in a broken state where
  // the flags are stored but every portal endpoint rejects the user.
  const anyFlagGranted = Object.values(patch).some((v) => v === true);
  if (anyFlagGranted && !user.isActive) {
    await db
      .update(portalUsersTable)
      .set({ isActive: true, updatedAt: new Date() })
      .where(eq(portalUsersTable.id, userId));
  }

  // Task #646: if the admin flipped any entitlement from granted ->
  // revoked, mirror that into the internal Sales CRM so reps stop
  // working a row that no longer has access. Best-effort - errors
  // never block the admin response.
  if (revokedFlags.length > 0 && user.email) {
    try {
      const { markCrmContactRefunded } = await import("../lib/crm-ingest");
      void markCrmContactRefunded({
        email: user.email,
        reason: "admin_revoke",
        detail: `flags=${revokedFlags.join(",")} actor=${req.appUser?.email ?? "admin"}`,
        source: "admin",
        payload: {
          revokedFlags,
          userId,
          actorEmail: req.appUser?.email ?? null,
        },
      });
    } catch (err: unknown) {
      req.log?.warn?.(
        {
          err: err instanceof Error ? err.message : String(err),
          userId,
          email: user.email,
        },
        "[admin-grant] CRM refund mirror dispatch failed",
      );
    }
  }

  const fresh = await db.select().from(portalUsersTable).where(eq(portalUsersTable.id, userId));
  const entitlements = await computePurchaseEntitlements(fresh[0]);
  res.json({
    userId,
    email: user.email,
    isAList: !!fresh[0].isAList,
    mainProductPaid: entitlements.mainProductPaid,
    bump1Paid: entitlements.bump1Paid,
    bump2Paid: entitlements.bump2Paid,
    bump3Paid: entitlements.bump3Paid,
    upsell1Paid: entitlements.upsell1Paid,
    upsell2Paid: entitlements.upsell2Paid,
    upsell3Paid: entitlements.upsell3Paid,
    downsell1Paid: entitlements.downsell1Paid,
    tiktokSlideshowPaid: entitlements.tiktokSlideshowPaid,
    hookDemoPaid: entitlements.hookDemoPaid,
    doneForYouPackPaid: entitlements.doneForYouPackPaid,
    portfolioPaid: entitlements.portfolioPaid,
    platinumPaid: entitlements.platinumPaid,
  });
});

// PATCH /portal/admin/users/:userId/influencer-bonus
//
// Manually grant N bonus AI Influencer generations to a buyer on top of
// the base entitlement (1 free + 5 from upsell2Paid). Writes
// `portal_users.bonus_influencer_quota`. computePurchaseEntitlements
// sums this onto whatever the buyer already has, so total cap =
// 1 + (upsell2 ? 5 : 0) + bonusInfluencerQuota.
//
// Body: `{ add: N }` to increment by N (can be negative to take some
// back), OR `{ set: N }` to overwrite to exactly N. Floor is 0 - the
// value will never persist below zero. No upper cap; the operator owns
// that judgment.
portalRouter.patch(
  "/portal/admin/users/:userId/influencer-bonus",
  requireAuth,
  requireAdmin,
  async (req: any, res) => {
    const userId = parseInt(req.params.userId);
    if (isNaN(userId)) {
      res.status(400).json({ error: "Invalid user ID" });
      return;
    }
    const [user] = await db
      .select()
      .from(portalUsersTable)
      .where(eq(portalUsersTable.id, userId));
    if (!user) {
      res.status(404).json({ error: "User not found" });
      return;
    }
    if (
      !(req.appUser?.isSuperAdmin && getPortalKey(req) === "room30") &&
      (user.portalKey || "main") !== getPortalKey(req)
    ) {
      res.status(404).json({ error: "User not found" });
      return;
    }

    const add = typeof req.body?.add === "number" ? Math.trunc(req.body.add) : null;
    const set = typeof req.body?.set === "number" ? Math.trunc(req.body.set) : null;
    if (add === null && set === null) {
      res
        .status(400)
        .json({ error: "missing_field", message: "Provide either { add: N } or { set: N }." });
      return;
    }
    if (add !== null && set !== null) {
      res
        .status(400)
        .json({ error: "conflicting_fields", message: "Provide only one of { add } or { set }, not both." });
      return;
    }

    const before = user.bonusInfluencerQuota ?? 0;
    const nextRaw = set !== null ? set : before + (add ?? 0);
    const next = Math.max(0, nextRaw);

    await db
      .update(portalUsersTable)
      .set({ bonusInfluencerQuota: next })
      .where(eq(portalUsersTable.id, userId));

    req.log?.info?.(
      {
        event: "admin_influencer_bonus_set",
        userId,
        email: user.email,
        before,
        after: next,
        delta: next - before,
        actorEmail: req.appUser?.email ?? null,
      },
      "[admin] influencer-bonus updated",
    );

    res.json({
      userId,
      email: user.email,
      bonusInfluencerQuota: next,
      previous: before,
      delta: next - before,
    });
  },
);

// POST /portal/admin/users/:userId/resend-invite
//
// Re-fires the post-purchase enrollment email (Clerk invitation link for
// new accounts, or "training unlocked" notice for returning customers)
// for a user the admin has already granted access to. Use cases:
//   - Buyer says they never received the welcome email (spam / typo / etc).
//   - Admin just flipped an entitlement via PATCH /access and wants the
//     buyer notified.
//   - Re-sending after the Clerk invite expired (7-day TTL upstream).
//
// Bypasses the per-(email, orderId) `email_logs` dedupe via
// `forceResend: true` so the same orderId can be re-sent. Picks the
// most recent paid order for the user's email; falls back to the
// synthetic `admin-grant-<userId>` row when the user only has
// admin-granted access. Returns the enrollment result so the admin UI
// can show "Sent" vs "Already had account" vs the failure reason.
portalRouter.post(
  "/portal/admin/users/:userId/resend-invite",
  requireAuth,
  requireCapability("users.invite"),
  async (req: any, res) => {
    const userId = parseInt(req.params.userId);
    if (isNaN(userId)) {
      res.status(400).json({ error: "Invalid user ID" });
      return;
    }
    const [user] = await db
      .select()
      .from(portalUsersTable)
      .where(eq(portalUsersTable.id, userId));
    if (!user) {
      res.status(404).json({ error: "User not found" });
      return;
    }
    // Cross-portal isolation: a portal admin can only touch users who
    // belong to their own portal. Super admin still scoped to the
    // requested portal so the portal switcher remains authoritative.
    if (
      !(req.appUser?.isSuperAdmin && getPortalKey(req) === "room30") &&
      (user.portalKey || "main") !== getPortalKey(req)
    ) {
      res.status(404).json({ error: "User not found" });
      return;
    }
    if (!user.email) {
      res.status(400).json({ error: "User has no email on file" });
      return;
    }

    // Gate on actual access. We refuse to send a "your training is
    // unlocked" email to a user who has never been granted anything -
    // that would be misleading and create support tickets. Any paid
    // flag (real or admin-granted) is enough.
    const entitlements = await computePurchaseEntitlements(user);
    const hasAnyAccess =
      entitlements.mainProductPaid ||
      entitlements.bump1Paid ||
      entitlements.bump2Paid ||
      entitlements.bump3Paid ||
      entitlements.upsell1Paid ||
      entitlements.upsell2Paid ||
      entitlements.upsell3Paid ||
      entitlements.downsell1Paid ||
      entitlements.tiktokSlideshowPaid ||
      entitlements.hookDemoPaid ||
      entitlements.doneForYouPackPaid ||
      entitlements.portfolioPaid ||
      entitlements.platinumPaid ||
      !!user.isAList;
    if (!hasAnyAccess) {
      res.status(409).json({
        error: "no_access",
        message:
          "This user has no entitlements yet. Grant access first, then re-send the invite.",
      });
      return;
    }

    // Cooldown: refuse to spam the buyer if a welcome / training-unlocked
    // email already went out (or failed) for this address in the last 60
    // seconds. Admin-only scope means abuse is unlikely but two quick
    // double-clicks on the admin button would otherwise mint two Clerk
    // invitations.
    const normEmail = user.email.trim().toLowerCase();
    const cooldownSince = new Date(Date.now() - 60 * 1000);
    const [recentSend] = await db
      .select({ id: emailLogsTable.id, sentAt: emailLogsTable.sentAt })
      .from(emailLogsTable)
      .where(
        and(
          eq(emailLogsTable.email, normEmail),
          inArray(emailLogsTable.templateType, [
            "purchase_account_created",
            "purchase_account_existing",
          ]),
          gte(emailLogsTable.sentAt, cooldownSince),
        ),
      )
      .orderBy(desc(emailLogsTable.sentAt))
      .limit(1);
    if (recentSend) {
      res.status(429).json({
        error: "cooldown",
        message:
          "An enrollment email was already sent to this user in the last minute. Try again shortly.",
        retryAfterSeconds: 60,
      });
      return;
    }

    // OrderId selection (in priority order):
    //   1. portal_users.orderId - the order this portal_users row was
    //      originally created from. This is the most accurate audit
    //      anchor because it can never point to a sibling Whop/Stripe
    //      order belonging to the same email but the wrong portal.
    //   2. Most recent paid order for this email - covers users whose
    //      portal_users row predates the orderId column or who paid
    //      a follow-up upgrade without re-enrollment. Filtered to
    //      mainProductPaid=true so refunded/abandoned orders are
    //      skipped.
    //   3. `admin-grant-<userId>` synthetic - admin-only comps that
    //      never had a real Stripe/Whop/GHL order.
    // The orderId is used as the `email_logs` dedupe key (bypassed
    // here via forceResend) and stamped into Clerk invitation
    // metadata, so it must be stable and meaningful for support.
    let orderId: string;
    if (user.orderId) {
      orderId = user.orderId;
    } else {
      const [latestOrder] = await db
        .select({ id: ordersTable.id })
        .from(ordersTable)
        .where(
          and(
            sql`lower(${ordersTable.email}) = ${normEmail}`,
            eq(ordersTable.mainProductPaid, true),
          ),
        )
        .orderBy(desc(ordersTable.createdAt))
        .limit(1);
      orderId = latestOrder?.id ?? `admin-grant-${userId}`;
    }

    try {
      const result = await enrollPurchaserAndSendEmail({
        email: user.email,
        orderId,
        portalKey:
          (user.portalKey as "room30" | "main" | undefined) ?? "room30",
        forceResend: true,
        extraMetadata: {
          resentByAdminId: req.portalUser?.id ?? null,
          resentByAdminEmail: req.appUser?.email ?? null,
          resentAt: new Date().toISOString(),
          source: "admin_resend_invite",
        },
      });
      req.log?.info?.(
        {
          userId,
          email: user.email,
          orderId,
          adminId: req.portalUser?.id ?? null,
          result,
        },
        "[admin-resend-invite] enrollment email re-sent",
      );
      // Surface provider-level failures (Resend rejected the message,
      // bad recipient, etc) instead of silently returning "ok". The
      // admin UI keys on `ok` to render the success toast.
      if (result.status === "failed") {
        res.status(502).json({
          ok: false,
          userId,
          email: user.email,
          orderId,
          result,
          error: "send_failed",
          message: result.error,
        });
        return;
      }
      res.json({
        ok: true,
        userId,
        email: user.email,
        orderId,
        result,
      });
    } catch (err: any) {
      req.log?.error?.(
        {
          err: err?.message,
          userId,
          email: user.email,
          orderId,
        },
        "[admin-resend-invite] enrollment email re-send failed",
      );
      res.status(502).json({
        error: "resend_failed",
        message: err?.message || "Could not re-send the invite email.",
      });
    }
  },
);

// ───────────────────────────────────────────────────────────────────────────
// Admin: AI Influencer generations per user
//
// Lets support see every AI Influencer generation job a buyer has submitted,
// the form preferences they filled in, the current pipeline status (queued,
// generating_base, enhancing, swapping_scenes, ready, failed), per-scene
// state, and provider error fields - and force-retry a stuck job through
// the worker on the next tick.
//
// Linkage: ai_influencer_jobs.client_id and ai_influencers.client_id both
// reference app_users.id (NOT portal_users.id). We resolve a portal_users
// row to its app_users counterpart by clerk_id first, then by lower-cased
// email so legacy rows without a clerk_id still work.
// ───────────────────────────────────────────────────────────────────────────
// Resolve a portal_users row to the matching app_users (clientId for
// ai_influencer_jobs / ai_influencers). Clerk id is unique on app_users so
// that mapping is exact. Email is NOT unique on app_users, so on the email
// fallback we explicitly require exactly one match - multiple matches
// (legacy duplicate signups) return `linkReason: "ambiguous_email"` and the
// caller must refuse to act rather than silently target the wrong account.
async function resolveAppUserIdForPortalUser(userId: number): Promise<
  | {
      portalUser: any;
      appUserId: number | null;
      linkReason: "clerk" | "email" | "ambiguous_email" | "not_found";
    }
  | null
> {
  const [pu] = await db
    .select({ id: portalUsersTable.id, email: portalUsersTable.email, clerkId: portalUsersTable.clerkId, portalKey: portalUsersTable.portalKey })
    .from(portalUsersTable)
    .where(eq(portalUsersTable.id, userId))
    .limit(1);
  if (!pu) return null;
  if (pu.clerkId) {
    const [byClerk] = await db
      .select({ id: appUsers.id })
      .from(appUsers)
      .where(eq(appUsers.clerkId, pu.clerkId))
      .limit(1);
    if (byClerk?.id) return { portalUser: pu, appUserId: byClerk.id, linkReason: "clerk" };
  }
  if (pu.email) {
    const matches = await db
      .select({ id: appUsers.id })
      .from(appUsers)
      .where(sql`lower(${appUsers.email}) = lower(${pu.email})`)
      .limit(2);
    if (matches.length === 1) return { portalUser: pu, appUserId: matches[0].id, linkReason: "email" };
    if (matches.length > 1) return { portalUser: pu, appUserId: null, linkReason: "ambiguous_email" };
  }
  return { portalUser: pu, appUserId: null, linkReason: "not_found" };
}

// Cross-portal isolation, mirroring the resend-invite gate above. Returns
// true when the caller is allowed to touch this portal_users row.
function adminMayAccessPortalUser(req: any, user: { portalKey: string | null }): boolean {
  if (req.appUser?.isSuperAdmin && getPortalKey(req) === "room30") return true;
  return (user.portalKey || "main") === getPortalKey(req);
}

function summarizeScenes(scenes: any): { total: number; completed: number; failed: number; processing: number; pending: number } {
  const list = Array.isArray(scenes) ? scenes : [];
  let completed = 0, failed = 0, processing = 0, pending = 0;
  for (const s of list) {
    if (s?.state === "completed") completed++;
    else if (s?.state === "failed") failed++;
    else if (s?.state === "processing") processing++;
    else pending++;
  }
  return { total: list.length, completed, failed, processing, pending };
}

portalRouter.get(
  "/portal/admin/users/:userId/influencers",
  requireAuth,
  requireAdmin,
  async (req: any, res) => {
    const userId = parseInt(req.params.userId);
    if (isNaN(userId)) { res.status(400).json({ error: "Invalid user ID" }); return; }
    try {
      const resolved = await resolveAppUserIdForPortalUser(userId);
      if (!resolved) { res.status(404).json({ error: "user_not_found" }); return; }
      const { portalUser, appUserId, linkReason } = resolved;
      if (!adminMayAccessPortalUser(req, portalUser)) {
        res.status(404).json({ error: "user_not_found" });
        return;
      }
      if (!appUserId) {
        res.json({ portalUser, appUserId: null, linkReason, jobs: [], influencers: [] });
        return;
      }
      const [jobs, influencers] = await Promise.all([
        db
          .select({
            id: aiInfluencerJobsTable.id,
            influencerId: aiInfluencerJobsTable.influencerId,
            status: aiInfluencerJobsTable.status,
            progress: aiInfluencerJobsTable.progress,
            prefs: aiInfluencerJobsTable.prefs,
            isFreeTier: aiInfluencerJobsTable.isFreeTier,
            baseImageUrl: aiInfluencerJobsTable.baseImageUrl,
            enhancedImageUrl: aiInfluencerJobsTable.enhancedImageUrl,
            sceneImageUrls: aiInfluencerJobsTable.sceneImageUrls,
            scenes: aiInfluencerJobsTable.scenes,
            failureReason: aiInfluencerJobsTable.failureReason,
            lastErrorCode: aiInfluencerJobsTable.lastErrorCode,
            lastErrorMessage: aiInfluencerJobsTable.lastErrorMessage,
            finalizeAttempts: aiInfluencerJobsTable.finalizeAttempts,
            etaAt: aiInfluencerJobsTable.etaAt,
            nextAttemptAt: aiInfluencerJobsTable.nextAttemptAt,
            heartbeatAt: aiInfluencerJobsTable.heartbeatAt,
            stageStartedAt: aiInfluencerJobsTable.stageStartedAt,
            emailSentAt: aiInfluencerJobsTable.emailSentAt,
            completedAt: aiInfluencerJobsTable.completedAt,
            createdAt: aiInfluencerJobsTable.createdAt,
            updatedAt: aiInfluencerJobsTable.updatedAt,
          })
          .from(aiInfluencerJobsTable)
          .where(eq(aiInfluencerJobsTable.clientId, appUserId))
          .orderBy(desc(aiInfluencerJobsTable.createdAt)),
        db
          .select()
          .from(aiInfluencersTable)
          .where(eq(aiInfluencersTable.clientId, appUserId))
          .orderBy(desc(aiInfluencersTable.createdAt)),
      ]);
      const jobsOut = jobs.map((j) => ({
        ...j,
        sceneSummary: summarizeScenes(j.scenes),
        sceneImageCount: Array.isArray(j.sceneImageUrls) ? j.sceneImageUrls.length : 0,
      }));
      res.json({ portalUser, appUserId, jobs: jobsOut, influencers });
    } catch (err: any) {
      req.log?.error?.({ err: err?.message, userId }, "[admin-influencers] list failed");
      res.status(500).json({ error: "internal_error", message: err?.message });
    }
  },
);

portalRouter.get(
  "/portal/admin/influencer-jobs/:jobId",
  requireAuth,
  requireAdmin,
  async (req: any, res) => {
    const jobId = parseInt(req.params.jobId);
    if (isNaN(jobId)) { res.status(400).json({ error: "Invalid job ID" }); return; }
    try {
      const [job] = await db
        .select()
        .from(aiInfluencerJobsTable)
        .where(eq(aiInfluencerJobsTable.id, jobId))
        .limit(1);
      if (!job) { res.status(404).json({ error: "job_not_found" }); return; }
      const [influencer] = job.influencerId
        ? await db
            .select()
            .from(aiInfluencersTable)
            .where(eq(aiInfluencersTable.id, job.influencerId))
            .limit(1)
        : [null];
      const [owner] = await db
        .select({ id: appUsers.id, email: appUsers.email, name: appUsers.name, clerkId: appUsers.clerkId })
        .from(appUsers)
        .where(eq(appUsers.id, job.clientId))
        .limit(1);
      let portalUser: any = null;
      if (owner?.clerkId) {
        const [pu] = await db
          .select({ id: portalUsersTable.id, email: portalUsersTable.email, portalKey: portalUsersTable.portalKey })
          .from(portalUsersTable)
          .where(eq(portalUsersTable.clerkId, owner.clerkId))
          .limit(1);
        if (pu) portalUser = pu;
      }
      if (!portalUser && owner?.email) {
        const [pu] = await db
          .select({ id: portalUsersTable.id, email: portalUsersTable.email, portalKey: portalUsersTable.portalKey })
          .from(portalUsersTable)
          .where(sql`lower(${portalUsersTable.email}) = lower(${owner.email})`)
          .limit(1);
        if (pu) portalUser = pu;
      }
      // Cross-portal isolation: only super admins on room30 can inspect
      // jobs whose owner sits in a different portal. If we cannot locate
      // a portal_users row at all, fall through (super admin only) so
      // orphaned buyer jobs are still inspectable for support.
      if (portalUser) {
        if (!adminMayAccessPortalUser(req, portalUser)) {
          res.status(404).json({ error: "job_not_found" });
          return;
        }
      } else if (!(req.appUser?.isSuperAdmin && getPortalKey(req) === "room30")) {
        res.status(404).json({ error: "job_not_found" });
        return;
      }
      res.json({
        job: { ...job, sceneSummary: summarizeScenes(job.scenes) },
        influencer,
        owner: owner || null,
        portalUser,
      });
    } catch (err: any) {
      req.log?.error?.({ err: err?.message, jobId }, "[admin-influencer-job] get failed");
      res.status(500).json({ error: "internal_error", message: err?.message });
    }
  },
);

// POST /portal/admin/influencer-jobs/:jobId/push-through
// "Unstick" a wedged job so the next worker tick picks it up. Clears the
// stage-level retry gate (next_attempt_at), wipes the lingering error
// fields, resets BOTH finalize_attempts and the `retries` JSON map (the
// real per-stage retry budget consulted by bumpRetry/getRetry inside
// finalizeReadyJobs / advanceQueuedJobs / runSceneSwaps - see
// lib/influencer-pipeline.ts), drops heartbeat_at (so the stuck-job
// sweeper does not skip it), and clears per-scene next_attempt_at /
// lastError fields on any failed or pending scenes. Does NOT touch
// eta_at, scene image urls, or status - the worker decides what stage to
// re-drive based on existing state.
//
// Safety guards:
//  - Terminal jobs (status in ready / ready_degraded / failed) are
//    rejected with 409. Use scripts/cleanup-influencer-job.ts to
//    terminate.
//  - Active jobs (heartbeat within the last 2 minutes and no error
//    code / nextAttemptAt) are rejected with 409 `job_active` unless
//    `?force=1` is passed - otherwise we would race the live worker and
//    risk duplicate provider calls (Higgsfield/Enhancor/Gemini cost).
//  - The UPDATE is gated by a CAS on the original status so a concurrent
//    worker transition (e.g. swapping_scenes -> ready) is not silently
//    overwritten; if the CAS misses we return 409 `job_changed`.
portalRouter.post(
  "/portal/admin/influencer-jobs/:jobId/push-through",
  requireAuth,
  requireAdmin,
  async (req: any, res) => {
    const jobId = parseInt(req.params.jobId);
    if (isNaN(jobId)) { res.status(400).json({ error: "Invalid job ID" }); return; }
    const force = req.query?.force === "1" || req.query?.force === "true";
    try {
      const [job] = await db
        .select()
        .from(aiInfluencerJobsTable)
        .where(eq(aiInfluencerJobsTable.id, jobId))
        .limit(1);
      if (!job) { res.status(404).json({ error: "job_not_found" }); return; }
      if (job.status === "ready" || job.status === "ready_degraded" || job.status === "failed") {
        res.status(409).json({ error: "job_terminal", status: job.status });
        return;
      }
      // Cross-portal isolation - resolve owner -> portal_users -> portalKey.
      const [owner] = await db
        .select({ email: appUsers.email, clerkId: appUsers.clerkId })
        .from(appUsers)
        .where(eq(appUsers.id, job.clientId))
        .limit(1);
      let ownerPortalUser: { portalKey: string | null } | null = null;
      if (owner?.clerkId) {
        const [pu] = await db
          .select({ portalKey: portalUsersTable.portalKey })
          .from(portalUsersTable)
          .where(eq(portalUsersTable.clerkId, owner.clerkId))
          .limit(1);
        if (pu) ownerPortalUser = pu;
      }
      if (!ownerPortalUser && owner?.email) {
        const [pu] = await db
          .select({ portalKey: portalUsersTable.portalKey })
          .from(portalUsersTable)
          .where(sql`lower(${portalUsersTable.email}) = lower(${owner.email})`)
          .limit(1);
        if (pu) ownerPortalUser = pu;
      }
      if (ownerPortalUser) {
        if (!adminMayAccessPortalUser(req, ownerPortalUser)) {
          res.status(404).json({ error: "job_not_found" });
          return;
        }
      } else if (!(req.appUser?.isSuperAdmin && getPortalKey(req) === "room30")) {
        res.status(404).json({ error: "job_not_found" });
        return;
      }
      // Staleness check - refuse to interfere with a job that is plainly
      // still progressing on its own.
      const heartbeatMs = job.heartbeatAt ? new Date(job.heartbeatAt).getTime() : 0;
      const ageMs = Date.now() - heartbeatMs;
      const looksActive =
        !!job.heartbeatAt &&
        ageMs < 2 * 60 * 1000 &&
        !job.lastErrorCode &&
        !job.nextAttemptAt;
      if (looksActive && !force) {
        res.status(409).json({
          error: "job_active",
          message: "Job heartbeat is fresh and no retry gate is set; pass ?force=1 to override.",
          heartbeatAt: job.heartbeatAt,
          status: job.status,
        });
        return;
      }
      const scenes = Array.isArray(job.scenes) ? job.scenes : [];
      const resetScenes = scenes.map((s: any) => {
        if (s?.state === "failed" || s?.state === "pending") {
          return { ...s, nextAttemptAt: null, lastErrorCode: null, lastErrorAt: null };
        }
        return s;
      });
      const updated = await db
        .update(aiInfluencerJobsTable)
        .set({
          nextAttemptAt: null,
          heartbeatAt: null,
          finalizeAttempts: 0,
          retries: {},
          lastErrorCode: null,
          lastErrorMessage: null,
          lastErrorPayload: null,
          scenes: resetScenes,
        })
        // CAS on status so a concurrent worker transition does not get
        // clobbered by this admin write.
        .where(and(eq(aiInfluencerJobsTable.id, jobId), eq(aiInfluencerJobsTable.status, job.status)))
        .returning({
          id: aiInfluencerJobsTable.id,
          status: aiInfluencerJobsTable.status,
          progress: aiInfluencerJobsTable.progress,
          nextAttemptAt: aiInfluencerJobsTable.nextAttemptAt,
          heartbeatAt: aiInfluencerJobsTable.heartbeatAt,
          finalizeAttempts: aiInfluencerJobsTable.finalizeAttempts,
          retries: aiInfluencerJobsTable.retries,
        });
      if (updated.length === 0) {
        res.status(409).json({ error: "job_changed", message: "Job status changed concurrently; refetch and retry." });
        return;
      }
      req.log?.info?.(
        {
          jobId,
          adminId: req.appUser?.id,
          prevStatus: job.status,
          prevError: job.lastErrorCode,
          prevRetries: job.retries,
          prevFinalizeAttempts: job.finalizeAttempts,
          force,
        },
        "[admin-influencer-job] push-through applied",
      );
      res.json({ ok: true, job: updated[0] });
    } catch (err: any) {
      req.log?.error?.({ err: err?.message, jobId }, "[admin-influencer-job] push-through failed");
      res.status(500).json({ error: "internal_error", message: err?.message });
    }
  },
);

portalRouter.patch("/portal/admin/users/:userId/a-list", requireAuth, requireAdmin, async (req: any, res) => {
  const userId = parseInt(req.params.userId);
  if (isNaN(userId)) { res.status(400).json({ error: "Invalid user ID" }); return; }
  const { isAList } = req.body;
  if (typeof isAList !== "boolean") { res.status(400).json({ error: "isAList must be boolean" }); return; }
  const [currentUser] = await db.select().from(portalUsersTable).where(eq(portalUsersTable.id, userId));
  if (!currentUser) { res.status(404).json({ error: "User not found" }); return; }
  // Cross-portal isolation: a portal admin can only see/touch users who
  // belong to their own portal. Super admin still scoped to the
  // requested portal so the portal switcher remains authoritative.
  if (!(req.appUser?.isSuperAdmin && getPortalKey(req) === "room30") && (currentUser.portalKey || "main") !== getPortalKey(req)) {
    res.status(404).json({ error: "User not found" }); return;
  }

  const updates: any = { isAList, updatedAt: new Date() };
  if (isAList && !currentUser.aListJoinedAt) {
    updates.aListJoinedAt = new Date();
  }
  if (!isAList) {
    updates.aListJoinedAt = null;
  }

  const [updated] = await db
    .update(portalUsersTable)
    .set(updates)
    .where(eq(portalUsersTable.id, userId))
    .returning();
  res.json(updated);
});

// Admin user profile read. Returns everything the admin needs to manage
// a single user from one screen: identity, role + entitlements, billing
// rows by email, recent activity, invite history, email send history,
// and a Clerk profile snapshot for the sign-in metadata. Heavy joins are
// deliberately avoided in favour of small targeted reads so this stays
// fast even when the activity log is large.
portalRouter.get("/portal/admin/users/:userId/profile", requireAuth, requireCapability("users.view"), async (req: any, res) => {
  const userId = parseInt(req.params.userId);
  if (isNaN(userId)) { res.status(400).json({ error: "Invalid user ID" }); return; }
  const [user] = await db.select().from(portalUsersTable).where(eq(portalUsersTable.id, userId));
  if (!user) { res.status(404).json({ error: "User not found" }); return; }
  // Cross-portal isolation: a portal admin can only see/touch users who
  // belong to their own portal. Super admin still scoped to the
  // requested portal so the portal switcher remains authoritative.
  if (!(req.appUser?.isSuperAdmin && getPortalKey(req) === "room30") && (user.portalKey || "main") !== getPortalKey(req)) {
    res.status(404).json({ error: "User not found" }); return;
  }

  const email = (user.email || "").toLowerCase();
  const userPortalKey = user.portalKey || "main";

  // Lesson progress summary so the admin sees how far the student is.
  // Scope lesson totals to the user's portal so the percentage is
  // meaningful (a Room30 student on a 100%-complete Room30 curriculum
  // shouldn't read as 12% just because the Apex Offers course is much
  // larger). Progress rows are scoped via the lesson join.
  const [lessonsTotalRow] = await db
    .select({ count: count() })
    .from(lessonsTable)
    .where(eq(lessonsTable.portalKey, userPortalKey));
  const [lessonsDoneRow] = await db
    .select({ count: count() })
    .from(lessonProgressTable)
    .innerJoin(lessonsTable, eq(lessonsTable.id, lessonProgressTable.lessonId))
    .where(and(
      eq(lessonProgressTable.userId, userId),
      eq(lessonProgressTable.completed, true),
      eq(lessonsTable.portalKey, userPortalKey),
    ));
  const lessonsTotal = Number(lessonsTotalRow?.count || 0);
  const lessonsCompleted = Number(lessonsDoneRow?.count || 0);

  // Billing rows. We pull every order keyed off this email. Room30 has
  // no Whop billing flow (it is sold as a separate product), so for
  // Room30 users we don't surface Apex orders that might happen to share
  // the email - that would mix product context across the two
  // businesses. Apex Offers admins still see all order history.
  const orderRows = email && userPortalKey !== "room30"
    ? await db
        .select()
        .from(ordersTable)
        .where(eq(ordersTable.email, email))
        .orderBy(desc(ordersTable.createdAt))
    : [];
  const orders = orderRows.map((o: any) => ({
    id: o.id,
    email: o.email,
    isAdminGrant: typeof o.id === "string" && o.id.startsWith("admin-grant-"),
    currentStep: o.currentStep,
    mainProductPaid: !!o.mainProductPaid,
    bump1Paid: !!o.bump1Paid,
    bump2Paid: !!o.bump2Paid,
    bump3Paid: !!o.bump3Paid,
    upsell1Paid: !!o.upsell1Paid,
    upsell2Paid: !!o.upsell2Paid,
    upsell3Paid: !!o.upsell3Paid,
    downsell1Paid: !!o.downsell1Paid,
    totalAmount: o.totalAmount,
    whopUserId: o.whopUserId,
    whopReceiptId: o.whopReceiptId,
    whopMembershipId: o.whopMembershipId,
    stripeSessionId: o.stripeSessionId,
    stripePaymentIntentId: o.stripePaymentIntentId,
    createdAt: o.createdAt,
    updatedAt: o.updatedAt,
  }));

  // Aggregated entitlements. Reused from the existing helper so the
  // shape matches what the access toggles read elsewhere.
  const entitlements = await computePurchaseEntitlements(user);

  // Task #283: bonus AR influencer build usage so support can answer
  // "how many of my 5 bonus builds have I used?" without leaving this
  // screen. Counts only successful / in-flight free-tier jobs (matches
  // the same predicate the route uses to enforce the cap).
  const [influencerCountRow] = await db
    .select({ c: count() })
    .from(aiInfluencerJobsTable)
    .where(
      and(
        eq(aiInfluencerJobsTable.clientId, userId),
        eq(aiInfluencerJobsTable.isFreeTier, true),
        sql`${aiInfluencerJobsTable.status} <> 'failed'`,
      ),
    );
  const influencerJobsActive = Number(influencerCountRow?.c ?? 0);
  const bonusInfluencerQuota = entitlements.bonusInfluencerQuota ?? 0;
  const bonusInfluencerUsed = Math.max(0, Math.min(bonusInfluencerQuota, influencerJobsActive - 1));
  const influencerBuilds = {
    used: influencerJobsActive,
    total: 1 + bonusInfluencerQuota,
    bonusUnlocked: bonusInfluencerQuota > 0,
    bonusUsed: bonusInfluencerUsed,
    bonusRemaining: Math.max(0, bonusInfluencerQuota - bonusInfluencerUsed),
    unlockSeen: !!user.upsell2InfluencerUnlockSeen,
  };

  // Recent activity, last 50, lessons + tools opened.
  const recentLogs = await db
    .select()
    .from(accessLogsTable)
    .where(eq(accessLogsTable.userId, userId))
    .orderBy(desc(accessLogsTable.createdAt))
    .limit(50);

  // Invite history by email so admins can see if previous invites were
  // sent and whether they were claimed.
  // Invites + email logs are also keyed by email. For Room30 admins we
  // hide rows that originated from the Apex Offers flow (and vice versa)
  // so the two business surfaces don't bleed cross-portal correspondence
  // into each other's admin views.
  const inviteRows = email && userPortalKey !== "room30"
    ? await db
        .select()
        .from(invitesTable)
        .where(eq(invitesTable.email, email))
        .orderBy(desc(invitesTable.createdAt))
    : [];

  // Email logs, last 25, so admins can confirm invite/receipt delivery.
  const emailRows = email && userPortalKey !== "room30"
    ? await db
        .select()
        .from(emailLogsTable)
        .where(eq(emailLogsTable.email, email))
        .orderBy(desc(emailLogsTable.createdAt))
        .limit(25)
    : [];

  // Auth profile snapshot. With Replit Auth the portal_users row is the
  // source of truth (the historical clerk_id column holds the Replit
  // Auth user id), so this is assembled locally — no remote lookup.
  let clerkProfile: any = null;
  const resolvedClerkId: string | null = user.clerkId || null;
  if (resolvedClerkId) {
    clerkProfile = {
      id: resolvedClerkId,
      primaryEmailAddress: user.email || null,
      firstName: user.firstName || null,
      lastName: user.lastName || null,
      imageUrl: null,
      lastSignInAt: user.lastLoginAt || null,
      createdAt: user.createdAt || null,
      emailVerified: true,
      twoFactorEnabled: false,
    };
  }

  // If the local portal_users row never picked up the user's first/last
  // name (e.g. they were renamed via Clerk's own UI rather than the
  // in-app Settings page, or the row was seeded from a bare email-only
  // invite), backfill from Clerk so the admin UI stops showing
  // "(no name set)" for users who clearly have a name. Best-effort: a
  // failed update never breaks the admin response.
  let effectiveFirstName = user.firstName;
  let effectiveLastName = user.lastName;
  let effectiveClerkId = user.clerkId;
  const clerkFirst = clerkProfile?.firstName?.trim?.() || null;
  const clerkLast = clerkProfile?.lastName?.trim?.() || null;
  const missingFirst = !user.firstName && clerkFirst;
  const missingLast = !user.lastName && clerkLast;
  let missingClerkId = !user.clerkId && resolvedClerkId;
  // `clerk_id` is unique across portal_users, so we can't blindly copy
  // it onto this row if a different (e.g. legacy `main`-portal) row
  // already owns the linkage. Drop the clerk_id half of the patch in
  // that case and still backfill the names, which are not unique.
  if (missingClerkId) {
    try {
      const [conflict] = await db
        .select({ id: portalUsersTable.id })
        .from(portalUsersTable)
        .where(
          and(
            eq(portalUsersTable.clerkId, resolvedClerkId!),
            ne(portalUsersTable.id, user.id),
          ),
        )
        .limit(1);
      if (conflict?.id) {
        missingClerkId = false;
      }
    } catch (e: any) {
      req.log?.warn?.(
        { err: e?.message, userId: user.id },
        "admin.users.profile.clerk_id_conflict_check_failed",
      );
      missingClerkId = false;
    }
  }
  if (missingFirst || missingLast || missingClerkId) {
    const patch: { firstName?: string; lastName?: string; clerkId?: string; updatedAt: Date } = {
      updatedAt: new Date(),
    };
    if (missingFirst) patch.firstName = clerkFirst!;
    if (missingLast) patch.lastName = clerkLast!;
    if (missingClerkId) patch.clerkId = resolvedClerkId!;
    try {
      await db.update(portalUsersTable).set(patch).where(eq(portalUsersTable.id, user.id));
      if (missingFirst) effectiveFirstName = clerkFirst!;
      if (missingLast) effectiveLastName = clerkLast!;
      if (missingClerkId) effectiveClerkId = resolvedClerkId!;
    } catch (e: any) {
      req.log?.warn?.(
        { err: e?.message, userId: user.id },
        "admin.users.profile.clerk_backfill_failed",
      );
    }
  }

  res.json({
    user: {
      id: user.id,
      email: user.email,
      firstName: effectiveFirstName,
      lastName: effectiveLastName,
      role: user.role,
      isActive: user.isActive,
      isAList: user.isAList,
      clerkId: effectiveClerkId,
      orderId: user.orderId,
      whopUserId: user.whopUserId,
      avatarUrl: user.avatarUrl,
      currentDfyPhase: user.currentDfyPhase,
      createdAt: user.createdAt,
      updatedAt: user.updatedAt,
      lastLoginAt: user.lastLoginAt,
      invitedAt: user.invitedAt,
      aListJoinedAt: user.aListJoinedAt,
    },
    progress: {
      lessonsCompleted,
      lessonsTotal,
      progressPercent: lessonsTotal > 0
        ? Math.round((lessonsCompleted / lessonsTotal) * 100)
        : 0,
    },
    entitlements,
    orders,
    invites: inviteRows,
    emails: emailRows,
    activity: recentLogs,
    clerkProfile,
  });
});

// Edit a user's first name, last name and email on behalf of the user.
// Email change also propagates to Clerk: we add the new address as
// verified, set it as primary, then remove the old one. If the new
// email is already taken in Clerk we abort without touching anything
// to keep the two stores consistent. A renamed user keeps every order
// they ever paid for because we re-key every order row from the old
// email to the new email inside the same DB transaction.
portalRouter.patch("/portal/admin/users/:userId/profile", requireAuth, requireAdmin, async (req: any, res) => {
  const userId = parseInt(req.params.userId);
  if (isNaN(userId)) { res.status(400).json({ error: "Invalid user ID" }); return; }
  const [user] = await db.select().from(portalUsersTable).where(eq(portalUsersTable.id, userId));
  if (!user) { res.status(404).json({ error: "User not found" }); return; }
  // Cross-portal isolation: a portal admin can only see/touch users who
  // belong to their own portal. Super admin still scoped to the
  // requested portal so the portal switcher remains authoritative.
  if (!(req.appUser?.isSuperAdmin && getPortalKey(req) === "room30") && (user.portalKey || "main") !== getPortalKey(req)) {
    res.status(404).json({ error: "User not found" }); return;
  }

  // Only the env-pinned portal owner may edit another admin's identity.
  // Editing your own profile is always allowed regardless of role.
  if (
    user.role === "admin" &&
    req.portalUser?.id !== userId &&
    !req.appUser?.isSuperAdmin
  ) {
    res.status(403).json({ error: "Only the portal owner can edit another Admin." }); return;
  }

  const body = req.body || {};
  const updates: any = { updatedAt: new Date() };

  if (typeof body.firstName === "string") {
    const trimmed = body.firstName.trim();
    if (trimmed.length > 100) { res.status(400).json({ error: "First name too long" }); return; }
    updates.firstName = trimmed.length > 0 ? trimmed : null;
  }
  if (typeof body.lastName === "string") {
    const trimmed = body.lastName.trim();
    if (trimmed.length > 100) { res.status(400).json({ error: "Last name too long" }); return; }
    updates.lastName = trimmed.length > 0 ? trimmed : null;
  }

  let newEmail: string | null = null;
  if (typeof body.email === "string") {
    const candidate = body.email.trim().toLowerCase();
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(candidate)) {
      res.status(400).json({ error: "Invalid email" }); return;
    }
    if (candidate !== (user.email || "").toLowerCase()) {
      newEmail = candidate;
    }
  }

  // The sign-in email is owned by Replit Auth (the OIDC provider), not by
  // us. Allowing a local rename would desynchronize the row from the
  // verified identity used for claim-by-email, so we reject it outright.
  if (newEmail) {
    res.status(400).json({
      error:
        "Your sign-in email is managed by your Replit account and cannot be changed here.",
    }); return;
  }

  // Re-key orders + invites + email_logs + access_logs from old email
  // to new email so billing and audit history follows the rename, and
  // commit the portal_users update in the same transaction so the local
  // DB never half-applies a rename. Clerk has already accepted the new
  // address at this point; if the transaction below throws, the caller
  // sees a 500 and we surface a manual-recovery hint in the logs.
  try {
    const updated = await db.transaction(async (tx) => {
      if (newEmail) {
        const oldEmail = (user.email || "").toLowerCase();
        if (oldEmail) {
          await tx.update(ordersTable).set({ email: newEmail }).where(eq(ordersTable.email, oldEmail));
          await tx.update(invitesTable).set({ email: newEmail }).where(eq(invitesTable.email, oldEmail));
          await tx.update(emailLogsTable).set({ email: newEmail }).where(eq(emailLogsTable.email, oldEmail));
          await tx.update(accessLogsTable).set({ email: newEmail }).where(eq(accessLogsTable.email, oldEmail));
        }
      }
      const [row] = await tx
        .update(portalUsersTable)
        .set(updates)
        .where(eq(portalUsersTable.id, userId))
        .returning();
      return row;
    });
    res.json(updated); return;
  } catch (e: any) {
    req.log?.error?.(
      { err: e?.message, userId, newEmail },
      "Profile rename DB transaction failed after Clerk update; manual reconciliation may be required.",
    );
    res.status(500).json({
      error: "The new email was set in Clerk but the local rename failed. Please retry.",
    }); return;
  }
});

// Trigger a password reset for a user. We rotate their Clerk password
// to a strong randomly generated value and email it to them with a
// branded note. The user signs in with the temporary password and is
// told to change it via the standard "forgot password" flow on the
// sign-in screen if they want a permanent password of their choice.
// This avoids the brittleness of magic-link tickets while still being
// a single click for the admin.
portalRouter.post("/portal/admin/users/:userId/reset-password", requireAuth, requireCapability("users.reset_password"), async (_req: any, res) => {
  // Passwords are managed by Replit Auth now; there is nothing to rotate
  // on our side. Members sign in with their Replit account.
  res.status(410).json({
    error:
      "Passwords are managed by the member's Replit account. Ask them to sign in with Replit - there is no portal password to reset.",
  });
});


// Task #227: admin view of any user's Platinum Founder Code status.
// Returns the code (if issued), its status (unredeemed / redeemed /
// revoked), what it was redeemed for, and whether the user is currently
// a Platinum Club subscriber.
portalRouter.get(
  "/portal/admin/users/:userId/platinum-code",
  requireAuth,
  requireAdmin,
  async (req: any, res) => {
    const userId = parseInt(req.params.userId);
    if (isNaN(userId)) { res.status(400).json({ error: "Invalid user ID" }); return; }
    const [user] = await db.select().from(portalUsersTable).where(eq(portalUsersTable.id, userId));
    if (!user) { res.status(404).json({ error: "User not found" }); return; }
  // Cross-portal isolation: a portal admin can only see/touch users who
  // belong to their own portal. Super admin still scoped to the
  // requested portal so the portal switcher remains authoritative.
  if (!(req.appUser?.isSuperAdmin && getPortalKey(req) === "room30") && (user.portalKey || "main") !== getPortalKey(req)) {
    res.status(404).json({ error: "User not found" }); return;
  }
    const email = (user.email || "").toLowerCase();
    if (!email) { res.json({ status: "unissued", code: null, isPlatinumSubscriber: false }); return; }

    const [subscriberRow] = await db
      .select({ id: ordersTable.id })
      .from(ordersTable)
      .where(and(eq(ordersTable.email, email), eq(ordersTable.upsell3Paid, true)))
      .limit(1);
    const isPlatinumSubscriber = !!subscriberRow;

    const row = await getPlatinumCodeForEmail(email);
    if (!row) {
      res.json({
        status: "unissued",
        code: null,
        ownerEmail: email,
        isPlatinumSubscriber,
      }); return;
    }
    res.json({
      status: row.status,
      code: row.code,
      ownerEmail: row.ownerEmail,
      ownerOrderId: row.ownerOrderId,
      redeemedForProductSlug: row.redeemedForProductSlug,
      redeemedForOrderId: row.redeemedForOrderId,
      redeemedAt: row.redeemedAt,
      revokedAt: row.revokedAt,
      revokedReason: row.revokedReason,
      createdAt: row.createdAt,
      isPlatinumSubscriber,
    }); return;
  },
);

// Admin issuance: useful for support to manually issue a code (e.g.
// the buyer paid via a non-webhook path or the issuance side-effect
// was lost). Idempotent on email.
portalRouter.post(
  "/portal/admin/users/:userId/platinum-code/issue",
  requireAuth,
  requireAdmin,
  async (req: any, res) => {
    const userId = parseInt(req.params.userId);
    if (isNaN(userId)) { res.status(400).json({ error: "Invalid user ID" }); return; }
    const [user] = await db.select().from(portalUsersTable).where(eq(portalUsersTable.id, userId));
    if (!user || !user.email) { res.status(404).json({ error: "User not found" }); return; }
  // Cross-portal isolation: a portal admin can only see/touch users who
  // belong to their own portal. Super admin still scoped to the
  // requested portal so the portal switcher remains authoritative.
  if (!(req.appUser?.isSuperAdmin && getPortalKey(req) === "room30") && (user.portalKey || "main") !== getPortalKey(req)) {
    res.status(404).json({ error: "User not found" }); return;
  }
    const issued = await issuePlatinumFounderCode({ email: user.email });
    if (!issued) { res.status(500).json({ error: "issuance_failed" }); return; }
    res.json(issued); return;
  },
);

// Admin revoke: marks an unredeemed code as revoked. Already-redeemed
// codes cannot be revoked retroactively (per task #227 acceptance
// criterion - the buyer keeps the product they redeemed for).
portalRouter.post(
  "/portal/admin/users/:userId/platinum-code/revoke",
  requireAuth,
  requireAdmin,
  async (req: any, res) => {
    const userId = parseInt(req.params.userId);
    if (isNaN(userId)) { res.status(400).json({ error: "Invalid user ID" }); return; }
    const [user] = await db.select().from(portalUsersTable).where(eq(portalUsersTable.id, userId));
    if (!user || !user.email) { res.status(404).json({ error: "User not found" }); return; }
  // Cross-portal isolation: a portal admin can only see/touch users who
  // belong to their own portal. Super admin still scoped to the
  // requested portal so the portal switcher remains authoritative.
  if (!(req.appUser?.isSuperAdmin && getPortalKey(req) === "room30") && (user.portalKey || "main") !== getPortalKey(req)) {
    res.status(404).json({ error: "User not found" }); return;
  }
    const row = await getPlatinumCodeForEmail(user.email);
    if (!row) { res.status(404).json({ error: "no_code" }); return; }
    const reason = String(req.body?.reason || "admin_revoked");
    const result = await revokePlatinumCode(row.code, reason);
    if (result.alreadyRedeemed) {
      return res
        .status(409)
        .json({ error: "already_redeemed", message: "This code was already redeemed and cannot be revoked." });
    }
    res.json({ ...result, code: row.code }); return;
  },
);

// Hard delete a user. Removes Clerk account first (so the user can no
// longer sign in mid-cleanup) then portal_users + the rows that are
// not FK-cascaded. Marketing-tool tables FK-cascade automatically.
// Real Whop orders are kept for audit; only synthetic admin-grant
// rows are removed because they no longer have an owner.
portalRouter.delete("/portal/admin/users/:userId", requireAuth, requireAdmin, async (req: any, res) => {
  const userId = parseInt(req.params.userId);
  if (isNaN(userId)) { res.status(400).json({ error: "Invalid user ID" }); return; }
  const [user] = await db.select().from(portalUsersTable).where(eq(portalUsersTable.id, userId));
  if (!user) { res.status(404).json({ error: "User not found" }); return; }
  // Cross-portal isolation: a portal admin can only see/touch users who
  // belong to their own portal. Super admin still scoped to the
  // requested portal so the portal switcher remains authoritative.
  if (!(req.appUser?.isSuperAdmin && getPortalKey(req) === "room30") && (user.portalKey || "main") !== getPortalKey(req)) {
    res.status(404).json({ error: "User not found" }); return;
  }

  // Safety: cannot delete yourself.
  if (req.portalUser?.id === userId) {
    res.status(400).json({ error: "You cannot delete your own account." }); return;
  }
  // Safety: only the env-pinned super admin can remove another admin.
  if (user.role === "admin" && !req.appUser?.isSuperAdmin) {
    res.status(403).json({ error: "Only the portal owner can delete an Admin." }); return;
  }

  const email = (user.email || "").toLowerCase();

  // Revoke any live Replit Auth sessions for this user so a deleted
  // member is signed out immediately. Their Replit account itself is
  // untouched — we only remove the portal linkage and local data.
  if (user.clerkId) {
    try {
      await db.delete(sessionsTable).where(
        sql`${sessionsTable.sess}->'user'->>'id' = ${user.clerkId}`,
      );
    } catch (e: any) {
      req.log?.warn?.({ err: e?.message, userId }, "Failed to revoke sessions during user delete");
    }
  }

  // Local cleanup for tables that are not FK-cascaded, all in one
  // transaction so a partial failure cannot leave orphan rows after
  // the portal_users row is gone. Marketing-tool FK-cascades fire
  // automatically when portal_users is deleted, so per-user data in
  // the marketing tool is wiped at the database layer.
  try {
    await db.transaction(async (tx) => {
      await tx.delete(accessLogsTable).where(eq(accessLogsTable.userId, userId));
      await tx.delete(lessonProgressTable).where(eq(lessonProgressTable.userId, userId));
      if (email) {
        await tx.delete(invitesTable).where(eq(invitesTable.email, email));
        // Synthetic grant only. Real Whop orders are retained for audit.
        await tx.delete(ordersTable).where(eq(ordersTable.id, `admin-grant-${userId}`));
      }
      await tx.delete(portalUsersTable).where(eq(portalUsersTable.id, userId));
    });
  } catch (e: any) {
    req.log?.error?.(
      { err: e?.message, userId, clerkId: user.clerkId },
      "User delete DB transaction failed after Clerk delete; manual reconciliation may be required.",
    );
    res.status(500).json({
      error: "Clerk account was removed but the local cleanup failed. Please retry.",
    }); return;
  }

  res.json({ ok: true, deletedUserId: userId, deletedClerkId: user.clerkId || null });
});

// ----------------------------------------------------------------
// User self-service: profile, password, and silent AI-credit usage status.
// These endpoints back the redesigned Settings page and only ever touch the
// caller's own row (req.portalUser). They reuse the same Clerk + DB patterns
// as the admin equivalents above so naming, email, and Whop history all stay
// in sync after edits.
// ----------------------------------------------------------------

// Returns the AI usage tally for the current user. Below the included $10
// the frontend treats this as silent and shows nothing in the UI. Once
// `overLimit` flips true, the settings page surfaces a top-up CTA and the
// portal-wide banner appears until the user dismisses it.
portalRouter.get("/portal/me/credits-status", requireAuth, async (req: any, res) => {
  const user = req.portalUser;

  const researchPurchases = await db
    .select()
    .from(researchCreditPurchasesTable)
    .where(eq(researchCreditPurchasesTable.userId, user.id))
    .orderBy(desc(researchCreditPurchasesTable.createdAt))
    .limit(20);

  const osToolPurchases = await db
    .select()
    .from(osToolCreditPurchasesTable)
    .where(eq(osToolCreditPurchasesTable.userId, user.id))
    .orderBy(desc(osToolCreditPurchasesTable.createdAt))
    .limit(20);

  const history = [
    ...researchPurchases.map((p: any) => ({
      id: `research-${p.id}`,
      kind: "research" as const,
      label: "Research credit pack",
      amountCents: p.amountCents || 0,
      status: p.status,
      createdAt: p.createdAt,
      grantedAt: p.grantedAt,
      receiptUrl: p.receiptUrl,
    })),
    ...osToolPurchases.map((p: any) => ({
      id: `os-tool-${p.id}`,
      kind: "os_tool" as const,
      label: "OS Tool credit pack",
      amountCents: p.amountCents || 0,
      status: p.status,
      createdAt: p.createdAt,
      grantedAt: p.grantedAt,
      receiptUrl: p.receiptUrl,
    })),
  ].sort((a, b) => {
    const aT = a.grantedAt || a.createdAt;
    const bT = b.grantedAt || b.createdAt;
    return new Date(bT || 0).getTime() - new Date(aT || 0).getTime();
  });

  const aiUsageCents = user.aiUsageCents || 0;
  res.json({
    aiUsageCents,
    freeCents: AI_USAGE_FREE_CENTS,
    overLimit: aiUsageCents >= AI_USAGE_FREE_CENTS,
    notifiedAt: user.aiOverlimitNotifiedAt,
    dismissedAt: user.aiOverlimitDismissedAt,
    paidPacks: {
      research: user.researchPaidCredits || 0,
      osTool: user.osToolPaidCredits || 0,
      history,
    },
  });
});

