portalRouter.post("/portal/extract-proof-link", requireAuth, requireActive, async (req: any, res) => {
  try {
    const { url } = req.body || {};
    if (!url || typeof url !== "string") {
      res.status(400).json({ error: "URL is required" }); return;
    }
    let parsed: URL;
    try { parsed = new URL(url.trim()); } catch { res.status(400).json({ error: "Invalid URL" }); return; }
    if (!["http:", "https:"].includes(parsed.protocol)) {
      res.status(400).json({ error: "Only http(s) URLs are supported" }); return;
    }
    const host = parsed.hostname;
    if (
      host === "localhost" ||
      host.endsWith(".local") ||
      /^(127\.|10\.|192\.168\.|169\.254\.|0\.)/.test(host) ||
      /^172\.(1[6-9]|2[0-9]|3[0-1])\./.test(host)
    ) {
      res.status(400).json({ error: "Private/local URLs are not allowed" }); return;
    }

    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), 10000);
    let html = "";
    let finalUrl = parsed.toString();
    let pageTitle = "";
    try {
      const r = await fetch(parsed.toString(), {
        signal: controller.signal,
        redirect: "follow",
        headers: {
          "User-Agent": "Mozilla/5.0 (compatible; ProofExtractor/1.0; +https://apexoffers.io)",
          "Accept": "text/html,application/xhtml+xml",
        },
      });
      finalUrl = r.url || finalUrl;
      const ct = r.headers.get("content-type") || "";
      if (!ct.includes("text/html") && !ct.includes("application/xhtml")) {
        res.json({ extractedText: `Link points to non-HTML content (${ct || "unknown"}). URL: ${finalUrl}`, status: "non-html" }); return;
      }
      const reader = r.body?.getReader();
      if (!reader) { res.json({ extractedText: "", status: "empty" }); return; }
      const chunks: Uint8Array[] = [];
      let total = 0;
      const MAX = 1_500_000;
      while (true) {
        const { done, value } = await reader.read();
        if (done) break;
        if (value) {
          total += value.byteLength;
          chunks.push(value);
          if (total >= MAX) { try { await reader.cancel(); } catch {} break; }
        }
      }
      html = new TextDecoder("utf-8", { fatal: false }).decode(Buffer.concat(chunks.map(c => Buffer.from(c))));
    } catch (e: any) {
      clearTimeout(timeoutId);
      if (e?.name === "AbortError") { res.status(504).json({ error: "Request timed out" }); return; }
      res.status(502).json({ error: `Could not fetch URL: ${e?.message || "unknown error"}` }); return;
    }
    clearTimeout(timeoutId);

    const titleMatch = html.match(/<title[^>]*>([\s\S]*?)<\/title>/i);
    if (titleMatch) pageTitle = titleMatch[1].trim().slice(0, 200);

    const text = html
      .replace(/<script[\s\S]*?<\/script>/gi, " ")
      .replace(/<style[\s\S]*?<\/style>/gi, " ")
      .replace(/<noscript[\s\S]*?<\/noscript>/gi, " ")
      .replace(/<!--[\s\S]*?-->/g, " ")
      .replace(/<[^>]+>/g, " ")
      .replace(/&nbsp;/g, " ")
      .replace(/&amp;/g, "&")
      .replace(/&quot;/g, '"')
      .replace(/&#39;/g, "'")
      .replace(/&lt;/g, "<")
      .replace(/&gt;/g, ">")
      .replace(/\s+/g, " ")
      .trim()
      .slice(0, 12000);

    if (!text || text.length < 40) {
      res.json({ extractedText: `Page returned no extractable text (likely JS-rendered or behind a login). URL: ${finalUrl}`, status: "no-text", title: pageTitle }); return;
    }

    let extractedText = "";
    try {
      const openai = new OpenAI({
        baseURL: process.env.AI_INTEGRATIONS_OPENAI_BASE_URL,
        apiKey: process.env.AI_INTEGRATIONS_OPENAI_API_KEY,
      });
      const completion = await openai.chat.completions.create({
        model: "gpt-4o-mini",
        messages: [
          {
            role: "system",
            content: "You extract social proof from a webpage's text. Pull out: overall ratings (e.g. 4.8/5), total review/customer counts, the strongest 2-3 verbatim testimonial quotes (with attribution if visible), revenue/result numbers, awards, press mentions, and any provable metrics. Be concise and factual. Output as a short structured summary. If the page contains no usable proof, say so plainly. Never invent data not present in the source.",
          },
          {
            role: "user",
            content: `URL: ${finalUrl}\nPage title: ${pageTitle}\n\nPage text:\n${text}`,
          },
        ],
        max_tokens: 600,
      });
      extractedText = completion.choices[0]?.message?.content?.trim() || "";
    } catch (e: any) {
      console.error("Link extraction LLM failed:", e?.message);
      res.json({ extractedText: `Fetched page but AI extraction failed. Raw title: ${pageTitle}`, status: "llm-failed", title: pageTitle }); return;
    }

    res.json({ extractedText, title: pageTitle, finalUrl, status: "ok" });
    return;
  } catch (error: any) {
    console.error("Proof link extraction error:", error?.message || error);
    res.status(500).json({ error: "Failed to extract link" });
    return;
  }
});

portalRouter.post("/portal/admin/generate-diagram", requireAuth, requireAdmin, async (req: any, res) => {
  const { description, diagramType } = req.body;
  if (!description || typeof description !== "string") {
    res.status(400).json({ error: "Description is required" }); return;
  }
  if (description.length > 5000) {
    res.status(400).json({ error: "Description too long (max 5K characters)" }); return;
  }

  try {
    const openai = new OpenAI({
      baseURL: process.env.AI_INTEGRATIONS_OPENAI_BASE_URL,
      apiKey: process.env.AI_INTEGRATIONS_OPENAI_API_KEY,
    });

    const type = diagramType || "flowchart";

    const completion = await openai.chat.completions.create({
      model: "gpt-4o",
      messages: [
        {
          role: "system",
          content: `You generate clean, simple, professional SVG diagrams for a business course. Output ONLY valid SVG code, nothing else.

DESIGN RULES:
- White or very light (#f8f8f8) background
- Primary accent: #E32652 (red) for key elements, borders, arrows
- Secondary: #1a1a1a for text, #333 for secondary text
- Font: Arial or sans-serif (system fonts only, no custom fonts)
- Clean rounded rectangles (rx="8") with subtle borders
- Simple arrow lines (stroke-width 2, with arrowhead markers)
- Generous spacing between elements — never cramped
- Text must be large enough to read easily (14-18px for labels, 12-14px for descriptions)
- Maximum 800px wide, height proportional to content
- Keep it SIMPLE — no gradients, no shadows, no complex shapes
- Each box should have a short label (max ~6 words)
- Use numbered circles or step indicators where appropriate

DIAGRAM TYPES:
- flowchart: Boxes connected by arrows, top-to-bottom or left-to-right flow
- process: Numbered steps in sequence, horizontal or vertical
- funnel: Wide at top, narrow at bottom with labeled stages
- comparison: Side-by-side columns with items
- hierarchy: Tree structure, parent to children
- cycle: Circular flow with connected stages
- infographic: Key stats/facts in a clean visual layout

SVG REQUIREMENTS:
- Must start with <svg xmlns="http://www.w3.org/2000/svg"
- Include viewBox for proper scaling
- Use <defs> for arrowhead markers if arrows are needed
- All text must use <text> elements (never foreignObject)
- Keep SVG code compact but readable
- Wrap text manually into multiple <tspan> lines if a label is long

OUTPUT: Return ONLY the raw SVG code. No markdown code fences, no explanation, no backticks. Start with <svg and end with </svg>.`
        },
        {
          role: "user",
          content: `Create a ${type} diagram showing:\n${description}`
        }
      ],
      max_completion_tokens: 4096,
    });

    let svgContent = completion.choices[0]?.message?.content || "";
    if (!svgContent) {
      res.status(500).json({ error: "AI did not generate content" }); return;
    }

    svgContent = svgContent.trim();
    if (svgContent.startsWith("```")) {
      svgContent = svgContent.replace(/^```(?:svg|xml)?\n?/, "").replace(/\n?```$/, "").trim();
    }

    if (!svgContent.startsWith("<svg")) {
      const svgStart = svgContent.indexOf("<svg");
      if (svgStart >= 0) {
        svgContent = svgContent.substring(svgStart);
      } else {
        res.status(500).json({ error: "Failed to generate valid SVG diagram" }); return;
      }
    }

    res.json({ svg: svgContent });
    return;
  } catch (error: any) {
    console.error("Diagram generation error:", error?.message || error);
    res.status(500).json({ error: "Failed to generate diagram. Please try again." });
    return;
  }
});

portalRouter.get("/portal/images/:fileName", async (req: any, res) => {
  try {
    const bucketId = process.env.DEFAULT_OBJECT_STORAGE_BUCKET_ID;
    const privateDir = process.env.PRIVATE_OBJECT_DIR;
    if (!bucketId || !privateDir) {
      res.status(500).json({ error: "Object storage not configured" }); return;
    }

    const { fileName } = req.params;
    if (!fileName || fileName.includes("..") || fileName.includes("/")) {
      res.status(400).json({ error: "Invalid file name" }); return;
    }

    // Optional ?w=NUMBER triggers an on-the-fly resize to a webp thumbnail.
    // Without it we serve the original bytes untouched. Width is clamped so
    // callers cannot ask the server to re-encode a near-original 4000px image
    // (which would defeat the point of the cheap thumbnail path).
    const widthRaw = req.query.w;
    let targetWidth: number | null = null;
    if (typeof widthRaw === "string" && /^\d+$/.test(widthRaw)) {
      const parsed = parseInt(widthRaw, 10);
      if (parsed >= 32 && parsed <= 1600) targetWidth = parsed;
    }

    const bucket = objectStorageClient.bucket(bucketId);
    const file = bucket.file(`${privateDir}/${fileName}`);

    const [exists] = await file.exists();
    if (!exists) {
      res.status(404).json({ error: "Image not found" }); return;
    }

    const [metadata] = await file.getMetadata();
    const baseEtag = String(metadata.etag || metadata.md5Hash || metadata.generation || "");
    // Thumbnail bytes differ per width, so the ETag must too — otherwise the
    // browser would happily reuse a 400px webp where a full PNG was asked for.
    const variantEtag = targetWidth ? `"${baseEtag.replace(/^"|"$/g, "")}-w${targetWidth}"` : baseEtag;

    // Image URLs are content-addressed (random UUID per upload) so the bytes
    // never change once stored. Override the portal-wide no-store middleware
    // and tell the browser it can cache for a year, immutable.
    res.removeHeader("Pragma");
    res.removeHeader("Expires");
    res.set("Cache-Control", "public, max-age=31536000, immutable");
    res.set("X-Content-Type-Options", "nosniff");
    // ?download=1 forces a save dialog instead of inline display. fileName is
    // already validated above (no "/" or ".."), so it is safe to echo into the
    // attachment filename.
    const asAttachment = req.query.download === "1";
    res.set(
      "Content-Disposition",
      asAttachment ? `attachment; filename="${fileName}"` : "inline",
    );
    if (variantEtag) res.set("ETag", variantEtag);

    // Honour conditional GET — browsers send If-None-Match on revalidation
    // and we can short-circuit with a 304, saving a multi-megabyte transfer.
    const ifNoneMatch = req.headers["if-none-match"];
    if (variantEtag && ifNoneMatch && ifNoneMatch === variantEtag) {
      res.status(304).end(); return;
    }

    if (targetWidth) {
      // Resize path: download once, transcode to webp at the requested width,
      // ship the small buffer. We import sharp lazily so any platform without
      // the native binary still serves originals fine.
      try {
        const sharp = (await import("sharp")).default;
        const [buffer] = await file.download();
        const out = await sharp(buffer)
          .rotate()
          .resize({ width: targetWidth, withoutEnlargement: true })
          .webp({ quality: 78 })
          .toBuffer();
        res.set("Content-Type", "image/webp");
        res.end(out); return;
      } catch (err: any) {
        req.log?.warn({ err: err?.message, fileName, targetWidth }, "thumbnail resize failed, falling back to original");
        // fall through to streaming the original
      }
    }

    // Originals path: use a one-shot buffered download instead of
    // file.createReadStream().pipe(res). The streaming variant has been
    // observed taking 60-90 seconds for a 4 MB file in this environment,
    // whereas .download() returns the full buffer in well under a second.
    // 4 MB images are small enough to comfortably hold in memory.
    res.set("Content-Type", metadata.contentType || "image/png");
    const [origBuffer] = await file.download();
    res.set("Content-Length", String(origBuffer.length));
    res.end(origBuffer); return;
  } catch (error: any) {
    console.error("Image serve error:", error?.message || error);
    res.status(500).json({ error: "Failed to serve image" });
    return;
  }
});

portalRouter.post("/portal/internal/bootstrap-admin", async (req, res) => {
  const authHeader = req.headers["x-internal-secret"];
  if (authHeader !== INTERNAL_WEBHOOK_SECRET) {
    res.status(403).json({ error: "Forbidden" }); return;
  }
  const { clerkId } = req.body;
  if (!clerkId) { res.status(400).json({ error: "clerkId required" }); return; }
  const adminEmail = process.env.ADMIN_EMAIL || "greg@cookemedia.io";
  const [updated] = await db.update(portalUsersTable).set({
    email: adminEmail,
    role: "admin",
    isActive: true,
    updatedAt: new Date(),
  }).where(eq(portalUsersTable.clerkId, clerkId)).returning();
  if (!updated) { res.status(404).json({ error: "User not found" }); return; }
  res.json({ ok: true, user: updated });
});

portalRouter.post("/portal/internal/seed-course", async (req, res) => {
  const authHeader = req.headers["x-internal-secret"];
  if (authHeader !== INTERNAL_WEBHOOK_SECRET) {
    res.status(403).json({ error: "Forbidden" }); return;
  }
  const { phases, lessons, clearAll } = req.body;
  if (!phases?.length) { res.status(400).json({ error: "phases required" }); return; }

  if (clearAll) {
    await db.delete(lessonsTable);
    await db.delete(coursePhasesTable);
  }

  for (const p of phases) {
    await db.insert(coursePhasesTable).values({
      slug: p.slug,
      title: p.title,
      description: p.description,
      sortOrder: p.sortOrder ?? p.sort_order,
    }).onConflictDoNothing();
  }

  const allPhases = await db.select().from(coursePhasesTable);
  const slugToId: Record<string, number> = {};
  for (const p of allPhases) slugToId[p.slug] = p.id;

  if (lessons?.length) {
    for (const l of lessons) {
      const phaseId = slugToId[l.phaseSlug] || null;
      if (!phaseId) continue;
      await db.insert(lessonsTable).values({
        phaseId,
        slug: l.slug,
        title: l.title,
        brief: l.brief || null,
        wistiaVideoId: l.wistiaVideoId || null,
        promptTemplate: l.promptTemplate || null,
        downloadFiles: l.downloadFiles || null,
        actionTask: l.actionTask || null,
        sortOrder: l.sortOrder,
        durationMinutes: l.durationMinutes || null,
        isPublished: l.isPublished ?? true,
      }).onConflictDoNothing();
    }
  }

  const totalPhases = await db.select({ count: count() }).from(coursePhasesTable);
  const totalLessons = await db.select({ count: count() }).from(lessonsTable);
  res.json({ ok: true, phases: totalPhases[0].count, lessons: totalLessons[0].count });
});

