portalRouter.post("/portal/internal/fix-dashes", async (req, res) => {
  const authHeader = req.headers["x-internal-secret"];
  if (authHeader !== INTERNAL_WEBHOOK_SECRET) {
    res.status(403).json({ error: "Forbidden" }); return;
  }
  const allLessons = await db.select({ id: lessonsTable.id, slug: lessonsTable.slug, notes: lessonsTable.notes, brief: lessonsTable.brief }).from(lessonsTable);
  let fixed = 0;
  for (const l of allLessons) {
    let changed = false;
    let newNotes = l.notes || "";
    let newBrief = l.brief || "";
    if (/\u2014|\u2013/.test(newNotes)) {
      newNotes = newNotes.replace(/\u2014/g, " - ").replace(/\u2013/g, " - ");
      changed = true;
    }
    if (/\u2014|\u2013/.test(newBrief)) {
      newBrief = newBrief.replace(/\u2014/g, " - ").replace(/\u2013/g, " - ");
      changed = true;
    }
    if (/\*\*[^*]+\*\*/.test(newNotes)) {
      newNotes = newNotes.replace(/\*\*([^*]+)\*\*/g, "<strong>$1</strong>");
      changed = true;
    }
    if (/\*\*[^*]+\*\*/.test(newBrief)) {
      newBrief = newBrief.replace(/\*\*([^*]+)\*\*/g, "<strong>$1</strong>");
      changed = true;
    }
    if (changed) {
      await db.update(lessonsTable).set({ notes: newNotes, brief: newBrief }).where(eq(lessonsTable.id, l.id));
      fixed++;
    }
  }
  res.json({ ok: true, fixed, total: allLessons.length });
});

