// Upload an arbitrary research / source document straight into the user's
// brain (category=user-uploads). Supports text-style files (txt, md, html,
// csv, json) read straight off the buffer, and .docx via mammoth. Anything
// else is rejected with a clear hint to paste the contents as text instead
// (the same endpoint accepts a `pastedText` field for that fallback).
portalRouter.post(
  "/portal/assets/upload",
  requireAuth,
  requireActive,
  upload.single("file"),
  async (req: any, res) => {
    try {
      const user = req.portalUser;
      const titleInput: string = (req.body?.title || req.file?.originalname || "Untitled").toString().trim();
      const title = titleInput.replace(/\.[a-z0-9]{1,8}$/i, "").slice(0, 200) || "Untitled";
      const pastedText: string = (req.body?.pastedText || "").toString();

      let content = "";
      if (req.file) {
        const buf: Buffer = req.file.buffer;
        const mime = (req.file.mimetype || "").toLowerCase();
        const name = (req.file.originalname || "").toLowerCase();
        const isDocx =
          mime === "application/vnd.openxmlformats-officedocument.wordprocessingml.document" ||
          name.endsWith(".docx");
        const isText =
          mime.startsWith("text/") ||
          mime === "application/json" ||
          mime === "application/xml" ||
          /\.(txt|md|markdown|html?|csv|tsv|json|xml|log)$/i.test(name);

        if (isDocx) {
          try {
            const mammoth = await import("mammoth");
            const result = await mammoth.extractRawText({ buffer: buf });
            content = (result.value || "").trim();
          } catch (err: any) {
            req.log?.error({ err }, "user upload mammoth extract failed");
            res.status(400).json({ error: "Could not read that .docx file. Try saving it as .txt or paste the contents as text." }); return;
          }
        } else if (isText) {
          content = buf.toString("utf-8").trim();
        } else {
          res.status(415).json({
            error: "Unsupported file type. Upload .txt, .md, .html, .csv, .json or .docx - or paste the contents as text.",
          }); return;
        }
      } else if (pastedText.trim()) {
        content = pastedText.trim();
      } else {
        res.status(400).json({ error: "Provide either a file or pastedText." }); return;
      }

      if (!content) {
        res.status(400).json({ error: "The uploaded document is empty." }); return;
      }
      // Soft cap to keep brain context windows manageable. Most user
      // research docs are well under this.
      const MAX_CHARS = 200_000;
      if (content.length > MAX_CHARS) content = content.slice(0, MAX_CHARS);

      const [asset] = await db.insert(userAssetsTable).values({
        userId: user.id,
        category: "user-uploads",
        title,
        content,
        assetType: "upload",
        metadata: req.file
          ? { originalName: req.file.originalname, mimeType: req.file.mimetype, sizeBytes: req.file.size }
          : { source: "pasted-text" },
      }).returning();

      res.json({ asset });
      return;
    } catch (err: any) {
      req.log?.error({ err }, "user asset upload failed");
      res.status(500).json({ error: err?.message || "Upload failed" });
      return;
    }
  },
);

