portalRouter.post("/portal/assets/:id/refine", requireAuth, requireActive, async (req: any, res) => {
  const user = req.portalUser;
  const assetId = parseInt(req.params.id);
  const { refinePrompt } = req.body || {};
  if (!refinePrompt || typeof refinePrompt !== "string" || !refinePrompt.trim()) {
    res.status(400).json({ error: "refinePrompt is required" }); return;
  }
  const [existing] = await db.select().from(userAssetsTable).where(and(eq(userAssetsTable.id, assetId), eq(userAssetsTable.userId, user.id)));
  if (!existing) { res.status(404).json({ error: "Asset not found" }); return; }

  const openai = new OpenAI({
    baseURL: process.env.AI_INTEGRATIONS_OPENAI_BASE_URL,
    apiKey: process.env.AI_INTEGRATIONS_OPENAI_API_KEY,
  });

  try {
    const completion = await openai.chat.completions.create({
      model: "gpt-4o",
      messages: [
        {
          role: "system",
          content:
            "You are an expert business strategist and copywriter refining a saved document for the user's business. Apply the user's refinement request to the existing document while preserving its structure, tone, and any sections the request does not mention. Return the COMPLETE revised document in HTML format only — no preamble, no commentary, no markdown code fences.",
        },
        {
          role: "user",
          content: `Document title: ${existing.title}\n\nCurrent document:\n\n${existing.content || ""}\n\n---\nUser's refinement request: ${refinePrompt}\n\nReturn the complete revised document in HTML.`,
        },
      ],
      max_tokens: 4000,
    });
    const content = stripCodeFences(completion.choices[0]?.message?.content || "");
    res.json({ content });
    return;
  } catch (err: any) {
    console.error("Asset refine failed:", err);
    res.status(500).json({ error: err?.message || "Refine failed" });
    return;
  }
});

