portalRouter.post("/portal/expertise/generate", requireAuth, requireActive, async (req: any, res) => {
  const user = req.portalUser;
  const [profile] = await db.select().from(userExpertiseProfilesTable).where(eq(userExpertiseProfilesTable.userId, user.id));
  if (!profile) {
    res.status(400).json({ error: "Please save your answers first." }); return;
  }
  const a = (profile.answers || {}) as Record<string, string>;
  const requiredKeys = ["lifestyleVision", "currentIncome", "professionalAuthority", "superpowers", "otherSkills", "livedExperience", "whoAround"];
  const missing = requiredKeys.filter((k) => !a[k] || !String(a[k]).trim());
  if (missing.length > 0) {
    res.status(400).json({ error: "Please complete every step before generating.", missing }); return;
  }

  // Credit gating: first generation is free for everyone, regenerations
  // share the same regeneration credit pool used by Research Docs.
  // Admins always get free regenerations.
  const isRegeneration = !!profile.generatedAt;
  const ent = computeResearchEntitlement(user);
  let creditType: "free" | "paid" = "free";
  if (isRegeneration && !ent.isAdmin) {
    if (ent.freeRunsRemaining > 0) {
      creditType = "free";
    } else if (ent.paidCredits > 0) {
      creditType = "paid";
    } else {
      res.status(402).json({
        error: "You've used your free generations. Purchase a regeneration credit ($5) on the Research Docs page to regenerate your Expertise Profile.",
        code: "needs_credit",
      }); return;
    }
  }

  await db.update(userExpertiseProfilesTable)
    .set({ status: "generating", updatedAt: new Date() })
    .where(eq(userExpertiseProfilesTable.userId, user.id));

  void (async () => {
    try {
      const openai = new OpenAI({
        baseURL: process.env.AI_INTEGRATIONS_OPENAI_BASE_URL,
        apiKey: process.env.AI_INTEGRATIONS_OPENAI_API_KEY,
      });

      // Reuse the shared OS tool prompt registry so this tool follows the
      // same prompt/flow pattern as every other generator in the OS.
      const toolConfig = OS_TOOL_PROMPTS["find-your-expertise"];
      if (!toolConfig) throw new Error("find-your-expertise prompt missing from OS_TOOL_PROMPTS");

      const [brainProfileRow] = await db.select().from(userBrainProfilesTable).where(eq(userBrainProfilesTable.userId, user.id));
      const brainProfile = resolveEffectiveBrain(brainProfileRow, getPortalKey(req));
      const brainData = brainProfile ? {
        name: brainProfile.name,
        companyName: brainProfile.companyName,
        whoDoYouHelp: brainProfile.whoDoYouHelp,
        howDoYouHelpThem: brainProfile.howDoYouHelpThem,
        keyAchievements: brainProfile.keyAchievements,
      } : {};

      const knowledgeContext = await getOSToolKnowledgeContext("find-your-expertise", a);
      const enrichedSystem = toolConfig.system + knowledgeContext;

      const completion = await openai.chat.completions.create({
        model: "gpt-4o",
        messages: [
          { role: "system", content: enrichedSystem },
          { role: "user", content: toolConfig.userTemplate(a, brainData) },
        ],
        temperature: 0.55,
        max_tokens: toolConfig.maxTokens || 2400,
      });

      const html = completion.choices?.[0]?.message?.content || "";

      const pull = (key: string) => {
        const re = new RegExp(`<span\\s+data-key="${key}"[^>]*>([\\s\\S]*?)<\\/span>`, "i");
        const m = html.match(re);
        return m ? m[1].replace(/<[^>]+>/g, " ").replace(/\s+/g, " ").trim() : null;
      };

      const coreExpertise = pull("coreExpertise");
      const uniqueAngle = pull("uniqueAngle");
      const subNiche = pull("subNiche");
      const whyQualified = pull("whyQualified");
      const suggestedOfferDirection = pull("suggestedOfferDirection");
      const recommendedNextSteps = pull("recommendedNextSteps");

      await db.update(userExpertiseProfilesTable).set({
        generatedProfile: html,
        coreExpertise,
        uniqueAngle,
        subNiche,
        whyQualified,
        suggestedOfferDirection,
        recommendedNextSteps,
        status: "generated",
        generatedAt: new Date(),
        updatedAt: new Date(),
      }).where(eq(userExpertiseProfilesTable.userId, user.id));

      // Consume from the same regeneration ledger Research Docs uses on
      // successful completion. Free-run regenerations bump the completed
      // counter (eating into the shared free pool); paid regenerations
      // additionally decrement a paid credit. First-time generations do
      // not consume anything.
      if (isRegeneration && !ent.isAdmin) {
        if (creditType === "paid") {
          await db.update(portalUsersTable).set({
            researchGenerationsCompleted: sql`${portalUsersTable.researchGenerationsCompleted} + 1`,
            researchPaidCredits: sql`GREATEST(${portalUsersTable.researchPaidCredits} - 1, 0)`,
          }).where(eq(portalUsersTable.id, user.id));
        } else {
          await db.update(portalUsersTable).set({
            researchGenerationsCompleted: sql`${portalUsersTable.researchGenerationsCompleted} + 1`,
          }).where(eq(portalUsersTable.id, user.id));
        }
      }

      // Silent $10 AI usage tracker. The Expertise generation runs roughly
      // the same model spend as a research job ($1.00).
      void recordAiUsage({ userId: user.id, cents: 100, source: "expertise_generation" });

      // Seed Brain profile fields if empty so About You / Brain OS picks this up
      const [brain] = await db.select().from(userBrainProfilesTable).where(eq(userBrainProfilesTable.userId, user.id));
      const seedFields: Record<string, any> = { updatedAt: new Date() };
      let mutated = false;
      if (subNiche && (!brain?.whoDoYouHelp || !brain.whoDoYouHelp.trim())) {
        seedFields.whoDoYouHelp = subNiche;
        mutated = true;
      }
      if (suggestedOfferDirection && (!brain?.howDoYouHelpThem || !brain.howDoYouHelpThem.trim())) {
        seedFields.howDoYouHelpThem = suggestedOfferDirection;
        mutated = true;
      }
      if (whyQualified && (!brain?.keyAchievements || !brain.keyAchievements.trim())) {
        seedFields.keyAchievements = whyQualified;
        mutated = true;
      }
      if (mutated) {
        if (brain) {
          await db.update(userBrainProfilesTable).set(seedFields).where(eq(userBrainProfilesTable.userId, user.id));
        } else {
          await db.insert(userBrainProfilesTable).values({ userId: user.id, ...seedFields });
        }
      }

      // Save as an asset under a dedicated category so it can be picked up by
      // downstream tools without polluting the Research Docs context.
      // First clear any prior expertise asset so we keep a single source of truth.
      await db.delete(userAssetsTable).where(
        and(
          eq(userAssetsTable.userId, user.id),
          eq(userAssetsTable.category, "expertise-profile"),
        ),
      );
      await db.insert(userAssetsTable).values({
        userId: user.id,
        category: "expertise-profile",
        title: "Your Expertise Profile",
        content: html,
        assetType: "doc",
        lessonSlug: "find-your-expertise",
      });
    } catch (err: any) {
      console.error("Expertise generation error:", err);
      await db.update(userExpertiseProfilesTable)
        .set({ status: "error", updatedAt: new Date() })
        .where(eq(userExpertiseProfilesTable.userId, user.id));
    }
  })();
  res.json({ started: true, status: "generating" });
  return;
});

// One-shot idempotent migration: insert the new "find-your-expertise" lesson
// before "about-you" in phase-1, bumping subsequent sortOrders by +1.
portalRouter.post("/portal/internal/seed-find-your-expertise", async (req, res) => {
  const authHeader = req.headers["x-internal-secret"];
  if (authHeader !== INTERNAL_WEBHOOK_SECRET) {
    res.status(403).json({ error: "Forbidden" }); return;
  }

  const [phase] = await db.select().from(coursePhasesTable).where(eq(coursePhasesTable.slug, "phase-1-research-offer"));
  if (!phase) { res.status(400).json({ error: "phase-1-research-offer not found" }); return; }

  const [existing] = await db.select().from(lessonsTable).where(eq(lessonsTable.slug, "find-your-expertise"));
  if (existing) {
    res.json({ ok: true, alreadyExists: true, lessonId: existing.id }); return;
  }

  // Bump existing lessons in this phase that are sortOrder >= 1 by +1 to make room at sortOrder=1
  await db.execute(sql`update ${lessonsTable} set sort_order = sort_order + 1 where phase_id = ${phase.id} and sort_order >= 1`);

  const [created] = await db.insert(lessonsTable).values({
    phaseId: phase.id,
    slug: "find-your-expertise",
    title: "Find Your Expertise",
    brief: "<p>Most people freeze at the start because they don't know <strong>what</strong> to be the expert in. This lesson is the cure. We walk you through seven simple prompts - lifestyle vision, finances, what you're already respected for, your superpowers, your other skills, the journey you've lived, and the people already in your orbit - and the system surfaces the one positioning that gives you the highest leverage right now.</p><p>You leave with a clear core expertise, a sub-niche worth owning, the angle nobody else has, and a recommended first offer direction. Your Brain profile and Research Docs then build from this.</p>",
    actionTask: "Complete every step in the Find Your Expertise tool, generate your Expertise Profile, and approve the surfaced sub-niche before moving on to Your Brain.",
    sortOrder: 1,
    durationMinutes: 12,
    isPublished: true,
  }).returning();

  res.json({ ok: true, created: true, lessonId: created.id });
});

portalRouter.get("/portal/brain", requireAuth, requireActive, async (req: any, res) => {
  const user = req.portalUser;
  const [rawProfile] = await db.select().from(userBrainProfilesTable).where(eq(userBrainProfilesTable.userId, user.id));
  if (!rawProfile) { res.json({ profile: null }); return; }
  // When the user has switched to a pre-built brain (brainMode='prebuilt'),
  // their own row still carries stale name/companyName values, so the
  // "Brain Connected" badge surfaced the wrong brain name. resolveEffectiveBrain
  // overlays the selected curated brain's positioning before we return the row.
  const profile = resolveEffectiveBrain(rawProfile);
  // Task #725: surface the last generation error (if any) so the UI can
  // show the real reason instead of a generic "Failed to generate brain".
  // The error is stashed in scrapedData.__error when the background
  // generation step fails.
  const scrapedAny = (profile.scrapedData ?? null) as { __error?: string; __errorCode?: string } | null;
  const errorMessage = profile.status === "error" ? (scrapedAny?.__error ?? null) : null;
  const errorCode = profile.status === "error" ? (scrapedAny?.__errorCode ?? null) : null;
  res.json({ profile: { ...profile, errorMessage, errorCode } });
});

// Catalog of curated "promote one of our offers" brains. Display-only fields.
// Intentionally unauthenticated: it's a static catalog with no per-user data,
// and the React Query fires on mount (before Clerk's token getter is ready),
// so requiring auth here causes a one-shot 401 that React Query does not retry,
// leaving the picker stuck on "Loading available brains...".
portalRouter.get("/portal/brain/prebuilt", async (_req: any, res) => {
  res.json({ brains: listPrebuiltBrainsForClient() });
});

// Full payload for a single prebuilt brain - includes the curated positioning
// fields (brainData) and the generated brain markdown so the "Choose Your
// Brain" picker on /your-brain can preview the entire brain inline (read-only)
// when a user selects one. Kept separate from the catalog list endpoint so the
// list response stays small. Auth-optional for the same race-on-mount reason
// as the list endpoint above.
portalRouter.get("/portal/brain/prebuilt/:id", async (req: any, res) => {
  const id = String(req.params.id || "");
  const brain = getPrebuiltBrain(id);
  if (!brain || brain.isActive === false) {
    res.status(404).json({ error: "prebuilt_brain_not_found" });
    return;
  }
  res.json({
    brain: {
      id: brain.id,
      name: brain.name,
      tagline: brain.tagline,
      shortDescription: brain.shortDescription,
      audience: brain.audience,
      highlights: brain.highlights,
      badge: brain.badge ?? null,
      brainData: brain.brainData,
      generatedBrain: brain.generatedBrain,
    },
  });
});

portalRouter.put("/portal/brain", requireAuth, requireActive, async (req: any, res) => {
  const user = req.portalUser;
  const { name, companyName, whoDoYouHelp, howDoYouHelpThem, keyAchievements, website, landingPages, socialProfiles, brandColorPrimary, brandColorSecondary, brandColorSource, brandGuidelinesUrl, confirmedLowTicketOffer, confirmedPremiumOffer, confirmed100kOffer, brainMode, selectedPrebuiltBrainId } = req.body;

  const [existing] = await db.select().from(userBrainProfilesTable).where(eq(userBrainProfilesTable.userId, user.id));

  // Validate brain mode + the prebuilt selection if present. The catalog
  // (e.g. AI Influencer Portfolio) is shared across portals so Room30
  // members can promote it.
  let normalizedMode = brainMode === "prebuilt" ? "prebuilt" : "own";
  let normalizedPrebuiltId: string | null = null;
  if (normalizedMode === "prebuilt") {
    const pre = getPrebuiltBrain(selectedPrebuiltBrainId);
    if (!pre) {
      res.status(400).json({ error: "Unknown prebuilt brain id" }); return;
    }
    normalizedPrebuiltId = pre.id;
  }

  const profileData: any = {
    name: name || null,
    companyName: companyName || null,
    whoDoYouHelp: whoDoYouHelp || null,
    howDoYouHelpThem: howDoYouHelpThem || null,
    keyAchievements: keyAchievements || null,
    website: website || null,
    landingPages: landingPages || [],
    socialProfiles: socialProfiles || [],
    brandColorPrimary: brandColorPrimary || null,
    brandColorSecondary: brandColorSecondary || null,
    brandColorSource: brandColorSource || "manual",
    brandGuidelinesUrl: brandGuidelinesUrl || null,
    brainMode: normalizedMode,
    selectedPrebuiltBrainId: normalizedPrebuiltId,
    updatedAt: new Date(),
  };
  // When the user picks a prebuilt brain, mark the profile "generated" so OS
  // tools that gate on `status === 'generated'` (e.g. legacy guards) treat the
  // brain as ready without needing to run the OpenAI Generate Brain flow.
  if (normalizedMode === "prebuilt") {
    profileData.status = "generated";
    profileData.generatedAt = new Date();
  }
  if (confirmedLowTicketOffer !== undefined) {
    profileData.confirmedLowTicketOffer = confirmedLowTicketOffer || null;
  }
  if (confirmedPremiumOffer !== undefined) {
    profileData.confirmedPremiumOffer = confirmedPremiumOffer || null;
  }
  if (confirmed100kOffer !== undefined) {
    profileData.confirmed100kOffer = confirmed100kOffer || null;
  }

  if (existing) {
    const [updated] = await db.update(userBrainProfilesTable).set(profileData).where(eq(userBrainProfilesTable.userId, user.id)).returning();
    res.json({ profile: updated });
    return;
  } else {
    const [created] = await db.insert(userBrainProfilesTable).values({ userId: user.id, ...profileData }).returning();
    res.json({ profile: created });
    return;
  }
});

portalRouter.post("/portal/brain/scrape-colors", requireAuth, requireActive, async (req: any, res) => {
  let { url } = req.body || {};
  if (!url || typeof url !== "string") {
    res.status(400).json({ error: "URL is required" }); return;
  }
  url = url.trim();
  if (!/^https?:\/\//i.test(url)) url = "https://" + url;

  let parsed: URL;
  try {
    parsed = new URL(url);
  } catch {
    res.status(400).json({ error: "Invalid URL" }); return;
  }

  const fetchWithTimeout = async (u: string, timeoutMs = 8000): Promise<string> => {
    const ctrl = new AbortController();
    const t = setTimeout(() => ctrl.abort(), timeoutMs);
    try {
      const r = await fetch(u, {
        signal: ctrl.signal,
        headers: {
          "User-Agent": "Mozilla/5.0 (compatible; CookeMediaBrandBot/1.0)",
          "Accept": "text/html,text/css,*/*",
        },
        redirect: "follow",
      });
      if (!r.ok) throw new Error(`HTTP ${r.status}`);
      return await r.text();
    } finally {
      clearTimeout(t);
    }
  };

  // Two outputs only:
  //   1) primary  — the brand accent colour
  //   2) secondary — the page background (dark or light), plus a `backgroundStyle` flag
  type Color = { hex: string; r: number; g: number; b: number; sat: number; lum: number };

  const normalizeHex = (h: string): string | null => {
    h = h.replace("#", "").toLowerCase();
    if (h.length === 3) h = h.split("").map(c => c + c).join("");
    if (h.length === 4) h = h.slice(0, 3).split("").map(c => c + c).join("");
    if (h.length === 8) h = h.slice(0, 6);
    if (!/^[0-9a-f]{6}$/.test(h)) return null;
    return "#" + h;
  };

  const rgbToHex = (r: number, g: number, b: number): string =>
    "#" + [r, g, b].map(v => Math.max(0, Math.min(255, Math.round(v))).toString(16).padStart(2, "0")).join("");

  const toColor = (hex: string): Color | null => {
    const n = normalizeHex(hex);
    if (!n) return null;
    const r = parseInt(n.slice(1, 3), 16);
    const g = parseInt(n.slice(3, 5), 16);
    const b = parseInt(n.slice(5, 7), 16);
    const max = Math.max(r, g, b), min = Math.min(r, g, b);
    const sat = max === 0 ? 0 : (max - min) / max;
    const lum = (0.299 * r + 0.587 * g + 0.114 * b) / 255;
    return { hex: n, r, g, b, sat, lum };
  };

  // Saturated enough to be a "brand" colour (not grey, not near-black/near-white)
  const isBranded = (c: Color) =>
    c.r + c.g + c.b > 60 && (Math.max(c.r, c.g, c.b) - Math.min(c.r, c.g, c.b)) >= 35;

  // Parse `hsl(345 82% 52%)` or `hsl(345, 82%, 52%)` or raw `345 82% 52%` (Tailwind v4 / shadcn)
  const HSL_RE = /(?:hsla?\()?\s*(\d{1,3}(?:\.\d+)?)\s*[, ]\s*(\d{1,3}(?:\.\d+)?)\s*%\s*[, ]\s*(\d{1,3}(?:\.\d+)?)\s*%/g;
  const hslToRgb = (h: number, s: number, l: number): [number, number, number] => {
    s /= 100; l /= 100;
    const k = (n: number) => (n + h / 30) % 12;
    const a = s * Math.min(l, 1 - l);
    const f = (n: number) => l - a * Math.max(-1, Math.min(k(n) - 3, Math.min(9 - k(n), 1)));
    return [Math.round(255 * f(0)), Math.round(255 * f(8)), Math.round(255 * f(4))];
  };

  const HEX_RE = /#([0-9a-fA-F]{3,8})\b/g;
  const RGB_RE = /rgba?\(\s*(\d{1,3})\s*[, ]\s*(\d{1,3})\s*[, ]\s*(\d{1,3})\s*(?:[,/ ]\s*[\d.]+\s*)?\)/gi;

  // Pull every concrete colour value out of a CSS value string (handles hex/rgb/hsl/raw triplet).
  const extractColors = (text: string): Color[] => {
    const out: Color[] = [];
    let m: RegExpExecArray | null;
    HEX_RE.lastIndex = 0;
    while ((m = HEX_RE.exec(text)) !== null) {
      const c = toColor("#" + m[1]); if (c) out.push(c);
    }
    RGB_RE.lastIndex = 0;
    while ((m = RGB_RE.exec(text)) !== null) {
      const c = toColor(rgbToHex(+m[1], +m[2], +m[3])); if (c) out.push(c);
    }
    HSL_RE.lastIndex = 0;
    while ((m = HSL_RE.exec(text)) !== null) {
      const [r, g, b] = hslToRgb(parseFloat(m[1]) % 360, parseFloat(m[2]), parseFloat(m[3]));
      const c = toColor(rgbToHex(r, g, b)); if (c) out.push(c);
    }
    return out;
  };

  let html = "";
  try {
    html = await fetchWithTimeout(url, 10000);
  } catch (e: any) {
    res.status(502).json({ error: `Could not load page: ${e?.message || "fetch failed"}` }); return;
  }

  // Gather external CSS (SPA pages have an empty HTML shell).
  const cssLinks: string[] = [];
  const linkRe  = /<link[^>]+rel=["'][^"']*stylesheet[^"']*["'][^>]+href=["']([^"']+)["']/gi;
  const linkRe2 = /<link[^>]+href=["']([^"']+)["'][^>]+rel=["'][^"']*stylesheet[^"']*["']/gi;
  let lm: RegExpExecArray | null;
  while ((lm = linkRe.exec(html)) !== null) cssLinks.push(lm[1]);
  while ((lm = linkRe2.exec(html)) !== null) cssLinks.push(lm[1]);
  const assetCssRe = /["'](\/[^"']+\.css(?:\?[^"']*)?)["']/g;
  let am2: RegExpExecArray | null;
  while ((am2 = assetCssRe.exec(html)) !== null) cssLinks.push(am2[1]);

  const isFrameworkCss = (u: string) => /tailwind|bootstrap|normalize|reset|font-?awesome|materialize|bulma|foundation/i.test(u);
  const cssUrls = Array.from(new Set(cssLinks))
    .filter(u => !isFrameworkCss(u))
    .slice(0, 6)
    .map(href => { try { return new URL(href, parsed.origin).toString(); } catch { return null; } })
    .filter((u): u is string => !!u);

  const externalCss: string[] = await Promise.all(
    cssUrls.map(u => fetchWithTimeout(u, 6000).catch(() => ""))
  );

  // ALL the CSS sources we'll search across, in priority order:
  //   - inline <style> blocks                (page-owned CSS)
  //   - external CSS bundles                  (SPA case)
  //   - inline style="" attributes            (rare but unambiguous)
  const inlineStyleBlocks: string[] = [];
  const styleBlockRe = /<style[^>]*>([\s\S]*?)<\/style>/gi;
  let sb: RegExpExecArray | null;
  while ((sb = styleBlockRe.exec(html)) !== null) inlineStyleBlocks.push(sb[1]);

  const allCss = [...inlineStyleBlocks, ...externalCss].join("\n");

  // ---- Step 1: PRIMARY — pull from brand-named CSS variables, then theme-color ----
  // Tailwind/shadcn store HSL triplets in --primary; Bootstrap uses --bs-primary; etc.
  const brandVarRe = /--(?:bs-)?(?:color-)?(?:primary|brand|accent|main|theme|cta|action|hero)[a-z0-9-]*\s*:\s*([^;}\n]+)/gi;
  const brandedFromVars: Color[] = [];
  let bv: RegExpExecArray | null;
  while ((bv = brandVarRe.exec(allCss)) !== null) {
    for (const c of extractColors(bv[1])) {
      if (isBranded(c)) brandedFromVars.push(c);
    }
  }

  // theme-color meta — also a strong primary signal
  let themeColor: Color | null = null;
  const themeMatch = html.match(/<meta[^>]+name=["']theme-color["'][^>]+content=["']([^"']+)["']/i)
    || html.match(/<meta[^>]+content=["']([^"']+)["'][^>]+name=["']theme-color["']/i);
  if (themeMatch) {
    const c = toColor(themeMatch[1]);
    if (c && isBranded(c)) themeColor = c;
  }

  // Pick primary: prefer the most-saturated brand-var colour; fall back to theme-color;
  // last resort, scan rules that target buttons / CTAs / hero sections.
  let primary: Color | null = null;
  if (brandedFromVars.length) {
    // count occurrences, prefer most-frequent then most-saturated
    const counts = new Map<string, { c: Color; n: number }>();
    for (const c of brandedFromVars) {
      const ex = counts.get(c.hex);
      if (ex) ex.n++; else counts.set(c.hex, { c, n: 1 });
    }
    primary = [...counts.values()]
      .sort((a, b) => (b.n * (1 + b.c.sat)) - (a.n * (1 + a.c.sat)))[0].c;
  } else if (themeColor) {
    primary = themeColor;
  } else {
    // Last resort: look at colours appearing inside button/CTA rules
    const buttonRuleRe = /(?:\.btn|\.button|\.cta|\.primary|button)\b[^{}]{0,200}\{([^}]*)\}/gi;
    const buttonColors: Color[] = [];
    let br: RegExpExecArray | null;
    while ((br = buttonRuleRe.exec(allCss)) !== null) {
      for (const c of extractColors(br[1])) if (isBranded(c)) buttonColors.push(c);
    }
    if (buttonColors.length) {
      buttonColors.sort((a, b) => b.sat - a.sat);
      primary = buttonColors[0];
    }
  }

  if (!primary) {
    res.status(422).json({ error: "Could not detect a brand colour on that page. Try a different URL or set it manually." }); return;
  }

  // ---- Step 2: BACKGROUND — explicit body/html background colour ----
  const bodyBgRe = /(?:^|\})\s*(?:html|body|html\s*,\s*body|body\s*,\s*html)\s*\{[^}]*?background(?:-color)?\s*:\s*([^;}]+)[^}]*\}/gi;
  let bgColor: Color | null = null;
  let bg: RegExpExecArray | null;
  while ((bg = bodyBgRe.exec(allCss)) !== null) {
    const cs = extractColors(bg[1]);
    if (cs.length) { bgColor = cs[0]; break; }
  }
  // Fallback: a --background CSS variable
  if (!bgColor) {
    const bgVarRe = /--(?:color-)?(?:background|bg|surface|page)[a-z0-9-]*\s*:\s*([^;}\n]+)/gi;
    let v: RegExpExecArray | null;
    while ((v = bgVarRe.exec(allCss)) !== null) {
      const cs = extractColors(v[1]);
      if (cs.length) { bgColor = cs[0]; break; }
    }
  }

  // Decide light vs dark. If we couldn't find it, infer from primary's contrast preference:
  //   most modern brand sites with a saturated mid-luminance accent are dark.
  const backgroundStyle: "light" | "dark" =
    bgColor ? (bgColor.lum > 0.6 ? "light" : "dark") : "dark";
  const secondary: Color = bgColor || (backgroundStyle === "dark" ? toColor("#0a0a0a")! : toColor("#ffffff")!);

  // Build a small palette for the UI: primary + a couple of supporting brand colours + the bg.
  const allBranded = brandedFromVars.length ? brandedFromVars : extractColors(allCss).filter(isBranded);
  const dedup = new Map<string, Color>();
  for (const c of [primary, ...allBranded, secondary]) if (!dedup.has(c.hex)) dedup.set(c.hex, c);
  const palette = [...dedup.values()].slice(0, 6).map(c => c.hex);

  res.json({
    primary: primary.hex,
    secondary: secondary.hex,
    backgroundStyle,
    palette,
    themeColor: themeColor?.hex || null,
    sourceUrl: url,
  });
});

portalRouter.post("/portal/brain/generate", requireAuth, requireActive, async (req: any, res) => {
  const user = req.portalUser;
  const [profile] = await db.select().from(userBrainProfilesTable).where(eq(userBrainProfilesTable.userId, user.id));

  if (!profile) {
    res.status(400).json({ error: "Please save your profile information first" }); return;
  }

  await db.update(userBrainProfilesTable).set({ status: "generating", updatedAt: new Date() }).where(eq(userBrainProfilesTable.userId, user.id));

  void (async () => {
  try {
    let scrapedContent: any = {};

    const urlsToScrape: string[] = [];
    if (profile.website) urlsToScrape.push(profile.website);
    if (Array.isArray(profile.landingPages)) {
      (profile.landingPages as string[]).forEach(lp => { if (lp) urlsToScrape.push(lp); });
    }
    if (Array.isArray(profile.socialProfiles)) {
      (profile.socialProfiles as string[]).forEach(sp => { if (sp) urlsToScrape.push(sp); });
    }

    if (urlsToScrape.length > 0) {
      const apifyToken = process.env.APIFY_API_TOKEN;
      if (apifyToken) {
        const detectPlatform = (raw: string): "linkedin" | "instagram" | "tiktok" | "youtube" | "web" => {
          const u = raw.toLowerCase();
          if (u.includes("linkedin.com")) return "linkedin";
          if (u.includes("instagram.com")) return "instagram";
          if (u.includes("tiktok.com")) return "tiktok";
          if (u.includes("youtube.com") || u.includes("youtu.be")) return "youtube";
          return "web";
        };
        const extractIgUsername = (raw: string): string | null => {
          const m = raw.match(/instagram\.com\/([^\/?#]+)/i);
          if (!m) return null;
          const reserved = ["p", "reel", "reels", "explore", "stories", "tv", "accounts"];
          return reserved.includes(m[1].toLowerCase()) ? null : m[1].replace(/^@/, "");
        };
        const extractTikTokUsername = (raw: string): string | null => {
          const m = raw.match(/tiktok\.com\/@([^\/?#]+)/i);
          return m ? m[1] : null;
        };

        const buildActorCall = (url: string): { actorId: string; input: any } | null => {
          const platform = detectPlatform(url);
          switch (platform) {
            case "linkedin":
              return { actorId: "harvestapi~linkedin-profile-posts", input: { profileUrls: [url], maxPosts: 20 } };
            case "instagram": {
              const username = extractIgUsername(url);
              if (!username) return null;
              return { actorId: "apify~instagram-profile-scraper", input: { usernames: [username], resultsLimit: 20 } };
            }
            case "tiktok": {
              const username = extractTikTokUsername(url);
              if (!username) return null;
              return { actorId: "clockworks~tiktok-scraper", input: { profiles: [username], resultsPerPage: 20, shouldDownloadVideos: false, shouldDownloadCovers: false } };
            }
            case "youtube":
              return { actorId: "streamers~youtube-scraper", input: { startUrls: [{ url }], maxResults: 20, maxResultsShorts: 0, maxResultStreams: 0 } };
            case "web":
            default:
              return {
                actorId: "apify~website-content-crawler",
                input: {
                  startUrls: [{ url }],
                  maxCrawlPages: 5,
                  maxCrawlDepth: 1,
                  crawlerType: "cheerio",
                  saveHtml: false,
                  saveMarkdown: true,
                },
              };
          }
        };

        const summarizeItem = (platform: string, item: any): { title: string; text: string; url: string } => {
          const truncate = (s: any, n: number) => (typeof s === "string" ? s.substring(0, n) : "");
          const stripHtml = (s: any): string =>
            typeof s === "string" ? s.replace(/<[^>]*>/g, " ").replace(/\s+/g, " ").trim() : "";

          if (platform === "web") {
            const body = item.markdown || item.text || stripHtml(item.html);
            return { title: item.title || item.metadata?.title || "", text: truncate(body, 4000), url: item.url || "" };
          }

          if (platform === "linkedin") {
            const author = item.author?.fullName || item.author?.name || item.authorName || "";
            const headline = item.author?.headline || item.author?.subtitle || "";
            const body = stripHtml(item.text || item.content || item.commentary || "");
            return {
              title: `${author}${headline ? " — " + headline : ""}`.trim() || "LinkedIn post",
              text: truncate(body, 1500),
              url: item.linkedinUrl || item.postUrl || item.url || "",
            };
          }

          if (platform === "instagram") {
            const bio = item.biography || "";
            const fullName = item.fullName || "";
            const username = item.username || "";
            const followers = item.followersCount || 0;
            const category = item.businessCategoryName || item.category || "";
            const externalUrl = item.externalUrl || "";
            const posts = Array.isArray(item.latestPosts) ? item.latestPosts : [];
            const captionLines = posts.slice(0, 12).map((p: any, i: number) => {
              const caption = (p.caption || "").replace(/\s+/g, " ").trim();
              const hashtags = Array.isArray(p.hashtags) && p.hashtags.length ? `  [#${p.hashtags.slice(0, 8).join(" #")}]` : "";
              const likes = p.likesCount ? `  (${p.likesCount} likes)` : "";
              return caption ? `${i + 1}. ${caption.substring(0, 280)}${hashtags}${likes}` : null;
            }).filter(Boolean).join("\n");
            return {
              title: `${fullName} (@${username}) — ${followers.toLocaleString()} followers${category ? " — " + category : ""}`,
              text: truncate(
                `BIO: ${bio}\nEXTERNAL LINK: ${externalUrl}\n\nRECENT POST CAPTIONS (best signal for tone, topics & niche):\n${captionLines}`,
                5000,
              ),
              url: item.url || `https://instagram.com/${username}`,
            };
          }

          if (platform === "tiktok") {
            const author = item.authorMeta?.nickName || item.authorMeta?.name || "";
            const handle = item.authorMeta?.name ? `@${item.authorMeta.name}` : "";
            const followers = item.authorMeta?.fans || 0;
            const caption = (item.text || "").replace(/\s+/g, " ").trim();
            const hashtags = Array.isArray(item.hashtags) && item.hashtags.length
              ? ` [#${item.hashtags.slice(0, 8).map((h: any) => h.name || h).join(" #")}]`
              : "";
            const stats = `views=${item.playCount || 0} likes=${item.diggCount || 0} comments=${item.commentCount || 0}`;
            return {
              title: `${author} ${handle} — ${followers.toLocaleString()} followers`.trim(),
              text: truncate(`CAPTION: ${caption}${hashtags}\nSTATS: ${stats}`, 1500),
              url: item.webVideoUrl || item.videoUrl || "",
            };
          }

          if (platform === "youtube") {
            const channel = item.channelName || item.channel?.name || "";
            const title = item.title || "YouTube video";
            const desc = stripHtml(item.description || item.text || "");
            const tags = Array.isArray(item.keywords) && item.keywords.length ? ` [tags: ${item.keywords.slice(0, 10).join(", ")}]` : "";
            const views = item.viewCount ? ` (${item.viewCount} views)` : "";
            return {
              title: `${channel} — ${title}${views}`.trim(),
              text: truncate(`${desc}${tags}`, 1500),
              url: item.url || item.videoUrl || "",
            };
          }

          return { title: "", text: truncate(JSON.stringify(item), 1500), url: "" };
        };

        const runActor = async (url: string) => {
          const call = buildActorCall(url);
          if (!call) return { url, items: [] as any[] };
          const platform = detectPlatform(url);
          try {
            const ctrl = new AbortController();
            const timer = setTimeout(() => ctrl.abort(), 120_000);
            // Task #169: inject admin-managed IG session cookies for IG actors.
            let actorInput: any = call.input;
            try {
              const igMod = await import("../lib/instagram-session-cookies");
              if (igMod.isInstagramActor(call.actorId)) {
                actorInput = await igMod.withInstagramSessionCookies(call.actorId, call.input ?? {});
              }
            } catch { /* proceed anonymously */ }
            const response = await fetch(
              `https://api.apify.com/v2/acts/${call.actorId}/run-sync-get-dataset-items?token=${apifyToken}&timeout=110&memory=1024`,
              {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify(actorInput),
                signal: ctrl.signal,
              },
            );
            clearTimeout(timer);
            if (!response.ok) {
              console.error(`Apify ${call.actorId} HTTP ${response.status} for ${url}`);
              return { url, items: [] };
            }
            const data = await response.json();
            const items = (Array.isArray(data) ? data : []).slice(0, 25).map((it: any) => summarizeItem(platform, it));
            return { url, items };
          } catch (err: any) {
            console.error(`Apify scrape error for ${url} (${call.actorId}):`, err?.message || err);
            return { url, items: [] };
          }
        };

        const results = await Promise.allSettled(urlsToScrape.slice(0, 10).map(runActor));
        for (const r of results) {
          if (r.status === "fulfilled" && r.value.items.length > 0) {
            scrapedContent[r.value.url] = r.value.items;
          }
        }
      }
    }

    const openai = new OpenAI({
      baseURL: process.env.AI_INTEGRATIONS_OPENAI_BASE_URL,
      apiKey: process.env.AI_INTEGRATIONS_OPENAI_API_KEY,
    });

    const scrapedSummary = Object.keys(scrapedContent).length > 0
      ? "\n\nSCRAPED WEBSITE/SOCIAL DATA:\n" + Object.entries(scrapedContent).map(([url, pages]) =>
          `--- ${url} ---\n${(pages as any[]).map((p: any) => `${p.title || ""}:\n${p.text || ""}`).join("\n\n")}`
        ).join("\n\n")
      : "";

    // Task #725: single-retry-with-backoff around the OpenAI completion
    // so a transient 429 / 5xx / ECONNRESET doesn't silently flip the
    // brain to status='error' and force the user to retry from scratch.
    const callOpenAi = () => openai.chat.completions.create({
      model: "gpt-4o",
      messages: [
        {
          role: "system",
          content: `You are an expert business analyst and brand strategist building a comprehensive "Brain" profile for a creator/coach. This Brain is the single source of truth that downstream AI tools will use to generate funnels, offers, sales pages, emails, and marketing copy — so accuracy, specificity, and pattern-matching from their real content matter more than generic advice.

You will be given (a) what the user typed about themselves, and (b) raw scraped data from their website + social profiles (LinkedIn posts, Instagram bio + captions, TikTok captions, YouTube titles + descriptions). TREAT THE SCRAPED CONTENT AS THE PRIMARY EVIDENCE. The captions and post text reveal who they really are — their actual tone, the topics they obsess over, the slang/phrases they use, the audience they're talking to, and the market they operate in.

Output a detailed HTML Brain profile with these sections:

<h3>Business Overview</h3> — What they do, the company, their position in the market.
<h3>Niche & Market</h3> — The exact niche/sub-niche they own, the broader market category, who their direct competitors are (infer from content), and what makes them different.
<h3>Target Audience</h3> — Their ideal client: demographics, psychographics, pain points, desires, language they use about themselves. Pull specifics from the captions/posts.
<h3>Topics They Speak About</h3> — Bullet list of the 8-15 recurring themes/topics across their content (e.g. "low-ticket offers", "lead magnets", "agency life"). Quote 2-3 specific post titles or caption snippets as evidence.
<h3>Tone of Voice & Writing Style</h3> — How they actually talk: sentence rhythm, formal vs casual, use of slang/swearing/emojis, hooks they favour, story structures they use, signature phrases. Give 3-5 verbatim quote examples from the scraped data.
<h3>Value Proposition & Unique Mechanism</h3> — What they help clients achieve and the specific framework/method/POV that makes them different.
<h3>Key Achievements & Social Proof</h3> — Numbers, results, testimonials, credentials surfaced from their content.
<h3>Brand Identity</h3> — Visual style, colour usage, positioning archetype (e.g. authority/rebel/mentor).
<h3>Content & Marketing Approach</h3> — Where they post, what formats work for them, posting cadence signals, hooks they reuse.
<h3>Offer Architecture Recommendations</h3> — How their low-ticket, mid-ticket and high-ticket offers should be structured based on this evidence.
<h3>Key Messaging & Copy Angles</h3> — Primary hooks, pain points, desire triggers, and 5-10 ready-to-use angle ideas written in THEIR voice (using their phrases and rhythm).

Rules:
- Be specific and evidence-based. When you make a claim about tone or topic, back it up by quoting or paraphrasing the scraped data.
- If a section has no evidence, say "Insufficient data — recommend collecting X" rather than inventing.
- Use <h3>, <p>, <ul>/<li>, <strong>. No markdown. No code fences. Output HTML only.`
        },
        {
          role: "user",
          content: `Here is the user's profile information:

Name: ${profile.name || "Not provided"}
Company: ${profile.companyName || "Not provided"}
Who They Help: ${profile.whoDoYouHelp || "Not provided"}
How They Help Them: ${profile.howDoYouHelpThem || "Not provided"}
Key Achievements/Results: ${profile.keyAchievements || "Not provided"}
Website: ${profile.website || "Not provided"}
Landing Pages: ${Array.isArray(profile.landingPages) ? (profile.landingPages as string[]).join(", ") : "None"}
Social Profiles: ${Array.isArray(profile.socialProfiles) ? (profile.socialProfiles as string[]).join(", ") : "None"}
Brand Colors: Primary ${profile.brandColorPrimary || "Not set"}, Secondary ${profile.brandColorSecondary || "Not set"}
${scrapedSummary}

Generate a comprehensive Brain profile.`
        },
      ],
      max_tokens: 4000,
    });
    let completion;
    try {
      completion = await callOpenAi();
    } catch (err: any) {
      const status = err?.status ?? err?.response?.status;
      const code = err?.code ?? err?.response?.code;
      const transient = status === 429 || (typeof status === "number" && status >= 500) || code === "ECONNRESET" || code === "ETIMEDOUT";
      if (transient) {
        console.warn("brain/generate: OpenAI transient error, retrying once", { status, code, err: err?.message });
        await new Promise((resolve) => setTimeout(resolve, 1000 + Math.floor(Math.random() * 500)));
        completion = await callOpenAi();
      } else {
        throw err;
      }
    }

    const generatedBrain = completion.choices[0]?.message?.content || "";

    await db.update(userBrainProfilesTable).set({
      generatedBrain,
      scrapedData: scrapedContent,
      status: "generated",
      generatedAt: new Date(),
      updatedAt: new Date(),
    }).where(eq(userBrainProfilesTable.userId, user.id));
  } catch (err: any) {
    // Task #725: persist the real error onto the row so the GET /portal/brain
    // endpoint can surface it as `errorMessage` instead of leaving the UI
    // to show a flat "Failed to generate brain".
    const status = err?.status ?? err?.response?.status;
    const code = err?.code ?? err?.response?.code;
    let errorCode = "internal_error";
    let errorMessage = err?.message ? String(err.message) : "Brain generation failed for an unknown reason.";
    if (status === 429) {
      errorCode = "upstream_unavailable";
      errorMessage = "OpenAI is rate-limiting our requests right now. Please try again in a minute.";
    } else if (typeof status === "number" && status >= 500) {
      errorCode = "upstream_unavailable";
      errorMessage = "OpenAI is temporarily unavailable. Please try again in a few minutes.";
    } else if (code === "ECONNRESET" || code === "ETIMEDOUT") {
      errorCode = "upstream_unavailable";
      errorMessage = "We couldn't reach OpenAI just now. Please try again in a minute.";
    } else if (status === 400 || status === 422) {
      errorCode = "validation_failed";
      errorMessage = `OpenAI rejected the brain request: ${errorMessage}`;
    }
    console.error("brain/generate: background generation failed", { status, code, err: err?.message });
    await db.update(userBrainProfilesTable).set({
      status: "error",
      scrapedData: { __error: errorMessage, __errorCode: errorCode } as any,
      updatedAt: new Date(),
    }).where(eq(userBrainProfilesTable.userId, user.id));
  }
  })();
  res.json({ started: true, status: "generating" });
  return;
});

// ─── RESEARCH GENERATION JOBS ────────────────────────────────────────────────

type EvidenceCategory =
  | "academic-clinical"
  | "analyst-business"
  | "latest-news"
  | "market-sizing"
  | "voice-of-customer"
  | "competitors";

type CredibilityTier = "tier1-primary" | "tier2-major" | "tier3-supporting";

type EvidenceItem = {
  title: string;
  url: string;
  domain: string;
  snippet: string;
  fullText: string;
  category: EvidenceCategory;
  credibilityTier: CredibilityTier;
  publishedDate?: string;
  author?: string;
  publisher?: string;
  rankScore: number;
};

type ResearchBrief = {
  subTopics: string[];
  audienceTerminology: string[];
  adjacentIndustries: string[];
  isHealthClinical: boolean;
  isB2BSaas: boolean;
  isConsumer: boolean;
  mustFindSources: string[];
  competitorBrands: string[];
};

const TIER1_DOMAINS = [
  "pubmed.ncbi.nlm.nih.gov", "ncbi.nlm.nih.gov", "nih.gov", "cdc.gov", "who.int",
  "nature.com", "sciencedirect.com", "nejm.org", "jamanetwork.com", "thelancet.com",
  "bmj.com", "cell.com", "springer.com", "wiley.com", "tandfonline.com", "plos.org",
  "scholar.google.com", "ssrn.com", "arxiv.org",
  "harvard.edu", "stanford.edu", "mit.edu", "yale.edu", "princeton.edu", "berkeley.edu",
  "ox.ac.uk", "cam.ac.uk", "ucl.ac.uk", "lse.ac.uk", "imperial.ac.uk",
  "mayoclinic.org", "clevelandclinic.org", "hopkinsmedicine.org", "uchicagomedicine.org",
];
const TIER2_DOMAINS = [
  "mckinsey.com", "bain.com", "bcg.com", "deloitte.com", "pwc.com", "kpmg.com", "accenture.com", "ey.com",
  "hbr.org", "sloanreview.mit.edu", "knowledge.wharton.upenn.edu",
  "gartner.com", "forrester.com", "idc.com", "cbinsights.com",
  "pewresearch.org", "statista.com", "nielsen.com", "edelman.com", "ipsos.com",
  "wsj.com", "ft.com", "bloomberg.com", "reuters.com", "economist.com",
  "forbes.com", "fortune.com", "fastcompany.com", "wired.com", "techcrunch.com", "theverge.com",
  "nytimes.com", "washingtonpost.com", "theguardian.com", "bbc.com", "cnbc.com",
];
