portalRouter.get("/portal/os-tools/:slug/quota", requireAuth, async (req: any, res) => {
  const user = req.portalUser;
  const { slug } = req.params;

  const lifetimeRows = await db.select({ id: osToolGenerationJobsTable.id }).from(osToolGenerationJobsTable)
    .where(and(
      eq(osToolGenerationJobsTable.userId, user.id),
      eq(osToolGenerationJobsTable.slug, slug),
      eq(osToolGenerationJobsTable.status, "done"),
    ));
  const lifetimeUsed = lifetimeRows.length;

  // Admins always have unlimited generations.
  if (user.role === "admin") {
    res.json({
      lifetimeUsed,
      freeQuota: 999,
      freeRemaining: 999,
      creditCost: 0,
      balance: 999,
      unlimited: true,
      isAdmin: true,
    }); return;
  }

  // Standard phase tools are always free — unlimited for every active user.
  const OS_TOOL_ALWAYS_UNLIMITED = new Set([
    "bridge-page-headlines",
    "kpi-generator",
    "direct-offer-ad-generator",
  ]);
  if (OS_TOOL_ALWAYS_UNLIMITED.has(slug)) {
    res.json({
      lifetimeUsed,
      freeQuota: 999,
      freeRemaining: 999,
      creditCost: 0,
      balance: user.osToolPaidCredits ?? 0,
      unlimited: true,
      alwaysUnlimited: true,
    }); return;
  }

  // Greg AI subscribers get unlimited Direct Offer Ad Generator runs.
  let gregAiUnlimited = false;
  if (slug === "direct-offer-ad-generator") {
    const ent = await computePurchaseEntitlements(user);
    gregAiUnlimited = ent.upsell1Paid || ent.downsell1Paid;
  }
  if (gregAiUnlimited) {
    res.json({
      lifetimeUsed,
      freeQuota: 999,
      freeRemaining: 999,
      creditCost: 0,
      balance: user.osToolPaidCredits ?? 0,
      unlimited: true,
      gregAiUnlimited: true,
    }); return;
  }

  const freeQuota = osToolFreeQuotaFor(slug);
  const creditCost = osToolCreditCostFor(slug);
  const freeRemaining = Math.max(0, freeQuota - lifetimeUsed);
  res.json({
    lifetimeUsed,
    freeQuota,
    freeRemaining,
    creditCost,
    balance: user.osToolPaidCredits ?? 0,
    unlimited: false,
  });
});

