// Create a Stripe Checkout session for the chosen OS tool credit pack.
// The /confirm endpoint validates metadata.purpose and metadata.packId
// before granting credits. The whopSessionId column on
// osToolCreditPurchasesTable now stores the Stripe Checkout Session id.
portalRouter.post("/portal/os-tools/credits/purchase", requireAuth, requireActive, async (_req: any, res) => {
  // OS tool credit pack purchasing (the legacy Stripe ad-hoc checkout) is
  // retired. Credit provisioning now flows through the GoHighLevel
  // purchase stack.
  res.status(410).json({
    error: "credit_purchasing_retired",
    message:
      "Credit purchasing has moved. Please reach out through the support chat and we will sort this out for you.",
  });
  return;
});

// Confirm a Stripe Checkout session and grant credits to the user.
portalRouter.post("/portal/os-tools/credits/confirm", requireAuth, requireActive, async (req: any, res) => {
  try {
    const user = req.portalUser;
    const { sessionId } = req.body;
    if (!sessionId || typeof sessionId !== "string") {
      res.status(400).json({ error: "sessionId required" }); return;
    }

    // Pre-flight check (read-only, no charge). Tells us early whether to even
    // bother hitting Stripe.
    const [preCheck] = await db.select().from(osToolCreditPurchasesTable)
      .where(eq(osToolCreditPurchasesTable.whopSessionId, sessionId));

    if (preCheck && preCheck.userId !== user.id) {
      res.status(403).json({ error: "Session does not belong to this user" }); return;
    }

    if (preCheck && preCheck.status === "granted") {
      const [fresh] = await db.select().from(portalUsersTable).where(eq(portalUsersTable.id, user.id));
      res.json({
        granted: false,
        alreadyGranted: true,
        creditsGranted: preCheck.creditsGranted,
        balance: fresh?.osToolPaidCredits ?? 0,
      }); return;
    }

    // Stripe-backed OS tool credit confirmation is retired. Any already
    // granted purchase remains valid (idempotent read above); no new Stripe
    // session verification runs.
    res.status(410).json({
      error: "credit_purchasing_retired",
      message:
        "Credit purchasing has moved. Please reach out through the support chat and we will sort this out for you.",
    });
    return;
  } catch (error: any) {
    console.error("Confirm OS tool credit error:", error);
    res.status(500).json({ error: error.message });
    return;
  }
});

