/* ─────────────────────────────────────────────────────────────────────────
   JSON PROMPT GENERATOR — analyse a reference image + brand context,
   return a structured JSON prompt for image generators (Higgsfield, nano-banana,
   MidJourney, etc.) AND a natural-language prompt the user can paste into
   their own Replit coding agent to regenerate/swap the image.
   ───────────────────────────────────────────────────────────────────────── */

const IMAGE_SLOT_PRESETS: Record<string, { aspect: string; label: string }> = {
  "hero":         { aspect: "16:9",   label: "Hero / Sales Page Banner" },
  "square":       { aspect: "1:1",    label: "Square (Product / Testimonial Card)" },
  "portrait":     { aspect: "4:5",    label: "Portrait (Founder / Avatar)" },
  "mobile-hero":  { aspect: "9:16",   label: "Mobile Hero / Story" },
  "wide-banner":  { aspect: "21:9",   label: "Ultra-Wide Banner" },
  "thumbnail":    { aspect: "16:9",   label: "Thumbnail / Video Still" },
  "background":   { aspect: "16:9",   label: "Background / Section Fill" },
  "testimonial":  { aspect: "1:1",    label: "Testimonial Avatar / Proof Card" },
};

portalRouter.post(
  "/portal/image-prompt-generator",
  requireAuth,
  upload.single("referenceImage"),
  async (req: any, res) => {
    try {
      const user = req.portalUser;
      const slotKey = String(req.body?.slot || "hero").toLowerCase();
      const slotInfo = IMAGE_SLOT_PRESETS[slotKey] || IMAGE_SLOT_PRESETS["hero"];
      const customAspect = String(req.body?.aspectRatio || "").trim();
      const aspect = customAspect || slotInfo.aspect;
      const context = String(req.body?.context || "").slice(0, 2000);
      const subject = String(req.body?.subject || "").slice(0, 500);
      const mood = String(req.body?.mood || "").slice(0, 300);
      const targetPagePath = String(req.body?.targetPagePath || "").slice(0, 400);

      const [brainRow] = await db
        .select()
        .from(userBrainProfilesTable)
        .where(eq(userBrainProfilesTable.userId, user.id));
      const brain = resolveEffectiveBrain(brainRow, getPortalKey(req));

      const brandHexes: string[] = [];
      if (brain?.brandColorPrimary) brandHexes.push(brain.brandColorPrimary);
      if (brain?.brandColorSecondary) brandHexes.push(brain.brandColorSecondary);

      const brandContext = `
Business Owner: ${brain?.name || "Not specified"}
Company: ${brain?.companyName || "Not specified"}
Who They Help: ${brain?.whoDoYouHelp || "Not specified"}
How They Help Them: ${brain?.howDoYouHelpThem || "Not specified"}
Brand Colours: ${brandHexes.length ? brandHexes.join(", ") : "Not specified"}
`.trim();

      const openai = new OpenAI({
        baseURL: process.env.AI_INTEGRATIONS_OPENAI_BASE_URL,
        apiKey: process.env.AI_INTEGRATIONS_OPENAI_API_KEY,
      });

      // Step 1 — if a reference image was uploaded, run a quick vision pass
      // to extract composition, subject, lighting, colour and style cues we
      // can fold into the final prompt.
      let referenceAnalysis = "";
      if (req.file?.buffer) {
        try {
          const base64 = req.file.buffer.toString("base64");
          const mime = req.file.mimetype || "image/png";
          const dataUrl = `data:${mime};base64,${base64}`;
          const vision = await openai.chat.completions.create({
            model: "gpt-4o",
            messages: [
              {
                role: "user",
                content: [
                  {
                    type: "text",
                    text:
                      "Describe this reference image for an image-generation prompt. Cover: (1) Subject & pose, (2) Composition & framing, (3) Lighting direction & quality, (4) Colour palette & mood, (5) Background / environment, (6) Lens feel / depth-of-field, (7) Overall visual style (e.g. editorial, cinematic, flat-vector, product studio, candid iPhone). Be specific and concrete. 120-180 words. No preamble.",
                  },
                  { type: "image_url", image_url: { url: dataUrl, detail: "high" } },
                ] as any,
              },
            ],
            max_tokens: 500,
          });
          referenceAnalysis = vision.choices[0]?.message?.content || "";
        } catch (e: any) {
          console.error("image-prompt vision failed:", e?.message);
        }
      }

      const systemPrompt = `You are an elite image-prompt engineer. You build production-grade JSON prompts for modern image-generation tools (Higgsfield, Google nano-banana, MidJourney, Ideogram, DALL·E) AND a natural-language "replace this image" prompt a non-technical user can paste into their own Replit coding agent.

HARD RULES:
- Never invent people's identities, faces, or trademarked brands that aren't in the context.
- If a reference image was analysed, MATCH its composition, lighting, and mood — do not reinvent them, but upgrade quality and polish.
- Lock the aspect ratio to the user's selected slot.
- Fold the user's brand colour hex codes into the palette if provided.
- Never mention any copywriter, guru, author, book, or third-party brand (e.g. Sabri, Suby, Sell Like Crazy, King Kong, Hormozi, Schwartz, Breakthrough Advertising).
- Output ONLY valid JSON — a single object with the fields below, no preamble, no trailing commentary.

OUTPUT JSON SCHEMA:
{
  "imagePrompt": {
    "subject": string,              // the main thing in the image
    "composition": string,          // framing, angle, rule-of-thirds, focal point
    "setting": string,              // environment / background
    "lighting": string,             // direction, quality, colour temperature
    "mood": string,                 // emotional tone
    "colorPalette": string[],       // 3-6 colours, include brand hexes where relevant
    "style": string,                // editorial / cinematic / studio / candid iPhone / flat-vector etc.
    "lensAndDepth": string,         // e.g. "85mm f/1.8, shallow DOF, background bokeh"
    "details": string[],            // 4-8 concrete details to include
    "negative": string[],           // 4-8 things to avoid (low-res, warped hands, extra fingers, text artifacts, watermark, stock-photo cheese)
    "aspectRatio": string,          // exact ratio the user selected
    "quality": "high" | "photoreal" | "editorial" | "studio",
    "outputFormat": "png" | "jpg" | "webp"
  },
  "generatorHints": {
    "higgsfield": string,           // 1-line prompt optimised for Higgsfield nano-banana
    "midjourney": string,           // 1-line prompt with --ar and --style cues
    "nanoBanana": string,           // 1-line prompt optimised for Google nano-banana pro
    "dalle": string                 // 1-line prompt optimised for DALL·E-3
  },
  "replitAgentPrompt": string       // 4-10 short paragraphs. A ready-to-paste prompt telling the coding agent EXACTLY what to do: what image slot to replace, what file/component to edit (use targetPagePath if provided, else infer), what image to generate (repeat subject/style/palette in plain English), the exact aspect ratio, and to use Replit's built-in image generation tool. End with "Do not change layout, surrounding copy, or responsive behaviour."
}`;

      const userPrompt = `USER BUSINESS / BRAND CONTEXT:
${brandContext}

IMAGE SLOT: ${slotInfo.label}
ASPECT RATIO: ${aspect}
${targetPagePath ? `TARGET PAGE / COMPONENT PATH (where the image lives in their build): ${targetPagePath}` : ""}

USER SUBJECT / WHAT THEY WANT: ${subject || "(not specified — infer from context)"}
USER MOOD / TONE NOTES: ${mood || "(not specified)"}
USER EXTRA CONTEXT: ${context || "(none)"}

${referenceAnalysis ? `REFERENCE IMAGE ANALYSIS (match its composition & mood, upgrade the polish):\n${referenceAnalysis}` : "(No reference image supplied — design from scratch using the brand context.)"}

Return the JSON object described in the schema. JSON only.`;

      const completion = await openai.chat.completions.create({
        model: "gpt-4o",
        messages: [
          { role: "system", content: systemPrompt },
          { role: "user", content: userPrompt },
        ],
        response_format: { type: "json_object" },
        temperature: 0.75,
        max_tokens: 2800,
      });

      const raw = completion.choices[0]?.message?.content || "{}";
      let parsed: any = {};
      try { parsed = JSON.parse(raw); } catch { parsed = {}; }

      const responseBody = {
        ok: true,
        aspect,
        slot: slotInfo.label,
        referenceAnalysis,
        ...parsed,
      };
      res.json(responseBody);
      void saveToolGeneration({
        portalUserId: user.id,
        toolSlug: "image-prompt-generator",
        label: `${slotInfo.label}${subject ? ` - ${subject.slice(0, 80)}` : ""}`,
        input: { slot: slotKey, slotLabel: slotInfo.label, aspect, subject, mood, context, targetPagePath, hadReference: !!req.file?.buffer },
        output: responseBody,
      });
      return;
    } catch (e: any) {
      console.error("image-prompt-generator error:", e);
      res.status(500).json({ error: e?.message || "Failed to generate image prompt" });
      return;
    }
  }
);

// -----------------------------------------------------------------------------
// Avatar Prompt Generator (Room30 — Phase 3 "Creating Unique Avatar" lesson)
// -----------------------------------------------------------------------------
// Accepts 1-3 reference avatar images, runs each through GPT-4o vision to
// extract face/skin/hair/clothing/lighting/environment cues, then synthesises
// a single hyper-detailed JSON prompt the user can paste into Higgsfield
// (nano-banana pro), MidJourney, or any JSON-aware image generator. Output
// matches the schema shape from the lesson playbook (subject.identity,
// composition, environment, technical_specifications, consistency_id).

portalRouter.post(
  "/portal/avatar-prompt-generator",
  requireAuth,
  upload.array("referenceImages", 3),
  async (req: any, res) => {
    try {
      const user = req.portalUser;
      const files: Express.Multer.File[] = (req.files as any) || [];
      if (files.length === 0) {
        res.status(400).json({ error: "Upload at least one reference image." }); return;
      }

      // Locked output: studio head-and-shoulders, front-on, plain white
      // background. Everything else (gender, age, hair, skin, clothing, vibe)
      // is auto-detected from the uploaded reference image(s).
      const perspective = "studio-headshot-front-white-bg";

      const [brainRow] = await db
        .select()
        .from(userBrainProfilesTable)
        .where(eq(userBrainProfilesTable.userId, user.id));
      const brain = resolveEffectiveBrain(brainRow, getPortalKey(req));

      const brandContext = `
Owner: ${brain?.name || "Not specified"}
Company: ${brain?.companyName || "Not specified"}
Who they help: ${brain?.whoDoYouHelp || "Not specified"}
`.trim();

      const openai = new OpenAI({
        baseURL: process.env.AI_INTEGRATIONS_OPENAI_BASE_URL,
        apiKey: process.env.AI_INTEGRATIONS_OPENAI_API_KEY,
      });

      // Step 1 — vision-analyse each reference image in parallel.
      const referenceAnalyses: string[] = await Promise.all(
        files.map(async (f, idx) => {
          try {
            const base64 = f.buffer.toString("base64");
            const mime = f.mimetype || "image/png";
            const dataUrl = `data:${mime};base64,${base64}`;
            const vision = await openai.chat.completions.create({
              model: "gpt-4o",
              messages: [
                {
                  role: "user",
                  content: [
                    {
                      type: "text",
                      text:
                        "Analyse this reference avatar image for an image-generation prompt. Be EXTREMELY specific and concrete. Cover EVERY one of these in order: " +
                        "(1) Apparent gender, age range, ethnicity cues. " +
                        "(2) Hair: length, colour with highlights/lowlights, texture, parting, styling. " +
                        "(3) Eyes: colour, shape, eyelash detail, gaze direction. " +
                        "(4) Skin: tone, undertone, freckles, pores, makeup vs natural, blemishes. " +
                        "(5) Facial structure: face shape, jaw, cheekbones, lip shape, eyebrows. " +
                        "(6) Expression and mouth (smiling, neutral, mouth open, etc.). " +
                        "(7) Clothing: top, layers, fabric type, colour, collar/neckline detail. " +
                        "(8) Accessories: earrings, necklaces, glasses, watches, nails, phone in hand. " +
                        "(9) Composition and framing: shot type (selfie/MCU/portrait), angle (low/eye-level/high), aspect ratio guess, hand visible or not. " +
                        "(10) Environment: location type, key background elements, depth-of-field. " +
                        "(11) Lighting: type (natural/studio), direction, colour temperature, time of day. " +
                        "(12) Technical feel: camera profile (iPhone front cam vs DSLR), focal length, f-stop guess, grain, overall rendering style. " +
                        "Be SPECIFIC. No vague words like 'nice' or 'pretty'. 200-280 words. No preamble.",
                    },
                    { type: "image_url", image_url: { url: dataUrl, detail: "high" } },
                  ] as any,
                },
              ],
              max_tokens: 700,
            });
            return vision.choices[0]?.message?.content || `(reference ${idx + 1} - no analysis returned)`;
          } catch (e: any) {
            req.log?.warn?.({ err: e?.message, idx }, "avatar-prompt vision failed for one reference");
            return `(reference ${idx + 1} - vision analysis failed: ${e?.message || "unknown error"})`;
          }
        })
      );

      // Step 2 — synthesise the hyper-detailed JSON prompt.
      const systemPrompt = `You are an elite character / avatar prompt engineer for AI image generators (Higgsfield with nano-banana pro, MidJourney, Ideogram, DALL-E 3). You take 1-3 reference image analyses plus user direction and produce a SINGLE hyper-detailed JSON prompt the user can paste directly into their image generator to create a NEW avatar that takes inspiration from the references but does NOT identically copy any one of them.

HARD RULES:
- AUTO-DETECT all identity, styling, and vibe cues directly from the reference image analyses below. Pull gender, age range, ethnicity cues, hair, skin, eye, facial structure, clothing, and accessory details from what you see across the references and synthesise them into a single consistent NEW avatar.
- DO NOT copy or reproduce any specific real person from the references. The references are for STYLE, VIBE, COMPOSITION and TECHNICAL feel only. Generate a NEW original face that fits the directional cues.
- DO NOT mention or invent any real-world celebrity, copyrighted character, or trademarked brand name. Generic descriptors only (e.g. "ribbed knit crewneck sweater", not "Lululemon Define jacket").
- LOCK the output to: studio head-and-shoulders portrait, front-on (camera at eye level, subject facing camera), on a clean white seamless studio background, soft even frontal lighting, no props, no environmental detail. The composition.framing MUST be "head-and-shoulders studio portrait", composition.perspective MUST be "front-on, eye-level, subject facing camera", composition.aspect_ratio MUST be "1:1", environment.location MUST be "clean white seamless studio backdrop", environment.background_elements MUST be ["plain white seamless backdrop", "no props", "no furniture"], environment.lighting.type MUST be "studio softbox, soft even frontal lighting", environment.lighting.color_temperature MUST be "neutral daylight (5500K)".
- Be EXTREMELY specific. Every facial feature, skin texture cue, hair detail, and clothing fabric must be concrete enough that two different generators would produce visually consistent results.
- ALWAYS include a "consistency_id" string the user can re-use across generations to keep the same avatar (use a short kebab-case slug derived from a quick read of the look + a 3-digit number, e.g. "warm-blonde-editorial-001").
- Output ONLY valid JSON, no preamble, no trailing commentary, no code fences.

REQUIRED JSON SCHEMA (this exact shape):
{
  "avatarPrompt": {
    "subject": {
      "identity": {
        "gender": string,
        "age_range": string,
        "ethnicity_cues": string,
        "facial_features": {
          "hair": string,                  // length, colour with highlights/lowlights, texture, parting, styling
          "eyes": string,                  // colour, shape, eyelash, gaze
          "skin": {
            "texture": string,             // pores, freckles, makeup vs natural, blemishes
            "undertone": string            // warm/cool/neutral
          },
          "face_structure": string,        // face shape, jaw, cheekbones, lips, eyebrows
          "expression": string             // mouth state, smile, mouth open as if speaking, etc.
        },
        "attire": {
          "top": string,                   // garment + fabric + colour + collar/neckline
          "bottom": string,                // optional, "(not visible)" if framing crops it out
          "accessories": string            // earrings, necklaces, glasses, nails, phone in hand, etc.
        }
      }
    },
    "composition": {
      "framing": string,                   // selfie / MCU / head-and-shoulders / full-body etc.
      "perspective": string,               // first-person POV holding phone / third-person studio / etc.
      "details": string,                   // hand visible, prop in hand, posture, body angle
      "aspect_ratio": string               // "9:16" | "1:1" | "4:5" | "3:4" etc.
    },
    "environment": {
      "location": string,
      "background_elements": string[],     // 3-6 specific items
      "lighting": {
        "type": string,                    // natural sunlight / studio softbox / golden hour / etc.
        "properties": string,
        "color_temperature": string        // e.g. "warm daylight (5600K)"
      }
    },
    "technical_specifications": {
      "camera_profile": string,            // e.g. "iPhone 15 Pro front-facing camera aesthetics"
      "lens": string,                      // e.g. "wide-angle ~24mm" or "85mm portrait"
      "f_stop": string,                    // e.g. "f/1.8"
      "rendering": {
        "style": string,                   // photoreal / candid smartphone / cinematic / editorial
        "detail_level": string,            // "ultra-high, 4K resolution"
        "film_grain": string
      }
    },
    "negative_prompt": string[],           // 4-8 things to AVOID (warped hands, extra fingers, plastic skin, watermark, text artifacts, identical-to-reference)
    "consistency_id": string               // short kebab-case slug + 3-digit number, e.g. "suburban-vlogger-001"
  },
  "generatorHints": {
    "higgsfield": string,                  // 1-line natural-language prompt optimised for Higgsfield nano-banana pro
    "nanoBanana": string,                  // 1-line prompt optimised for Google nano-banana pro
    "midjourney": string,                  // 1-line prompt with --ar and --style cues
    "dalle": string                        // 1-line prompt for DALL-E 3
  }
}`;

      const userPrompt = `BRAND CONTEXT (for vibe alignment only - do NOT put any brand names into the avatar prompt):
${brandContext}

LOCKED OUTPUT: studio head-and-shoulders portrait, front-on, plain white seamless background, soft even frontal lighting, no props. Aspect ratio 1:1. Auto-detect every other identity and styling cue from the references below.

REFERENCE IMAGE ANALYSES (${referenceAnalyses.length} total - use these to auto-detect identity, styling, hair, skin, clothing, and overall vibe. Do NOT copy any one face exactly):
${referenceAnalyses.map((a, i) => `--- Reference ${i + 1} ---\n${a}`).join("\n\n")}

Now produce the single hyper-detailed JSON prompt described in the schema, with the locked studio head-and-shoulders / white-background composition. JSON only.`;

      const completion = await openai.chat.completions.create({
        model: "gpt-4o",
        messages: [
          { role: "system", content: systemPrompt },
          { role: "user", content: userPrompt },
        ],
        response_format: { type: "json_object" },
        temperature: 0.7,
        max_tokens: 3500,
      });

      const raw = completion.choices[0]?.message?.content || "{}";
      let parsed: any = {};
      try { parsed = JSON.parse(raw); } catch { parsed = {}; }

      res.json({
        ok: true,
        referenceAnalyses,
        ...parsed,
      });
      return;
    } catch (e: any) {
      req.log?.error?.({ err: e?.message, stack: e?.stack }, "avatar-prompt-generator error");
      res.status(500).json({ error: e?.message || "Failed to generate avatar prompt" });
      return;
    }
  }
);


// -----------------------------------------------------------------------------
// Instagram Bio Generator OS (Room30 - setting up social media accounts lesson)
// -----------------------------------------------------------------------------
// Pulls the user's brain (who they help, achievements, generated brain) PLUS
// their selected confirmed offer (low ticket / premium / 100k) and produces 5
// punchy 3-4 line Instagram / TikTok bio variations following the proven
// "what you do + proof + transformation + CTA" framework, modelled on the
// reference bios from the lesson.
portalRouter.post(
  "/portal/ig-bio-generator",
  requireAuth,
  async (req: any, res) => {
    try {
      const user = req.portalUser;
      const body = (req.body || {}) as {
        influencerId?: number | null;
        offerBrainId?: string | null;
        igHandle?: string;
        extraNotes?: string;
      };
      const influencerId =
        typeof body.influencerId === "number" && Number.isFinite(body.influencerId)
          ? body.influencerId
          : null;
      // offerBrainId: null/"own" => user's own saved brain (resolveEffectiveBrain
      // honours their brainMode). Any other string => load that prebuilt brain
      // directly so the bios sell THAT offer regardless of what's saved on
      // Your Brain.
      const rawOfferId = typeof body.offerBrainId === "string" ? body.offerBrainId.trim() : "";
      // Room30 has no curated-brain catalogue: never honour an offerBrainId
      // request from that portal so OS tools never sell an Apex Offer
      // through the Room30 portal, even if a stale client sends one.
      const offerBrainId = rawOfferId && rawOfferId !== "own" && getPortalKey(req) !== "room30" ? rawOfferId : null;
      const igHandle = (body.igHandle || "").trim().replace(/^@+/, "").slice(0, 60);
      const extraNotes = (body.extraNotes || "").trim().slice(0, 600);

      let brain: any = null;
      let selectedOffer: { id: string; name: string; tagline: string } | null = null;

      if (offerBrainId) {
        const prebuilt = getPrebuiltBrain(offerBrainId);
        // Same availability rules the UI enforces: hidden (isActive=false) or
        // coming-soon brains can't be used to generate. Belt-and-braces in
        // case a direct API call bypasses the picker.
        if (!prebuilt || prebuilt.isActive === false || prebuilt.comingSoon) {
          res.status(400).json({
            error: "That offer is no longer available. Pick another from the list.",
          }); return;
        }
        brain = {
          name: prebuilt.brainData.name,
          companyName: prebuilt.brainData.companyName,
          whoDoYouHelp: prebuilt.brainData.whoDoYouHelp,
          howDoYouHelpThem: prebuilt.brainData.howDoYouHelpThem,
          keyAchievements: prebuilt.brainData.keyAchievements,
          generatedBrain: prebuilt.generatedBrain,
          website: null,
        };
        selectedOffer = { id: prebuilt.id, name: prebuilt.name, tagline: prebuilt.tagline };
      } else {
        const [brainRow] = await db
          .select()
          .from(userBrainProfilesTable)
          .where(eq(userBrainProfilesTable.userId, user.id));
        brain = resolveEffectiveBrain(brainRow, getPortalKey(req));
        if (!brain) {
          res.status(400).json({
            error:
              "We couldn't find your Brain yet. Head to Your Brain, fill in who you help and your achievements, or pick one of our pre-built offers above.",
          }); return;
        }
      }

      const stripHtml = (s: string) =>
        (s || "").replace(/<[^>]+>/g, " ").replace(/\s+/g, " ").trim();

      // Optional: tie the bio to a specific AI influencer the user has saved.
      // The Brain itself already carries the offer/positioning (prebuilt
      // AI Influencer Portfolio brain when brainMode='prebuilt', or the user's
      // own brain when 'own'), so the influencer is just the public-facing
      // persona the bio is being written for.
      let influencerBlock = "(No specific AI influencer selected - write the bio for the owner's main brand.)";
      let influencerName = "";
      if (influencerId) {
        // ai_influencers.client_id references appUsers (clientsTable), NOT
        // portalUsers. requireAuth populates both req.appUser and
        // req.portalUser - use the appUser id here so the row actually
        // matches.
        const appUserId = req.appUser?.id as number | undefined;
        const [inf] = appUserId
          ? await db
              .select()
              .from(aiInfluencersTable)
              .where(
                and(
                  eq(aiInfluencersTable.id, influencerId),
                  eq(aiInfluencersTable.clientId, appUserId),
                ),
              )
          : [];
        if (inf) {
          influencerName = inf.name;
          influencerBlock = `SELECTED AI INFLUENCER (this bio belongs on THIS persona's profile):
Name: ${inf.name}
Niche: ${inf.niche || "(not set)"}`;
        }
      }

      const brainContext = `
Owner: ${brain?.name || "Not specified"}
Company / brand: ${brain?.companyName || "Not specified"}
Who they help: ${brain?.whoDoYouHelp || "Not specified"}
How they help them: ${brain?.howDoYouHelpThem || "Not specified"}
Key achievements / proof / specific numbers: ${brain?.keyAchievements || "Not specified"}
Website: ${brain?.website || "(none)"}
${igHandle ? `Instagram handle for this profile: @${igHandle}` : ""}
`.trim();

      const generatedBrainBlock = brain?.generatedBrain
        ? `FULL BRAIN (this is the canonical positioning, offer, mechanism, proof, audience and tone - every bio must sell THIS offer with THIS brain's voice and proof; never invent figures that aren't in here):\n${stripHtml(brain.generatedBrain).slice(0, 6000)}`
        : "(No full brain generated yet - fall back to the fields above.)";

      const offerHeaderBlock = selectedOffer
        ? `SELECTED OFFER (this bio is promoting THIS specific offer - every bio's CTA must point the reader at it):
Offer name: ${selectedOffer.name}
One-liner: ${selectedOffer.tagline}`
        : "SELECTED OFFER: the owner's own brand / brain (defined below).";

      const offerBlock = `${offerHeaderBlock}\n\n${influencerBlock}`;

      const systemPrompt = `You are an elite Instagram bio writer for direct-response coaches, course creators and online founders. You produce SHORT, scroll-stopping bios that follow proven 3-4 line frameworks like the reference patterns below.

REFERENCE PATTERNS (each is 3-4 short lines, no paragraphs, often ends with a downward arrow + soft CTA pointing at the link in bio):

Pattern A - "I help X do Y without Z":
  I help coaches grow & sell more without ads
  With content that attracts, connects and converts
  1000+ business owners helped
  ↓ Start selling more

Pattern B - "Founder story → transformation → handle":
  Built a business that nearly killed me. Rebuilt it by design,
  around my dream life. Now I help founders do the same.
  F*ck Fine | @theirhandle

Pattern C - "Big number proof stack + install CTA":
  I help experts sell $100K+ offers.
  I make $724K/mo with zero employees.
  Turn $27 buyers into $100K+ dream deals.
  ↓ Install my OS

Pattern D - "Resume credential → social proof → CTA":
  Co-founded Quest Nutrition ➡️ Sold for $1B ➡️ CEO @ Impact Theory | Posts Show You How I Did It ⬇️

Pattern E - "Bullet manifesto":
  • Breaking down new tech & AI
  • Helping business owners stay ahead in the AI era
  • Partnerships: email@domain.com
  • Building productname.ai 👇

HARD RULES:
- 3 to 4 short lines per bio. Each line must be punchy. No paragraphs.
- Pull EVERY claim, number and proof point from the BRAIN below. NEVER invent achievements, revenue figures, client counts, exits, or credentials. If the brain doesn't contain a number, do not put a number in.
- The Brain is the canonical offer/positioning. The CTA line on each bio must point the reader toward the brain's offer (use phrases like "↓ Get the system", "↓ Start here", "↓ See how it works", "↓ Build mine", or whatever fits the brain's product/mechanism). Never reference an offer the brain doesn't describe.
- If a specific AI Influencer is selected, the bio is for THAT persona's profile - keep the voice, niche and CTA consistent with their angle while still selling the brain's offer.
- Keep total character count under ~150 chars per line so it actually fits Instagram's bio field.
- Use a downward arrow (↓ or ⬇️ or 👇) on the CTA line where appropriate.
- Use Instagram-safe characters. No markdown asterisks, no headings, no preamble.
- Each of the 5 variations must use a DIFFERENT pattern (one A, one B, one C, one D, one E) so the user can pick their favourite framework.

OUTPUT JSON SHAPE (exactly):
{
  "bios": [
    {
      "pattern": "A" | "B" | "C" | "D" | "E",
      "patternName": string,
      "lines": string[],          // 3 or 4 strings, each one bio line
      "rationale": string         // 1 short sentence on why this fits the owner
    }
  ]
}

Return EXACTLY 5 bios, one per pattern, in order A,B,C,D,E. JSON only, no preamble, no code fences.`;

      const userPrompt = `OWNER'S BRAIN CONTEXT:
${brainContext}

${generatedBrainBlock}

${offerBlock}

${extraNotes ? `EXTRA DIRECTION FROM OWNER:\n${extraNotes}\n` : ""}
Now produce 5 Instagram bios in the JSON shape above. Each one must use real proof from the brain only - no invented numbers - and the CTA must sell the selected offer.`;

      const openai = new OpenAI({
        baseURL: process.env.AI_INTEGRATIONS_OPENAI_BASE_URL,
        apiKey: process.env.AI_INTEGRATIONS_OPENAI_API_KEY,
      });

      const scrubDashes = (s: string) =>
        (s || "").replace(/\u2014/g, " - ").replace(/\u2013/g, " - ");

      // Normalize the model output into the shape the page expects, dropping
      // empty lines and scrubbing em/en dashes per house style. Returns only
      // bios that actually have copy so the page never renders blank cards.
      const normalizeBios = (parsedVal: any): any[] => {
        const arr = Array.isArray(parsedVal?.bios) ? parsedVal.bios : [];
        return arr
          .map((b: any) => {
            const lines = Array.isArray(b?.lines)
              ? b.lines
                  .map((l: any) =>
                    typeof l === "string"
                      ? scrubDashes(l).replace(/\r?\n/g, " ").replace(/\s+/g, " ").trim()
                      : "",
                  )
                  .filter((l: string) => l.length > 0)
              : [];
            return {
              pattern: typeof b?.pattern === "string" ? b.pattern : "",
              patternName: typeof b?.patternName === "string" ? b.patternName.trim() : "",
              lines,
              rationale: typeof b?.rationale === "string" ? scrubDashes(b.rationale).trim() : "",
            };
          })
          .filter((b: any) => b.lines.length >= 2);
      };

      // Retry once if the first call returns nothing usable (empty content or
      // unparseable JSON) so a single flaky completion does not leave the page
      // spinning then showing nothing.
      let bios: any[] = [];
      for (let attempt = 0; attempt < 2 && bios.length === 0; attempt++) {
        const completion = await openai.chat.completions.create({
          model: "gpt-4o",
          messages: [
            { role: "system", content: systemPrompt },
            { role: "user", content: userPrompt },
          ],
          response_format: { type: "json_object" },
          temperature: 0.85,
          max_tokens: 1800,
        });

        const raw = completion.choices[0]?.message?.content || "{}";
        let parsed: any = {};
        try { parsed = JSON.parse(raw); } catch { parsed = {}; }
        bios = normalizeBios(parsed);
      }

      if (bios.length === 0) {
        res.status(500).json({
          error: "AI did not return usable bios. Please try again.",
        });
        return;
      }

      res.json({
        ok: true,
        influencerId,
        influencerName,
        offerBrainId: selectedOffer?.id ?? null,
        offerName: selectedOffer?.name ?? null,
        bios,
      });
      return;
    } catch (e: any) {
      req.log?.error?.({ err: e?.message, stack: e?.stack }, "ig-bio-generator error");
      res.status(500).json({ error: e?.message || "Failed to generate bios" });
      return;
    }
  }
);


// -----------------------------------------------------------------------------
// Domain Name Idea Generator (Room30 — bridge page lesson)
// -----------------------------------------------------------------------------
// Takes a short free-text description of the user's offer and returns 20 short,
// brandable domain ideas mixed across .com, .io, .co and .ai. Each idea also
// gets a fast availability check via DNS NS lookup. NS-not-found is a strong
// (but not guaranteed) signal that the domain is unregistered, so we surface
// it as "available" with a "confirm at registrar" caveat in the UI.

const DOMAIN_TLDS = [".com", ".io", ".co", ".ai"] as const;

async function checkDomainAvailability(
  domain: string,
): Promise<"available" | "taken" | "unknown"> {
  try {
    const dns = await import("node:dns/promises");
    // Per-lookup timeout so a slow resolver cannot stall the whole request.
    const withTimeout = <T>(p: Promise<T>, ms: number): Promise<T> =>
      Promise.race([
        p,
        new Promise<T>((_, reject) =>
          setTimeout(() => {
            const err: any = new Error("dns timeout");
            err.code = "ETIMEOUT";
            reject(err);
          }, ms),
        ),
      ]);

    try {
      const ns = await withTimeout(dns.resolveNs(domain), 4000);
      if (Array.isArray(ns) && ns.length > 0) return "taken";
    } catch (e: any) {
      const code = e?.code;
      // ENOTFOUND / NXDOMAIN / ENODATA: authoritative "no such name" =>
      // very likely unregistered.
      if (code === "ENOTFOUND" || code === "ENODATA" || code === "NXDOMAIN") {
        return "available";
      }
      // SERVFAIL, timeouts, network errors, DNSSEC failures => we cannot
      // tell. Surface as unknown so the user is nudged to confirm at a
      // registrar instead of getting a false "available" badge.
      return "unknown";
    }
    // Fall through: NS lookup returned but empty. Try a generic resolve to
    // confirm registration. Treat ambiguous failures as unknown, not
    // available, for the same reason as above.
    try {
      await withTimeout(dns.resolve(domain), 4000);
      return "taken";
    } catch (e: any) {
      const code = e?.code;
      if (code === "ENOTFOUND" || code === "ENODATA" || code === "NXDOMAIN") {
        return "available";
      }
      return "unknown";
    }
  } catch {
    return "unknown";
  }
}

async function checkAllDomains(
  domains: { domain: string; tld: string; rationale: string }[],
  deadline?: number,
): Promise<
  { domain: string; tld: string; rationale: string; availability: "available" | "taken" | "unknown" }[]
> {
  // Bounded concurrency so we do not hammer the local resolver.
  const out: {
    domain: string;
    tld: string;
    rationale: string;
    availability: "available" | "taken" | "unknown";
  }[] = new Array(domains.length);
  const concurrency = 12;
  let cursor = 0;
  async function worker() {
    while (true) {
      const idx = cursor++;
      if (idx >= domains.length) return;
      const d = domains[idx];
      // If we have blown the overall time budget, stop doing live lookups and
      // mark the rest "unknown" (the UI nudges the user to confirm at a
      // registrar anyway). This guarantees we return before the proxy 502s.
      if (deadline && Date.now() >= deadline) {
        out[idx] = { ...d, availability: "unknown" };
        continue;
      }
      const availability = await checkDomainAvailability(d.domain);
      out[idx] = { ...d, availability };
    }
  }
  await Promise.all(Array.from({ length: concurrency }, () => worker()));
  return out;
}

portalRouter.post(
  "/portal/domain-name-generator/generate",
  requireAuth,
  async (req: any, res) => {
    try {
      const offerRaw = String(req.body?.offer || "").trim();
      if (offerRaw.length < 3) {
        res.status(400).json({ error: "Please describe your offer in at least a few words." }); return;
      }
      const offer = offerRaw.slice(0, 600);

      // Overall time budget. The shared proxy kills any request that runs
      // longer than ~60s with a 502, which is exactly what left this tool
      // "stuck" for users (slow gpt-5 reasoning call + two DNS passes ran
      // past the limit). Keep the whole handler comfortably under that so we
      // always return a real response instead of a proxy timeout.
      const deadline = Date.now() + 45_000;
      const msLeft = () => deadline - Date.now();

      const openai = new OpenAI({
        baseURL: process.env.AI_INTEGRATIONS_OPENAI_BASE_URL,
        apiKey: process.env.AI_INTEGRATIONS_OPENAI_API_KEY,
        timeout: 30_000,
        // Single-shot: an SDK auto-retry would stack a second full timeout
        // window on top of the first and could push us past the proxy limit.
        maxRetries: 0,
      });

      const systemPrompt = `You are an elite brand naming strategist who specialises in short, brandable, memorable domain names for online businesses.

HARD RULES:
- Output EXACTLY 20 domain ideas. No more, no less.
- Mix across these TLDs only: .com, .io, .co, .ai. Aim for a roughly even spread (about 5 of each), but bias toward .com when a strong .com phrase exists.
- Domains must be short (ideally 4 to 14 characters before the TLD), easy to spell, easy to say out loud, and easy to remember.
- Lowercase only. No hyphens. No numbers unless the user's offer is literally about a number. No trademarked or famous brand names.
- Each domain must be ONE word OR two words concatenated. Never three or more words.
- Do not output explanations, preambles, or markdown. Output ONLY a valid JSON object matching the schema.
- Make the names feel modern, premium and brandable. Think Notion, Stripe, Linear, Vercel, Loom, Figma, Replit, Cursor.
- Avoid generic words like "hub", "spot", "zone", "world" unless they genuinely fit. Prefer invented words, evocative compounds, and clever twists.
- Never include any em dashes, en dashes, or asterisks anywhere in the output. Use plain text only.

OUTPUT JSON SCHEMA:
{
  "domains": [
    {
      "name": string,        // the bare name without the dot or TLD, e.g. "promptforge"
      "tld": ".com" | ".io" | ".co" | ".ai",
      "rationale": string    // 1 short sentence (max 14 words) on why this name fits the offer. No dashes, no asterisks.
    }
    // ... exactly 20 entries
  ]
}`;

      const userPrompt = `OFFER DESCRIPTION:
${offer}

Generate 20 domain name ideas that fit this offer. Follow every rule. Return JSON only.`;

      // Helper: call the model once and return cleaned, de-duped entries.
      // gpt-4o-mini responds in a few seconds for this structured task and is
      // NOT a reasoning model, so it does not burn the token budget on a hidden
      // reasoning pass (the gpt-5 / gpt-5-mini reasoning pass was the cause of
      // both the proxy timeouts and the empty-output failures). Cap each call
      // with a per-request timeout so a slow upstream cannot stall us.
      const callModel = async (extraInstruction: string) => {
        // Hard stop: never start a model call we cannot finish inside the
        // budget. Prevents a late top-up from running past the proxy limit.
        if (msLeft() < 9_000) {
          throw new Error("insufficient time budget for model call");
        }
        const callTimeout = Math.max(8_000, Math.min(28_000, msLeft() - 6_000));
        const completion = await openai.chat.completions.create(
          {
            model: "gpt-4o-mini",
            messages: [
              { role: "system", content: systemPrompt },
              { role: "user", content: extraInstruction ? `${userPrompt}\n\n${extraInstruction}` : userPrompt },
            ],
            response_format: { type: "json_object" },
            temperature: 0.85,
            max_tokens: 2200,
          },
          { timeout: callTimeout },
        );
        const raw = completion.choices[0]?.message?.content || "{}";
        let parsed: any = {};
        try { parsed = JSON.parse(raw); } catch { parsed = {}; }
        const list: any[] = Array.isArray(parsed?.domains) ? parsed.domains : [];
        const out: { domain: string; tld: string; rationale: string }[] = [];
        for (const item of list) {
          const rawName = String(item?.name || "").toLowerCase().replace(/[^a-z0-9]/g, "");
          let tld = String(item?.tld || ".com").toLowerCase();
          if (!DOMAIN_TLDS.includes(tld as any)) tld = ".com";
          if (!rawName || rawName.length < 2 || rawName.length > 24) continue;
          const fullDomain = `${rawName}${tld}`;
          const rationale = String(item?.rationale || "")
            .replace(/[\u2013\u2014]/g, "-")
            .replace(/\*/g, "")
            .slice(0, 200)
            .trim();
          out.push({ domain: fullDomain, tld, rationale });
        }
        return out;
      };

      // Normalise + de-duplicate across (potentially multiple) calls so we
      // always end up with exactly 20 unique ideas. The model occasionally
      // returns dupes or invalid entries; a short top-up call covers the gap.
      const seen = new Set<string>();
      const cleaned: { domain: string; tld: string; rationale: string }[] = [];
      const ingest = (items: { domain: string; tld: string; rationale: string }[]) => {
        for (const item of items) {
          if (seen.has(item.domain)) continue;
          seen.add(item.domain);
          cleaned.push(item);
          if (cleaned.length >= 20) break;
        }
      };

      try {
        ingest(await callModel(""));
      } catch (e: any) {
        req.log?.warn?.({ err: e?.message }, "domain-name-generator primary model call failed");
      }

      if (cleaned.length === 0) {
        res.status(503).json({ error: "Our name generator is busy right now. Please try again in a moment." });
        return;
      }

      // Only spend a second round-trip topping up to 20 if we still have a
      // healthy chunk of the time budget left - otherwise ship what we have.
      if (cleaned.length < 20 && msLeft() > 22_000) {
        const need = 20 - cleaned.length;
        try {
          const topUp = await callModel(
            `IMPORTANT: We already have ${cleaned.length} usable ideas but still need ${need} MORE unique domains to hit 20. Generate ${need} fresh, distinctly different ideas. Avoid these already-taken slots: ${[...seen].join(", ")}. Still return the full JSON object with a "domains" array (you can return up to 20 entries; we will only take the first ${need} new ones).`,
          );
          ingest(topUp);
        } catch {
          // top-up failed; fall through with whatever we have
        }
      }

      const withAvailability = await checkAllDomains(cleaned, deadline);

      // Second pass: for any stem whose .com or .co is NOT confirmed
      // available, try prefixed .com alternatives (try/get/learn) so the
      // user can still grab a .com when the bare name is gone.
      const PREFIXES = ["try", "get", "learn"] as const;
      const stripTld = (d: string) =>
        d.replace(/\.(com|io|co|ai)$/i, "");

      // Build per-stem index of which TLDs already came back as available.
      const stemHasAvailableComCo = new Map<string, boolean>();
      const stemRationale = new Map<string, string>();
      for (const r of withAvailability) {
        const stem = stripTld(r.domain);
        if (!stemRationale.has(stem) && r.rationale) {
          stemRationale.set(stem, r.rationale);
        }
        if (
          (r.tld === ".com" || r.tld === ".co") &&
          r.availability === "available"
        ) {
          stemHasAvailableComCo.set(stem, true);
        }
      }

      // Candidate stems: every unique stem that does NOT already have an
      // available .com or .co. Skip stems that already start with one of
      // our prefixes so we never produce e.g. "trytrybrand.com".
      const candidateStems: string[] = [];
      const seenStem = new Set<string>();
      for (const r of withAvailability) {
        const stem = stripTld(r.domain);
        if (seenStem.has(stem)) continue;
        seenStem.add(stem);
        if (stemHasAvailableComCo.get(stem)) continue;
        if (PREFIXES.some((p) => stem.startsWith(p))) continue;
        candidateStems.push(stem);
      }
      // Cap so the prefixed pass stays fast (max 6 stems × 3 prefixes = 18 lookups).
      const stemsToTry = candidateStems.slice(0, 6);

      const prefixedCandidates: {
        domain: string;
        tld: string;
        rationale: string;
        basedOn: string;
        prefix: string;
      }[] = [];
      // The prefixed pass is a bonus, not essential. Only build + run it when
      // we still have enough of the time budget to finish another DNS sweep
      // without risking the proxy timeout; otherwise ship the main list.
      if (msLeft() > 12_000) {
        for (const stem of stemsToTry) {
          for (const prefix of PREFIXES) {
            const fullName = `${prefix}${stem}`;
            if (fullName.length > 28) continue;
            const baseRationale = stemRationale.get(stem) || "";
            prefixedCandidates.push({
              domain: `${fullName}.com`,
              tld: ".com",
              rationale: baseRationale
                ? `Prefixed .com option built on ${stem}. ${baseRationale}`
                : `Prefixed .com option built on ${stem}.`,
              basedOn: stem,
              prefix,
            });
          }
        }
      }

      const prefixedChecked = prefixedCandidates.length
        ? await checkAllDomains(prefixedCandidates, deadline)
        : [];
      // Keep only available ones so the section is high signal. If nothing
      // shakes loose we just omit the section.
      const prefixedAvailable = prefixedChecked
        .map((r, i) => ({
          ...r,
          basedOn: prefixedCandidates[i]!.basedOn,
          prefix: prefixedCandidates[i]!.prefix,
        }))
        .filter((r) => r.availability === "available");

      // Hide taken results from the main list. Taken stems still drive the
      // prefixed alternatives pass above, so the user gets a usable .com
      // option for the same idea instead of a noisy "TAKEN" card.
      const visibleDomains = withAvailability.filter(
        (r) => r.availability !== "taken",
      );

      const note = "Availability is a fast DNS check, so it is a strong signal but not a guarantee. Always confirm at a registrar before you buy.";
      res.json({
        ok: true,
        domains: visibleDomains,
        prefixedAlternatives: prefixedAvailable,
        note,
      });
      void saveToolGeneration({
        portalUserId: req.portalUser.id,
        toolSlug: "domain-name-generator",
        label: offer.slice(0, 120),
        input: { offer },
        output: { domains: visibleDomains, prefixedAlternatives: prefixedAvailable, note },
      });
      return;
    } catch (e: any) {
      req.log?.error?.({ err: e?.message }, "domain-name-generator error");
      res.status(500).json({ error: e?.message || "Failed to generate domain ideas" });
      return;
    }
  },
);

// On startup, requeue any jobs that were left mid-flight (server restart safety)
setImmediate(async () => {
  try {
    const stuck = await db.select().from(osToolSaveJobsTable)
      .where(sql`${osToolSaveJobsTable.status} IN ('pending', 'saving_asset', 'generating_secondary')`);
    for (const j of stuck) {
      runOsToolSaveJob(j.id).catch((e) => console.error("requeue job runner error:", e));
    }
  } catch (e) {
    console.error("Failed to requeue OS tool save jobs:", e);
  }
  try {
    const stuck = await db.select().from(osToolGenerationJobsTable)
      .where(sql`${osToolGenerationJobsTable.status} IN ('pending', 'processing')`);
    for (const j of stuck) {
      runOsToolGenerationJob(j.id).catch((e) => console.error("requeue gen runner error:", e));
    }
  } catch (e) {
    console.error("Failed to requeue OS tool generation jobs:", e);
  }
});

// ─────────────────────────────────────────────────────────────────────────────
// Live workshops (monthly 2-hour live calls with Greg).
// All authenticated users see the schedule; only admins manage the calendar.
// ─────────────────────────────────────────────────────────────────────────────

portalRouter.get("/portal/workshops", requireAuth, async (_req: any, res) => {
  try {
    const rows = await db
      .select()
      .from(liveWorkshopsTable)
      .orderBy(asc(liveWorkshopsTable.startsAt));
    res.json({ workshops: rows });
    return;
  } catch (err) {
    console.error("Failed to list workshops:", err);
    res.status(500).json({ error: "Failed to list workshops" });
    return;
  }
});

function validateMeetingUrl(raw: unknown): string | null {
  if (typeof raw !== "string") return null;
  const trimmed = raw.trim();
  if (!trimmed) return null;
  try {
    const u = new URL(trimmed);
    if (u.protocol !== "http:" && u.protocol !== "https:") return null;
    if (!u.hostname || !u.hostname.includes(".")) return null;
    return u.toString();
  } catch {
    return null;
  }
}

function validateDurationMinutes(raw: unknown): { ok: true; value: number } | { ok: false } {
  const n = Number(raw);
  if (!Number.isFinite(n) || !Number.isInteger(n)) return { ok: false };
  if (n < 15 || n > 600) return { ok: false };
  return { ok: true, value: n };
}

portalRouter.post("/portal/workshops", requireAuth, requireAdmin, async (req: any, res) => {
  try {
    const { title, description, startsAt, durationMinutes, meetingUrl, recordingUrl } = req.body ?? {};
    if (!title || typeof title !== "string" || !title.trim()) {
      res.status(400).json({ error: "title is required" }); return;
    }
    if (!startsAt) {
      res.status(400).json({ error: "startsAt is required" }); return;
    }
    const startsAtDate = new Date(startsAt);
    if (Number.isNaN(startsAtDate.getTime())) {
      res.status(400).json({ error: "startsAt is not a valid date" }); return;
    }
    const validUrl = validateMeetingUrl(meetingUrl);
    if (!validUrl) {
      res.status(400).json({ error: "meetingUrl must be a valid http(s) URL" }); return;
    }
    let duration = 120;
    if (durationMinutes != null) {
      const dv = validateDurationMinutes(durationMinutes);
      if (!dv.ok) {
        res.status(400).json({ error: "durationMinutes must be an integer between 15 and 600" }); return;
      }
      duration = dv.value;
    }
    let recording: string | null = null;
    if (recordingUrl !== undefined && recordingUrl !== null && recordingUrl !== "") {
      const validRec = validateMeetingUrl(recordingUrl);
      if (!validRec) {
        res.status(400).json({ error: "recordingUrl must be a valid http(s) URL" }); return;
      }
      recording = validRec;
    }
    const [row] = await db
      .insert(liveWorkshopsTable)
      .values({
        title: title.trim(),
        description: typeof description === "string" ? description.trim() : null,
        startsAt: startsAtDate,
        durationMinutes: duration,
        meetingUrl: meetingUrl.trim(),
        recordingUrl: recording,
        createdBy: (req as any).portalUser?.email || null,
      })
      .returning();
    res.json({ workshop: row });
    return;
  } catch (err) {
    console.error("Failed to create workshop:", err);
    res.status(500).json({ error: "Failed to create workshop" });
    return;
  }
});

portalRouter.patch("/portal/workshops/:id", requireAuth, requireAdmin, async (req: any, res) => {
  try {
    const id = Number(req.params.id);
    if (!Number.isFinite(id)) { res.status(400).json({ error: "Invalid id" }); return; }
    const { title, description, startsAt, durationMinutes, meetingUrl, recordingUrl } = req.body ?? {};
    const update: Record<string, any> = { updatedAt: new Date() };
    if (title !== undefined) {
      if (typeof title !== "string" || !title.trim()) {
        res.status(400).json({ error: "title must be a non-empty string" }); return;
      }
      update.title = title.trim();
    }
    if (description !== undefined) {
      if (description !== null && typeof description !== "string") {
        res.status(400).json({ error: "description must be a string or null" }); return;
      }
      update.description = typeof description === "string" ? description.trim() || null : null;
    }
    if (startsAt !== undefined) {
      const d = new Date(startsAt);
      if (Number.isNaN(d.getTime())) { res.status(400).json({ error: "startsAt is not a valid date" }); return; }
      update.startsAt = d;
    }
    if (durationMinutes !== undefined) {
      const dv = validateDurationMinutes(durationMinutes);
      if (!dv.ok) {
        res.status(400).json({ error: "durationMinutes must be an integer between 15 and 600" }); return;
      }
      update.durationMinutes = dv.value;
    }
    if (meetingUrl !== undefined) {
      const validUrl = validateMeetingUrl(meetingUrl);
      if (!validUrl) {
        res.status(400).json({ error: "meetingUrl must be a valid http(s) URL" }); return;
      }
      update.meetingUrl = validUrl;
    }
    if (recordingUrl !== undefined) {
      if (recordingUrl === null || recordingUrl === "") {
        update.recordingUrl = null;
      } else {
        const validRec = validateMeetingUrl(recordingUrl);
        if (!validRec) {
          res.status(400).json({ error: "recordingUrl must be a valid http(s) URL" }); return;
        }
        update.recordingUrl = validRec;
      }
    }
    const [row] = await db
      .update(liveWorkshopsTable)
      .set(update)
      .where(eq(liveWorkshopsTable.id, id))
      .returning();
    if (!row) { res.status(404).json({ error: "Workshop not found" }); return; }
    res.json({ workshop: row });
    return;
  } catch (err) {
    console.error("Failed to update workshop:", err);
    res.status(500).json({ error: "Failed to update workshop" });
    return;
  }
});

portalRouter.delete("/portal/workshops/:id", requireAuth, requireAdmin, async (req: any, res) => {
  try {
    const id = Number(req.params.id);
    if (!Number.isFinite(id)) { res.status(400).json({ error: "Invalid id" }); return; }
    await db.delete(liveWorkshopsTable).where(eq(liveWorkshopsTable.id, id));
    res.json({ ok: true });
    return;
  } catch (err) {
    console.error("Failed to delete workshop:", err);
    res.status(500).json({ error: "Failed to delete workshop" });
    return;
  }
});

// ---------- Daily Ad Research Board ----------
// Mirrors a public Google Sheet (#ID, link, Greg's notes) on a 24h cadence.
// Access gated to admins or users with bump2Paid (the Daily Ad Research Board add-on).

// Classify a thrown error from the board /items handlers into a small,
// stable set of codes the frontend can render. Keeps the error envelope
// machine-readable without surfacing raw stack traces.
//   schema_drift    : missing column / undefined column in catalog
//   db_unavailable  : connection refused / pool errors
//   query_failed    : any other SQL/db error
//   unknown         : everything else
function classifyBoardError(err: any): "schema_drift" | "db_unavailable" | "query_failed" | "unknown" {
  const msg = String(err?.message || err || "").toLowerCase();
  const code = String(err?.code || "").toUpperCase();
  if (
    msg.includes("does not exist") ||
    msg.includes("undefined column") ||
    msg.includes("undefined table") ||
    code === "42703" || // undefined_column
    code === "42P01"    // undefined_table
  ) {
    return "schema_drift";
  }
  if (
    msg.includes("econnrefused") ||
    msg.includes("connection terminated") ||
    msg.includes("connection ended") ||
    msg.includes("timeout") ||
    code === "ECONNREFUSED" ||
    code === "ENOTFOUND"
  ) {
    return "db_unavailable";
  }
  if (err?.name === "DrizzleQueryError" || msg.includes("failed query") || code.startsWith("42") || code.startsWith("22")) {
    return "query_failed";
  }
  return "unknown";
}

// GET /portal/ad-research-board/items
//
// Server-side paginated and filtered. With ~250 active rows on the board (and
// growing), shipping the entire collection over the wire on every page-paint
// stalled first paint for several seconds and pegged the React grid layout
// engine. We now return only the requested page (default 12) plus the counts
// and facet values the UI needs to render filter chips and the
// "Retry Failed (N)" badge accurately.
//
// Query params:
//   page          1-indexed page number (default 1)
//   pageSize      page size, clamped to [1, 60] (default 12)
//   search        substring match across rowKey, adLink, notes, type, etc.
//   type          repeatable; OR semantics (?type=Hook&type=Story)
//   awarenessStage  repeatable; OR semantics
//   style         repeatable; OR semantics
//   mediaOnly     "1" to require mediaStatus = ok
//   sort          "default" (sortIndex asc) or "newest" (createdAt desc)
//   view          admin only: "needsFixing" → only failed (non-dismissed) rows
//
// Response shape: { items, page, pageSize, total, counts, facets, lastSyncedAt, lastSyncOk, lastSyncError }
portalRouter.get("/portal/ad-research-board/items", requireAuth, async (req: any, res) => {
  try {
    const user = req.portalUser;
    if (!user) { res.status(401).json({ error: "Unauthorized" }); return; }
    const isAdmin = user.role === "admin";
    const entitlements = await computePurchaseEntitlements(user);
    if (!isAdmin && !entitlements.bump2Paid) {
      res.status(403).json({ error: "Ad Research Board not unlocked" }); return;
    }

    // Query parsing — be permissive (drop bad values silently) so a stale
    // bookmark with a junk param never breaks the user's board.
    const q = req.query as Record<string, unknown>;
    const toArray = (v: unknown): string[] => {
      if (Array.isArray(v)) return v.map((x) => String(x).trim()).filter(Boolean);
      if (typeof v === "string" && v.length) return [v.trim()].filter(Boolean);
      return [];
    };
    const pageRaw = Number(q.page);
    const page = Number.isFinite(pageRaw) && pageRaw > 0 ? Math.floor(pageRaw) : 1;
    const pageSizeRaw = Number(q.pageSize);
    const pageSize = Number.isFinite(pageSizeRaw)
      ? Math.max(1, Math.min(60, Math.floor(pageSizeRaw)))
      : 12;
    const search = typeof q.search === "string" ? q.search.trim() : "";
    const typeFilter = toArray(q.type);
    const awarenessFilter = toArray(q.awarenessStage);
    const styleFilter = toArray(q.style);
    const mediaOnly = q.mediaOnly === "1" || q.mediaOnly === "true";
    const sort = q.sort === "newest" ? "newest" : "default";
    const view = isAdmin && q.view === "needsFixing" ? "needsFixing" : "default";

    // Visibility rules:
    //  - Dismissed rows are always hidden (user view, admin board, AND the
    //    "Needs Fixing" admin view — they're permanently triaged-out).
    //  - Non-admins additionally never see failed rows.
    //  - Admin "Needs Fixing" view: only failed (non-dismissed) rows.
    //  - Admin default view: matches non-admin (no failed) so what admins
    //    see matches what users see; flip to "Needs Fixing" to triage.
    //  - Task #134: rows hidden from the sheet (hidden_from_sheet=true) are
    //    excluded from the user view but still visible to admins in the
    //    "Needs Fixing" view so they can decide whether to unhide them.
    const visibilityClauses: any[] = [eq(adResearchBoardItems.dismissed, false)];
    if (view === "needsFixing") {
      // Admin-only triage view: failed/partial rows OR rows that fell out
      // of the sheet but still have cached media we don't want to lose.
      // Task #401: needsFixing now includes ONLY retryable failures
      // (`failed`) plus partials and rows orphaned from the sheet.
      // Terminal `failed_permanent` rows are excluded - they've already
      // exhausted retries and are dismissed=true above, so they
      // shouldn't appear in the admin triage queue either. This makes
      // the badge `Needs Fixing (N)` match exactly what the filter
      // returns.
      // Task #402: Needs Fixing is operational-only. A row appears here
      // when the MEDIA needs attention - failed extraction, partial
      // carousel, invalid metadata, or "claims ok but no GCS object".
      // Rows that simply fell out of the source sheet (source_present=
      // false) but still have durable cached media do NOT appear here
      // - they're part of the permanent library. An admin who explicitly
      // archives a row (library_visibility='archived') also stops seeing
      // it in this triage view.
      visibilityClauses.push(eq(adResearchBoardItems.libraryVisibility, "visible"));
      visibilityClauses.push(
        or(
          eq(adResearchBoardItems.mediaStatus, "failed"),
          eq(adResearchBoardItems.mediaStatus, "partial"),
          eq(adResearchBoardItems.mediaStatus, "invalid"),
          and(
            inArray(adResearchBoardItems.mediaStatus, ["ok", "partial"]),
            isNull(adResearchBoardItems.mediaObjectPath),
          ),
        )!,
      );
    } else {
      // Task #134: user/default view shows ONLY rows with usable media —
      // ok (full result) or partial (some slides captured). Pending /
      // downloading / failed / null all hide. This guarantees users never
      // see a half-rendered card or an in-flight queue row.
      // Also require an actual media file on disk (mediaObjectPath IS NOT
      // NULL): rows can land in "ok" with a null object path when the
      // download succeeded the metadata check but the file write was lost
      // (storage hiccup, worker crash, manual cleanup, etc). Those rows
      // render as "Preview unavailable" tiles which look broken to users.
      // Admins still see them in the "Needs Fixing" view above so they
      // can re-queue them with Process Media / Fix Carousels.
      // Task #402: durable-media-library default view. library_visibility
      // is the canonical user-board gate. Rows that fell out of the
      // source sheet but still have durable cached media stay 'visible'
      // here - they're part of the permanent research inventory.
      visibilityClauses.push(eq(adResearchBoardItems.libraryVisibility, "visible"));
      // T370: `silent-source` rows are surfaced to users with a "no
      // audio in source" badge - the ad is genuinely silent, not
      // broken, so hiding it would make a perfectly good visual asset
      // disappear from the board. Visibility for silent-source does NOT
      // require a cached object path (the gate may have rejected every
      // rendition before any file was uploaded); the UI renders the
      // amber badge in that case so the row is still useful as a
      // labelled "silent ad" entry rather than vanishing.
      visibilityClauses.push(
        or(
          and(
            inArray(adResearchBoardItems.mediaStatus, ["ok", "partial"]),
            isNotNull(adResearchBoardItems.mediaObjectPath),
          ),
          eq(adResearchBoardItems.mediaStatus, "silent-source"),
        )!,
      );
    }
    const visibilityWhere = and(...visibilityClauses);

    // User-driven filter clauses applied on top of visibility.
    const filterClauses: any[] = [];
    if (typeFilter.length) filterClauses.push(inArray(adResearchBoardItems.type, typeFilter));
    if (awarenessFilter.length)
      filterClauses.push(inArray(adResearchBoardItems.awarenessStage, awarenessFilter));
    if (styleFilter.length) filterClauses.push(inArray(adResearchBoardItems.style, styleFilter));
    if (mediaOnly) filterClauses.push(eq(adResearchBoardItems.mediaStatus, "ok"));
    if (search) {
      const like = `%${search.replace(/[%_\\]/g, (c) => `\\${c}`)}%`;
      filterClauses.push(
        or(
          ilike(adResearchBoardItems.rowKey, like),
          ilike(adResearchBoardItems.adLink, like),
          ilike(adResearchBoardItems.notes, like),
          ilike(adResearchBoardItems.type, like),
          ilike(adResearchBoardItems.awarenessStage, like),
          ilike(adResearchBoardItems.style, like),
          // Match failure-class columns so chip-click filters work.
          ilike(adResearchBoardItems.mediaErrorClass, like),
          ilike(adResearchBoardItems.mediaError, like),
        ),
      );
    }
    const whereExpr = filterClauses.length
      ? and(visibilityWhere, ...filterClauses)
      : visibilityWhere;

    // Task #366: pagination `total` MUST stay aligned with the page query's
    // population (same WHERE clause the rows are drawn from). Otherwise
    // pagination breaks - the room30 infinite-scroll uses `loaded < total`
    // as the "has more" signal, and the course portal uses ceil(total /
    // pageSize) for page count, so a `total` larger than the actual
    // page-query population would either spin forever or render empty
    // pages. The header "X of Y ready" semantics (full inventory) are
    // served by separate `inventoryTotal` and `ready` fields below.
    const totalWhereExpr = whereExpr;

    // Always include `id` as a stable tiebreaker so OFFSET pagination
    // never returns the same row on two pages (sortIndex can repeat across
    // sheet rows; createdAt rounds to the same second on bulk inserts).
    // Without this tiebreaker users see duplicate cards as they scroll.
    const orderExprs =
      sort === "newest"
        ? [desc(adResearchBoardItems.createdAt), desc(adResearchBoardItems.id)]
        : [asc(adResearchBoardItems.sortIndex), asc(adResearchBoardItems.id)];

    // Run page query, total count, status-bucket counts, facets, and the
    // dismissed/hidden count queries in parallel — these are all
    // independent reads and the DB pool is sized for it. With proper
    // indexes (sortIndex, mediaStatus, dismissed) they're sub-100ms even
    // with thousands of rows. Previously the dismissed/hidden counts ran
    // in a second sequential Promise.all after this one resolved, which
    // added an unnecessary round-trip to every page load.
    // Task #512: only `pageRows` + `totalCountResult` are critical for
    // rendering the grid. Facets, status, buckets, and the latest sync
    // session each get their own `.catch()` so that a single failed
    // secondary query (e.g. a stale `sync_sessions` schema, a
    // long-running aggregation) returns a safe default and the user
    // still sees a usable, partially-populated board instead of a
    // page-level 500. Each fallback failure is logged so ops can see
    // which sub-query degraded.
    const logSubFailure = (sub: string) => (err: unknown) => {
      req.log?.warn?.(
        { err, route: "ad-research-board/items", sub, code: classifyBoardError(err) },
        "ad-research-board sub-query failed; using fallback",
      );
      return null;
    };
    const [
      pageRows,
      totalCountResult,
      facetsResult,
      status,
      bucketsResult,
      latestSyncSessionResult,
    ] = await Promise.all([
        db
          .select({
            id: adResearchBoardItems.id,
            rowKey: adResearchBoardItems.rowKey,
            sortIndex: adResearchBoardItems.sortIndex,
            adLink: adResearchBoardItems.adLink,
            type: adResearchBoardItems.type,
            awarenessStage: adResearchBoardItems.awarenessStage,
            style: adResearchBoardItems.style,
            notes: adResearchBoardItems.notes,
            mediaKind: adResearchBoardItems.mediaKind,
            mediaObjectPath: adResearchBoardItems.mediaObjectPath,
            mediaContentType: adResearchBoardItems.mediaContentType,
            mediaItems: adResearchBoardItems.mediaItems,
            // Task #186: cached video poster columns. Surfaced so the Ads
            // grid can render <img> over a video card instead of a black
            // <video preload="none"> tile.
            mediaThumbnailObjectPath: adResearchBoardItems.mediaThumbnailObjectPath,
            mediaThumbnailContentType: adResearchBoardItems.mediaThumbnailContentType,
            mediaThumbnailSource: adResearchBoardItems.mediaThumbnailSource,
            mediaThumbnailSourceUrl: adResearchBoardItems.mediaThumbnailSourceUrl,
            mediaStatus: adResearchBoardItems.mediaStatus,
            mediaError: adResearchBoardItems.mediaError,
            mediaMeta: adResearchBoardItems.mediaMeta,
            mediaAttempts: adResearchBoardItems.mediaAttempts,
            dismissed: adResearchBoardItems.dismissed,
            hiddenFromSheet: adResearchBoardItems.hiddenFromSheet,
            urlKind: adResearchBoardItems.urlKind,
            resolvedUrl: adResearchBoardItems.resolvedUrl,
            updatedAt: adResearchBoardItems.updatedAt,
            createdAt: adResearchBoardItems.createdAt,
          })
          .from(adResearchBoardItems)
          .where(whereExpr)
          .orderBy(...orderExprs)
          .limit(pageSize)
          .offset((page - 1) * pageSize),
        db.select({ n: count() }).from(adResearchBoardItems).where(totalWhereExpr),
        // Facets enumerate the distinct dropdown values across the same
        // visibility-filtered population (so admins see every value the
        // board actually uses; users don't see facet values that only
        // exist on hidden failed rows).
        db
          .selectDistinct({
            type: adResearchBoardItems.type,
            awarenessStage: adResearchBoardItems.awarenessStage,
            style: adResearchBoardItems.style,
          })
          .from(adResearchBoardItems)
          .where(visibilityWhere)
          .catch(logSubFailure("facets")),
        getAdResearchBoardSyncStatus().catch(logSubFailure("syncStatus")),
        // Task #366: DISJOINT breakdown buckets. Every row in
        // ad_research_board_items must fall into exactly one of these
        // buckets so the popover sums to inventoryTotal exactly.
        // Partition order (top-down):
        //   1. dismissed=true                        -> dismissed
        //   2. hiddenFromSheet=true                  -> hidden
        //   3. status in (ok,partial) AND objectPath -> ready
        //   4. status in (ok,partial) AND no path    -> missingObjectPath
        //   5. status = failed                       -> failed
        //   6. status = invalid                      -> invalid
        //   7. status = downloading                  -> downloading
        //   8. status pending OR null                -> pending
        db
          .select({
            dismissed: sql<number>`COUNT(*) FILTER (WHERE ${adResearchBoardItems.dismissed} = true)`,
            hidden: sql<number>`COUNT(*) FILTER (WHERE ${adResearchBoardItems.dismissed} = false AND ${adResearchBoardItems.hiddenFromSheet} = true)`,
            ready: sql<number>`COUNT(*) FILTER (WHERE ${adResearchBoardItems.dismissed} = false AND ${adResearchBoardItems.hiddenFromSheet} = false AND ${adResearchBoardItems.mediaStatus} IN ('ok','partial') AND ${adResearchBoardItems.mediaObjectPath} IS NOT NULL)`,
            missingObjectPath: sql<number>`COUNT(*) FILTER (WHERE ${adResearchBoardItems.dismissed} = false AND ${adResearchBoardItems.hiddenFromSheet} = false AND ${adResearchBoardItems.mediaStatus} IN ('ok','partial') AND ${adResearchBoardItems.mediaObjectPath} IS NULL)`,
            failed: sql<number>`COUNT(*) FILTER (WHERE ${adResearchBoardItems.dismissed} = false AND ${adResearchBoardItems.hiddenFromSheet} = false AND ${adResearchBoardItems.mediaStatus} = 'failed')`,
            // Task #401: dedicated "Needs Fixing" count that mirrors the
            // needsFixing visibility filter above exactly:
            //   dismissed=false AND (status='failed' OR status='partial'
            //                        OR hiddenFromSheet=true)
            // Frontend renders `Needs Fixing (N)` from this so the badge
            // can never drift from the row count the filter produces.
            // Terminal `failed_permanent` rows are dismissed and so are
            // intentionally NOT counted here - they're triaged-out and
            // belong on a separate "Terminal Failures" panel.
            // Task #402: needsFixing now mirrors the operational-only
            // filter above exactly. Source-removed rows with durable
            // media are NOT counted (they're part of the permanent
            // library). Includes: failed extraction, partial carousel,
            // invalid metadata, and "ok/partial but no GCS object".
            needsFixing: sql<number>`COUNT(*) FILTER (WHERE ${adResearchBoardItems.libraryVisibility} = 'visible' AND (${adResearchBoardItems.mediaStatus} = 'failed' OR ${adResearchBoardItems.mediaStatus} = 'partial' OR ${adResearchBoardItems.mediaStatus} = 'invalid' OR (${adResearchBoardItems.mediaStatus} IN ('ok','partial') AND ${adResearchBoardItems.mediaObjectPath} IS NULL)))`,
            // Task #401: terminal-exhaustion bucket. Always dismissed,
            // so it folds into the `dismissed` bucket above for the
            // invariant sum, but operators want to see it independently
            // ("how much of our dismissed pile is genuinely dead?").
            failedPermanent: sql<number>`COUNT(*) FILTER (WHERE ${adResearchBoardItems.mediaStatus} = 'failed_permanent')`,
            invalid: sql<number>`COUNT(*) FILTER (WHERE ${adResearchBoardItems.dismissed} = false AND ${adResearchBoardItems.hiddenFromSheet} = false AND ${adResearchBoardItems.mediaStatus} = 'invalid')`,
            // T370: telemetry bucket for ads whose source video has no
            // audio on either extractor. Counts every row at terminal
            // mediaStatus='silent-source' regardless of dismissed flag,
            // so legacy rows that were auto-dismissed by an earlier
            // implementation still show up in the admin total.
            silentSource: sql<number>`COUNT(*) FILTER (WHERE ${adResearchBoardItems.mediaStatus} = 'silent-source')`,
            // T370: count of rows currently in the no-audio-track retry
            // ladder - i.e. last error was no-audio-track but retries
            // are still pending (recoveryClass != 'silent-source', not
            // dismissed). Distinct from the terminal silentSource count
            // so the admin can see the in-flight backfill population
            // separately from the confirmed-silent population.
            noAudioRetry: sql<number>`COUNT(*) FILTER (WHERE ${adResearchBoardItems.dismissed} = false AND ${adResearchBoardItems.mediaErrorClass} = 'no-audio-track' AND ${adResearchBoardItems.mediaStatus} <> 'silent-source')`,
            downloading: sql<number>`COUNT(*) FILTER (WHERE ${adResearchBoardItems.dismissed} = false AND ${adResearchBoardItems.hiddenFromSheet} = false AND ${adResearchBoardItems.mediaStatus} = 'downloading')`,
            pending: sql<number>`COUNT(*) FILTER (WHERE ${adResearchBoardItems.dismissed} = false AND ${adResearchBoardItems.hiddenFromSheet} = false AND (${adResearchBoardItems.mediaStatus} = 'pending' OR ${adResearchBoardItems.mediaStatus} IS NULL))`,
            inventoryTotal: sql<number>`COUNT(*)`,
          })
          .from(adResearchBoardItems)
          .catch(logSubFailure("buckets")),
        // Task #366: latest sync session for the ad-research board so
        // we can surface `rowsSkipped` (source rows the sync silently
        // dropped before they could be upserted - currently empty link
        // cells) on the breakdown popover. Tracked separately from the
        // disjoint inventory buckets above because it describes the
        // sync stage, not the row state.
        db
          .select({
            rowsSkipped: syncSessions.rowsSkipped,
            rowsFetched: syncSessions.rowsFetched,
            startedAt: syncSessions.startedAt,
          })
          .from(syncSessions)
          .where(eq(syncSessions.board, "ad-research"))
          .orderBy(desc(syncSessions.startedAt))
          .limit(1)
          .catch(logSubFailure("latestSyncSession")),
      ]);
    // (end Promise.all destructure — fall-through into post-processing)

    const total = Number(totalCountResult[0]?.n ?? 0);
    // Task #366: explicit buckets for every distinct mediaStatus the
    // schema can produce. `pending` continues to absorb the null case
    // (legacy rows with no mediaStatus set yet) so the breakdown still
    // sums to the non-dismissed population.
    const counts = {
      ok: 0,
      failed: 0,
      // Task #401: needsFixing mirrors the admin triage filter exactly
      // so the `Needs Fixing (N)` badge matches the visible row count
      // 1:1. failedPermanent surfaces terminal exhaustions separately
      // (they're dismissed and therefore not in needsFixing).
      needsFixing: 0,
      failedPermanent: 0,
      pending: 0,
      partial: 0,
      downloading: 0,
      invalid: 0,
      dismissed: 0,
      hidden: 0,
      missingObjectPath: 0,
      sourceRowsSkipped: 0,
      // T370: dedicated count for ads whose source video carries no
      // audio on either extractor. Persisted as mediaStatus='silent-source'
      // (visible on the public board with a "no audio" badge).
      silentSource: 0,
      // T370: in-flight no-audio-track retry population - rows whose
      // last error was no-audio-track but that have NOT yet been
      // confirmed terminally silent. Distinct from silentSource so the
      // admin can watch the backfill drain.
      noAudioRetry: 0,
    };
    // Task #366: pull each disjoint bucket from the single aggregation.
    // The buckets sum to inventoryTotal exactly (modulo NULL safety).
    const b = bucketsResult?.[0];
    counts.dismissed = Number(b?.dismissed ?? 0);
    counts.hidden = Number(b?.hidden ?? 0);
    counts.ok = Number(b?.ready ?? 0); // legacy "ok" alias = ready
    counts.missingObjectPath = Number(b?.missingObjectPath ?? 0);
    counts.failed = Number(b?.failed ?? 0);
    counts.needsFixing = Number(b?.needsFixing ?? 0);
    counts.failedPermanent = Number(b?.failedPermanent ?? 0);
    counts.invalid = Number(b?.invalid ?? 0);
    counts.downloading = Number(b?.downloading ?? 0);
    counts.pending = Number(b?.pending ?? 0);
    counts.partial = 0; // collapsed into ready/missingObjectPath above
    counts.silentSource = Number(b?.silentSource ?? 0);
    counts.noAudioRetry = Number(b?.noAudioRetry ?? 0);
    counts.sourceRowsSkipped = Number(latestSyncSessionResult?.[0]?.rowsSkipped ?? 0);

    // Pull each facet via the strongly-typed selectDistinct row shape
    // rather than indexing by string key — keeps us out of `any` land
    // and gives drizzle a chance to flag schema drift here at compile
    // time if any of these columns are renamed in the future.
    const collectFacet = (
      pick: (row: NonNullable<typeof facetsResult>[number]) => string | null,
    ): string[] => {
      const out = new Set<string>();
      for (const row of facetsResult ?? []) {
        const v = pick(row);
        if (typeof v === "string" && v.trim()) out.add(v.trim());
      }
      return Array.from(out).sort((a, b) => a.localeCompare(b));
    };
    const facets = {
      types: collectFacet((r) => r.type),
      awarenessStages: collectFacet((r) => r.awarenessStage),
      styles: collectFacet((r) => r.style),
    };

    // Belt-and-braces media-kind derivation: some legacy rows landed with
    // mediaKind=null even though the cached object is a valid mp4/jpeg.
    // Derive it from the content type at read time so the UI never has to
    // guess what render path to take. (The downloader sets it correctly
    // for new rows; this is the safety net for older data.)
    const deriveKind = (
      kind: "video" | "image" | null,
      contentType: string | null,
    ): "video" | "image" | null => {
      if (kind === "video" || kind === "image") return kind;
      const ct = (contentType || "").toLowerCase();
      if (ct.startsWith("video/")) return "video";
      if (ct.startsWith("image/")) return "image";
      return null;
    };
    const normalizedRows = pageRows.map((row) => ({
      ...row,
      mediaKind: deriveKind(row.mediaKind as "video" | "image" | null, row.mediaContentType),
      mediaItems: Array.isArray(row.mediaItems)
        ? row.mediaItems.map((m) => ({
            ...m,
            kind: deriveKind(m?.kind ?? null, m?.contentType ?? null) || m?.kind,
          }))
        : row.mediaItems,
    }));

    // Strip admin-only fields from the user-facing payload — none of these
    // are surfaced in the user UI and we don't want to leak them.
    const items = isAdmin
      ? normalizedRows
      : normalizedRows.map(({
          mediaError: _err,
          dismissed: _d,
          hiddenFromSheet: _h,
          resolvedUrl: _r,
          mediaAttempts: _a,
          ...rest
        }) => rest);

    // Task #366: pull headline ready + inventoryTotal from the same
    // disjoint aggregation as the breakdown buckets, so the header
    // can never disagree with the popover.
    const ready = counts.ok;
    const inventoryTotal = Number(b?.inventoryTotal ?? 0);
    // Task #366: invariant assertion - the disjoint buckets MUST sum
    // to inventoryTotal. If they don't, the breakdown is wrong and
    // we want to know loudly rather than silently lie to operators.
    const bucketSum =
      counts.dismissed +
      counts.hidden +
      counts.ok +
      counts.missingObjectPath +
      counts.failed +
      counts.invalid +
      counts.downloading +
      counts.pending;
    if (bucketSum !== inventoryTotal) {
      req.log?.warn?.(
        { bucketSum, inventoryTotal, counts },
        "ad-research-board breakdown buckets do not sum to inventoryTotal",
      );
    }
    res.json({
      items,
      page,
      pageSize,
      total,
      inventoryTotal,
      ready,
      counts,
      facets,
      lastSyncedAt: status?.lastSyncedAt || null,
      lastSyncOk: status?.lastSyncOk ?? null,
      lastSyncError: status?.lastSyncError || null,
    });
    return;
  } catch (err: any) {
    const code = classifyBoardError(err);
    req.log?.error?.(
      { err, route: "ad-research-board/items", userId: req.portalUser?.id, code },
      "ad-research-board GET items failed",
    );
    res.status(500).json({
      error: err?.message || "Failed to load board",
      code,
    });
    return;
  }
});

// Task #134 admin endpoints: unhide a single row, retry partial-carousel
// rows specifically (separate from the catch-all "Retry Failed"), and a
// pipeline-counts endpoint that breaks down the full population by
// downloader status, hidden_from_sheet, and url_kind so the admin can see
// the health of the pipeline at a glance.
portalRouter.post(
  "/portal/admin/ad-research-board/items/:id/unhide",
  requireAuth,
  requireAdmin,
  async (req, res) => {
    try {
      const id = Number(req.params.id);
      if (!Number.isFinite(id) || id <= 0) {
        res.status(400).json({ error: "Invalid id" }); return;
      }
      const { unhideAdResearchBoardItem } = await import("../lib/ad-research-board-sync");
      const result = await unhideAdResearchBoardItem(id);
      if (!result.ok) { res.status(404).json(result); return; }
      res.json(result);
      return;
    } catch (err: any) {
      console.error("ad-research-board unhide failed:", err);
      res.status(500).json({ error: err?.message || "Failed" });
      return;
    }
  },
);

// Retry only the partial-carousel rows (carousels we got SOME slides for
// but not all). This is a narrower version of "Retry Failed" that targets
// the specific case where Apify returned a short-by-one result and we want
// to give it another pass without burning quota on hard-failed rows.
portalRouter.post(
  "/portal/admin/ad-research-board/retry-partials",
  requireAuth,
  requireAdmin,
  async (_req, res) => {
    try {
      const { MAX_ATTEMPTS, processPendingMediaInBackground } = await import("../lib/media-downloader");
      // Task #134: partial is now a first-class mediaStatus, so we no
      // longer have to scan mediaMeta JSON to find candidates — they're
      // exactly the rows where mediaStatus='partial' and dismissed=false.
      const result = await db
        .update(adResearchBoardItems)
        .set({
          mediaStatus: "pending",
          mediaError: null,
          mediaAttempts: MAX_ATTEMPTS - 1,
          mediaDownloadedAt: null,
          updatedAt: sql`now()`,
        })
        .where(
          and(
            eq(adResearchBoardItems.dismissed, false),
            eq(adResearchBoardItems.mediaStatus, "partial"),
          ),
        )
        .returning({ id: adResearchBoardItems.id });
      if (result.length > 0) processPendingMediaInBackground();
      res.json({ ok: true, requeued: result.length });
      return;
    } catch (err: any) {
      console.error("ad-research-board retry-partials failed:", err);
      res.status(500).json({ error: err?.message || "Failed" });
      return;
    }
  },
);

// Full pipeline-health snapshot: status buckets + hidden + dismissed +
// per-url-kind counts, computed across the entire ad_research_board_items
// population. Cheap (a handful of indexed COUNT queries) and lets the
// admin UI render an at-a-glance pipeline panel without overloading the
// main /items endpoint with admin-only counts.
portalRouter.get(
  "/portal/admin/ad-research-board/pipeline-counts",
  requireAuth,
  requireAdmin,
  async (_req, res) => {
    try {
      // Task #137: stuck = mediaStatus='downloading' AND
      // (mediaDownloadedAt IS NULL OR < cutoff). Mirrors the SELECT in
      // processPendingMedia so the admin pill matches what the next pass
      // will pick up. Backoff is 15min so we use the same window here.
      const STUCK_BACKOFF_MINUTES = 15;
      const stuckCutoff = new Date(Date.now() - STUCK_BACKOFF_MINUTES * 60 * 1000);
      const [statusRows, hiddenRow, dismissedRow, urlKindRows, stuckRow] =
        await Promise.all([
          db
            .select({ status: adResearchBoardItems.mediaStatus, n: count() })
            .from(adResearchBoardItems)
            .where(eq(adResearchBoardItems.dismissed, false))
            .groupBy(adResearchBoardItems.mediaStatus),
          db
            .select({ n: count() })
            .from(adResearchBoardItems)
            .where(
              and(
                eq(adResearchBoardItems.hiddenFromSheet, true),
                eq(adResearchBoardItems.dismissed, false),
              ),
            ),
          db
            .select({ n: count() })
            .from(adResearchBoardItems)
            .where(eq(adResearchBoardItems.dismissed, true)),
          db
            .select({ urlKind: adResearchBoardItems.urlKind, n: count() })
            .from(adResearchBoardItems)
            .where(eq(adResearchBoardItems.dismissed, false))
            .groupBy(adResearchBoardItems.urlKind),
          db
            .select({ n: count() })
            .from(adResearchBoardItems)
            .where(
              and(
                eq(adResearchBoardItems.dismissed, false),
                eq(adResearchBoardItems.mediaStatus, "downloading"),
                or(
                  isNull(adResearchBoardItems.mediaDownloadedAt),
                  lt(adResearchBoardItems.mediaDownloadedAt, stuckCutoff),
                ),
              ),
            ),
        ]);
      // Task #134: full first-class status breakdown - every value the
      // downloader writes is its own bucket. `pending` collapses NULL +
      // "pending" only; "downloading" is its own bucket.
      const status = { ok: 0, failed: 0, pending: 0, downloading: 0, partial: 0, stuck: 0 };
      for (const row of statusRows) {
        const n = Number(row.n);
        if (row.status === "ok") status.ok += n;
        else if (row.status === "failed") status.failed += n;
        else if (row.status === "partial") status.partial += n;
        else if (row.status === "downloading") status.downloading += n;
        else status.pending += n; // null + "pending"
      }
      status.stuck = Number(stuckRow[0]?.n ?? 0);
      const byUrlKind: Record<string, number> = {};
      for (const row of urlKindRows) {
        byUrlKind[row.urlKind || "unknown"] = Number(row.n);
      }
      res.json({
        ok: true,
        status,
        hidden: Number(hiddenRow[0]?.n ?? 0),
        dismissed: Number(dismissedRow[0]?.n ?? 0),
        partialCarousels: status.partial,
        byUrlKind,
      });
      return;
    } catch (err: any) {
      console.error("ad-research-board pipeline-counts failed:", err);
      res.status(500).json({ error: err?.message || "Failed" });
      return;
    }
  },
);

// Task #155: authenticated-scraping cookie jar admin endpoints. Cookie
// BYTES never leave the server — uploads accept text or a multipart
// file and the response always returns metadata only. Listed here
// alongside queue-health because the admin dashboard surfaces cookie
// health right next to queue health.
portalRouter.get(
  "/portal/admin/auth-cookies",
  requireAuth,
  requireAdmin,
  async (req, res) => {
    try {
      const mod = await import("../lib/auth-cookies");
      const [jars, health] = await Promise.all([mod.listJars(), mod.getAuthHealth()]);
      res.json({ ok: true, jars, health });
      return;
    } catch (err: any) {
      req.log?.error?.({ err }, "auth-cookies list failed");
      res.status(500).json({ error: err?.message || "Failed" });
      return;
    }
  },
);

// Task #158: customer-facing cookies.txt upload + delete endpoints
// REMOVED. Authenticated IG/FB extraction is now performed exclusively
// through Apify (operator-managed sessions, configured server-side).
// The auth_cookie_jars table and `auth-cookies` lib remain in place
// for back-compat and the existing yt-dlp `--cookies` fallback - they
// are no longer manageable from the customer dashboard. The GET list
// endpoint above is kept so the admin dashboard can still show jar
// metadata (when present) alongside the new Apify session-health view.

// T159: provider-aligned route aliases. The "auth-cookies" path
// reflected the old yt-dlp + cookies.txt model; under the Apify-first
// pipeline the canonical name is "extraction" (auth-health probe is
// really an Apify session-health probe). Both old and new routes are
// mounted, with the old paths kept as compat shims so any external
// monitor / runbook keeps working until it migrates.
async function adminExtractionProbeHandler(req: any, res: any): Promise<void> {
  try {
    const probeMod = await import("../lib/auth-health-probe");
    const cookiesMod = await import("../lib/auth-cookies");
    await probeMod.runProbeOnce();
    const [jars, health] = await Promise.all([
      cookiesMod.listJars(),
      cookiesMod.getAuthHealth(),
    ]);
    res.json({ ok: true, jars, health });
    return;
  } catch (err: any) {
    req.log?.error?.({ err }, "extraction probe failed");
    res.status(500).json({ error: err?.message || "Probe failed" });
    return;
  }
}

async function adminExtractionDiagnoseHandler(req: any, res: any): Promise<void> {
  try {
    const body = (req.body || {}) as { url?: string; platform?: string };
    if (!body.url || typeof body.url !== "string") {
      res.status(400).json({ error: "url is required" });
      return;
    }
    try { new URL(body.url); }
    catch {
      res.status(400).json({ error: "url is not a valid URL" });
      return;
    }
    const cookiesMod = await import("../lib/auth-cookies");
    const probeMod = await import("../lib/auth-health-probe");
    const platformOverride = body.platform && cookiesMod.isCookiePlatform(body.platform)
      ? body.platform
      : null;
    const result = await probeMod.runDiagnostic({
      url: body.url,
      platformOverride,
    });
    res.json({ ok: true, result });
    return;
  } catch (err: any) {
    req.log?.error?.({ err }, "extraction diagnose failed");
    res.status(500).json({ error: err?.message || "Diagnose failed" });
    return;
  }
}

// T159: canonical Apify-aligned routes. The dashboard now calls these.
portalRouter.post(
  "/portal/admin/extraction/probe",
  requireAuth,
  requireAdmin,
  adminExtractionProbeHandler,
);
portalRouter.post(
  "/portal/admin/extraction/diagnose",
  requireAuth,
  requireAdmin,
  adminExtractionDiagnoseHandler,
);

// Task #155 (verification): manually trigger the auth-health probe so
// an admin can validate a freshly-uploaded jar without waiting for
// the 6h scheduled cadence. Same code path the periodic timer uses;
// updates auth_health rows for both IG and FB on every call.
// T159: kept as a compat shim - delegates to the canonical
// /portal/admin/extraction/probe handler.
portalRouter.post(
  "/portal/admin/auth-cookies/probe",
  requireAuth,
  requireAdmin,
  adminExtractionProbeHandler,
);

// Task #155 (verification): one-shot yt-dlp --simulate against an
// admin-provided URL using the active jar for that URL's platform.
// Returns exit code, stderr/stdout summary, classified error, jar id,
// and whether authenticated extraction succeeded - the deterministic
// runtime proof an admin needs after uploading cookies. Read-only:
// does NOT write auth_health (use /probe for that).
// T159: kept as a compat shim - delegates to the canonical
// /portal/admin/extraction/diagnose handler.
portalRouter.post(
  "/portal/admin/auth-cookies/diagnose",
  requireAuth,
  requireAdmin,
  adminExtractionDiagnoseHandler,
);

// ─────────────────────────────────────────────────────────────────────
// Task #169: admin-managed Instagram session cookies for Apify scraping.
//
// Admins paste a Cookie-Editor / EditThisCookie JSON export. The blob is
// validated, normalized to Apify's loginCookies/sessionCookies shape,
// AES-256-GCM encrypted using INSTAGRAM_COOKIES_SECRET, and persisted in
// `provider_configs` (provider_slug='instagram', key='session_cookies').
// All Apify Instagram actor calls in the API server pull from this row
// via `instagram-session-cookies.withInstagramSessionCookies()`.
//
// GET    /portal/admin/instagram-cookies        - metadata (no plaintext)
// PUT    /portal/admin/instagram-cookies        - { cookiesJson: string }
// DELETE /portal/admin/instagram-cookies        - clear saved row
// POST   /portal/admin/instagram-cookies/test   - one Apify probe run
// ─────────────────────────────────────────────────────────────────────
portalRouter.get(
  "/portal/admin/instagram-cookies",
  requireAuth,
  requireAdmin,
  async (req: any, res) => {
    try {
      const mod = await import("../lib/instagram-session-cookies");
      const meta = await mod.getMetadata();
      res.json({ ok: true, ...meta });
      return;
    } catch (err: any) {
      req.log?.error?.({ err }, "instagram-cookies get failed");
      res.status(500).json({ error: err?.message || "Failed" });
      return;
    }
  },
);

portalRouter.put(
  "/portal/admin/instagram-cookies",
  requireAuth,
  requireAdmin,
  async (req: any, res) => {
    try {
      const body = (req.body || {}) as { cookiesJson?: string };
      if (!body.cookiesJson || typeof body.cookiesJson !== "string") {
        res.status(400).json({ error: "cookiesJson is required" });
        return;
      }
      const mod = await import("../lib/instagram-session-cookies");
      const savedBy = req.portalUser?.email || req.portalUser?.clerkId || null;
      const meta = await mod.saveCookies(body.cookiesJson, savedBy);
      res.json({ ok: true, ...meta });
      return;
    } catch (err: any) {
      req.log?.warn?.({ err: err?.message || String(err) }, "instagram-cookies save rejected");
      res.status(400).json({ error: err?.message || "Failed to save" });
      return;
    }
  },
);

