// Triage carousel rows that silently downgraded to a single slide (or that
// failed during the strong-retry chain). Resets them to pending so the next
// downloader pass retries them through the residential-proxy + secondary-actor
// chain. Returns the count of rows actually reset.
portalRouter.post(
  "/portal/admin/ad-research-board/requeue-incomplete-carousels",
  requireAuth,
  requireAdmin,
  async (_req, res) => {
    try {
      const { requeueIncompleteCarousels } = await import("../lib/media-downloader");
      const result = await requeueIncompleteCarousels();
      res.json(result);
      return;
    } catch (err: any) {
      console.error("ad-research-board requeue-incomplete-carousels failed:", err);
      res.status(500).json({ error: err?.message || "Failed" });
      return;
    }
  },
);

// Reset every failed (non-dismissed) row to pending so the next downloader
// pass retries them with the full fallback chain (apify primary →
// presetshubham reel-downloader → yt-dlp). Useful after we add a new actor
// and want stale failures to re-attempt without waiting for the next sheet
// sync.
//
// We reset attempts to MAX_ATTEMPTS - 1 (not 0). That way exactly ONE more
// real download attempt happens, and persistResult will dismiss the row if
// that attempt also fails. This is what makes "Retry Failed (N)" actually
// drain the badge to zero in a single retry cycle instead of needing 4
// background runs spaced 15 minutes apart.
portalRouter.post(
  "/portal/admin/ad-research-board/requeue-failed",
  requireAuth,
  requireAdmin,
  async (_req, res) => {
    try {
      // Single source of truth for the retry cap, owned by the downloader.
      const { MAX_ATTEMPTS } = await import("../lib/media-downloader");
      const result = await db
        .update(adResearchBoardItems)
        .set({
          mediaStatus: "pending",
          mediaError: null,
          mediaAttempts: MAX_ATTEMPTS - 1,
          mediaDownloadedAt: null,
          updatedAt: sql`now()`,
        })
        .where(
          and(
            eq(adResearchBoardItems.mediaStatus, "failed"),
            eq(adResearchBoardItems.dismissed, false),
          ),
        )
        .returning({ id: adResearchBoardItems.id });
      const { processPendingMediaInBackground } = await import("../lib/media-downloader");
      processPendingMediaInBackground();
      res.json({ ok: true, requeued: result.length });
      return;
    } catch (err: any) {
      console.error("ad-research-board requeue-failed failed:", err);
      res.status(500).json({ error: err?.message || "Failed" });
      return;
    }
  },
);

// Task #186: one-shot admin backfill of cached video thumbnails. Idempotent;
// only touches rows where mediaThumbnailObjectPath IS NULL, so re-running is
// safe. Bounded by `limit` to keep the Media Worker responsive while a large
// backfill runs.
portalRouter.post(
  "/portal/admin/ad-research-board/backfill-thumbnails",
  requireAuth,
  requireAdmin,
  async (req, res) => {
    try {
      const limit = Number((req.body && req.body.limit) ?? 200);
      const { backfillVideoThumbnails } = await import("../lib/media-downloader");
      const result = await backfillVideoThumbnails({
        limit: Number.isFinite(limit) && limit > 0 ? limit : 200,
      });
      res.json({ ok: true, ...result });
      return;
    } catch (err: any) {
      req.log?.error?.({ err: err?.message }, "ad-research-board backfill-thumbnails failed");
      res.status(500).json({ error: err?.message || "Failed" });
      return;
    }
  },
);

// One-shot admin backfill that scans cached video rows on the ad-research
// board, probes each one with ffprobe for a missing audio track, and
// requeues offenders so the (now audio-aware) Media Worker re-fetches
// them. Idempotent and bounded by `limit` so a 1700-row backfill can't
// pin the worker.
portalRouter.post(
  "/portal/admin/ad-research-board/requeue-no-audio",
  requireAuth,
  requireAdmin,
  async (req, res) => {
    try {
      const limit = Number((req.body && req.body.limit) ?? 200);
      const { backfillVideosMissingAudio, processPendingMediaInBackground } =
        await import("../lib/media-downloader");
      const result = await backfillVideosMissingAudio({
        limit: Number.isFinite(limit) && limit > 0 ? limit : 200,
      });
      if (result.requeued > 0) processPendingMediaInBackground();
      res.json({ ok: true, ...result });
      return;
    } catch (err: any) {
      req.log?.error?.({ err: err?.message }, "ad-research-board requeue-no-audio failed");
      res.status(500).json({ error: err?.message || "Failed" });
      return;
    }
  },
);

// Companion to /requeue-no-audio: scans rows whose source URL is a video
// kind (instagram-reel, facebook-reel, facebook-video, direct-video) but
// whose cached media is an image (the post thumbnail was silently saved
// instead of the actual video) and requeues them so the now-video-aware
// download path re-fetches via yt-dlp. Idempotent and bounded by `limit`.
portalRouter.post(
  "/portal/admin/ad-research-board/requeue-video-cached-as-image",
  requireAuth,
  requireAdmin,
  async (req, res) => {
    try {
      const limit = Number((req.body && req.body.limit) ?? 200);
      const { backfillVideoKindRowsCachedAsImage, processPendingMediaInBackground } =
        await import("../lib/media-downloader");
      const result = await backfillVideoKindRowsCachedAsImage({
        limit: Number.isFinite(limit) && limit > 0 ? limit : 200,
      });
      if (result.requeued > 0) processPendingMediaInBackground();
      res.json({ ok: true, ...result });
      return;
    } catch (err: any) {
      req.log?.error?.({ err: err?.message }, "ad-research-board requeue-video-cached-as-image failed");
      res.status(500).json({ error: err?.message || "Failed" });
      return;
    }
  },
);

// Manually dismiss a single row - admin moderation escape hatch. Hides
// the row from the user board and admin operational views, but is
// strictly a moderation action: it does NOT pretend the extraction
// failed and does NOT write into mediaStatus / mediaError /
// mediaErrorClass / mediaOutcomeChangedAt. Operational telemetry
// (success rate, Recent Failures, Terminal Fail, severity, failure
// class breakdown) must reflect real runtime/system outcomes only,
// never administrative moderation - the user-board success rate and
// the live-health badge are intentionally decoupled from this action.
portalRouter.post(
  "/portal/admin/ad-research-board/items/:id/dismiss",
  requireAuth,
  requireAdmin,
  async (req, res) => {
    try {
      const id = Number(req.params.id);
      if (!Number.isFinite(id) || id <= 0) {
        res.status(400).json({ error: "Invalid id" }); return;
      }
      const result = await db
        .update(adResearchBoardItems)
        .set({
          dismissed: true,
          // Moderation-only: archive the row from the durable media
          // library so it stops appearing on the user board and in the
          // admin operational views, while leaving every operational
          // field (mediaStatus, mediaError, mediaErrorClass,
          // mediaOutcomeChangedAt, mediaAttempts) untouched. The
          // extraction outcome that produced this row, whether it was
          // 'ok' with a healthy GCS object or 'pending' or anything
          // else, is preserved verbatim.
          libraryVisibility: "archived",
          updatedAt: sql`now()`,
        })
        .where(eq(adResearchBoardItems.id, id))
        .returning({ id: adResearchBoardItems.id });
      if (!result.length) { res.status(404).json({ error: "Item not found" }); return; }
      res.json({ ok: true, id: result[0].id });
      return;
    } catch (err: any) {
      console.error("ad-research-board dismiss failed:", err);
      res.status(500).json({ error: err?.message || "Failed" });
      return;
    }
  },
);

// ---------- Daily Funnels & Landing Page Research Board ----------
// Mirrors a public Google Sheet (#ID, link, Greg's notes) on a 24h cadence.
// Same gate as the ads board: admin OR bump2Paid.

// Task #307: server-side pagination + filtering, mirroring the ads endpoint.
// Previously this returned every row in one shot and the client did all the
// filtering / sorting in memory, which made the Funnels tab as slow as the
// pre-pagination Ads tab on a large board. Now the client uses an infinite
// query with the same incremental loading UX as the Ads tab.
portalRouter.get("/portal/funnels-research-board/items", requireAuth, async (req: any, res) => {
  try {
    const user = req.portalUser;
    if (!user) { res.status(401).json({ error: "Unauthorized" }); return; }
    const isAdmin = user.role === "admin";
    const entitlements = await computePurchaseEntitlements(user);
    if (!isAdmin && !entitlements.bump2Paid) {
      res.status(403).json({ error: "Funnels Research Board not unlocked" }); return;
    }

    const q = req.query as Record<string, unknown>;
    const toArray = (v: unknown): string[] => {
      if (Array.isArray(v)) return v.map((x) => String(x).trim()).filter(Boolean);
      if (typeof v === "string" && v.length) return [v.trim()].filter(Boolean);
      return [];
    };
    const pageRaw = Number(q.page);
    const page = Number.isFinite(pageRaw) && pageRaw > 0 ? Math.floor(pageRaw) : 1;
    const pageSizeRaw = Number(q.pageSize);
    const pageSize = Number.isFinite(pageSizeRaw)
      ? Math.max(1, Math.min(60, Math.floor(pageSizeRaw)))
      : 12;
    const search = typeof q.search === "string" ? q.search.trim() : "";
    const typeFilter = toArray(q.type);
    const awarenessFilter = toArray(q.awarenessStage);

    const filterClauses: SQL[] = [];
    if (typeFilter.length) filterClauses.push(inArray(funnelsResearchBoardItems.type, typeFilter));
    if (awarenessFilter.length)
      filterClauses.push(inArray(funnelsResearchBoardItems.awarenessStage, awarenessFilter));
    if (search) {
      const like = `%${search.replace(/[%_\\]/g, (c) => `\\${c}`)}%`;
      const searchExpr = or(
        ilike(funnelsResearchBoardItems.rowKey, like),
        ilike(funnelsResearchBoardItems.funnelLink, like),
        ilike(funnelsResearchBoardItems.notes, like),
        ilike(funnelsResearchBoardItems.type, like),
        ilike(funnelsResearchBoardItems.awarenessStage, like),
        ilike(funnelsResearchBoardItems.style, like),
      );
      if (searchExpr) filterClauses.push(searchExpr);
    }
    const whereExpr = filterClauses.length ? and(...filterClauses) : undefined;

    const baseSelect = {
      id: funnelsResearchBoardItems.id,
      rowKey: funnelsResearchBoardItems.rowKey,
      sortIndex: funnelsResearchBoardItems.sortIndex,
      funnelLink: funnelsResearchBoardItems.funnelLink,
      type: funnelsResearchBoardItems.type,
      awarenessStage: funnelsResearchBoardItems.awarenessStage,
      style: funnelsResearchBoardItems.style,
      notes: funnelsResearchBoardItems.notes,
      previewSourceUrl: funnelsResearchBoardItems.previewSourceUrl,
      pdfSourceUrl: funnelsResearchBoardItems.pdfSourceUrl,
      previewObjectPath: funnelsResearchBoardItems.previewObjectPath,
      previewContentType: funnelsResearchBoardItems.previewContentType,
      previewStatus: funnelsResearchBoardItems.previewStatus,
      previewError: funnelsResearchBoardItems.previewError,
      updatedAt: funnelsResearchBoardItems.updatedAt,
    } as const;

    const pageQuery = whereExpr
      ? db.select(baseSelect).from(funnelsResearchBoardItems).where(whereExpr)
      : db.select(baseSelect).from(funnelsResearchBoardItems);
    const totalQuery = whereExpr
      ? db.select({ n: count() }).from(funnelsResearchBoardItems).where(whereExpr)
      : db.select({ n: count() }).from(funnelsResearchBoardItems);

    // Task #512: only items + totalRow are critical. Facets and the
    // sync-status header fall back to safe defaults so a single failed
    // sub-query (typically a `sync_sessions` schema drift) returns a
    // usable board instead of a 500 for the whole page.
    const logSubFailure = (sub: string) => (err: unknown) => {
      req.log?.warn?.(
        { err, route: "funnels-research-board/items", sub, code: classifyBoardError(err) },
        "funnels-research-board sub-query failed; using fallback",
      );
      return null;
    };
    const [items, totalRow, facetsResult, status] = await Promise.all([
      pageQuery
        .orderBy(asc(funnelsResearchBoardItems.sortIndex))
        .limit(pageSize)
        .offset((page - 1) * pageSize),
      totalQuery,
      db
        .selectDistinct({
          type: funnelsResearchBoardItems.type,
          awarenessStage: funnelsResearchBoardItems.awarenessStage,
        })
        .from(funnelsResearchBoardItems)
        .catch(logSubFailure("facets")),
      getFunnelsResearchBoardSyncStatus().catch(logSubFailure("syncStatus")),
    ]);
    const total = Number(totalRow[0]?.n ?? 0);

    const collectFacet = (
      pick: (row: NonNullable<typeof facetsResult>[number]) => string | null,
    ): string[] => {
      const out = new Set<string>();
      for (const row of facetsResult ?? []) {
        const v = pick(row);
        if (typeof v === "string" && v.trim()) out.add(v.trim());
      }
      return Array.from(out).sort((a, b) => a.localeCompare(b));
    };
    const facets = {
      types: collectFacet((r) => r.type),
      awarenessStages: collectFacet((r) => r.awarenessStage),
    };

    res.json({
      items,
      page,
      pageSize,
      total,
      facets,
      lastSyncedAt: status?.lastSyncedAt || null,
      lastSyncOk: status?.lastSyncOk ?? null,
      lastSyncError: status?.lastSyncError || null,
    });
    return;
  } catch (err: any) {
    const code = classifyBoardError(err);
    req.log?.error?.(
      { err, route: "funnels-research-board/items", userId: req.portalUser?.id, code },
      "funnels-research-board GET items failed",
    );
    res.status(500).json({
      error: err?.message || "Failed to load board",
      code,
    });
    return;
  }
});

