portalRouter.put("/portal/admin/vsl-template-links/:slug", requireAuth, requireAdmin, async (req: any, res) => {
  try {
    const slug = String(req.params.slug || "").trim();
    if (!slug) { res.status(400).json({ error: "Missing slug" }); return; }
    const rawUrl = req.body?.url;
    let url: string | null = null;
    if (typeof rawUrl === "string" && rawUrl.trim().length > 0) {
      const trimmed = rawUrl.trim();
      try {
        const u = new URL(trimmed);
        if (u.protocol !== "http:" && u.protocol !== "https:") {
          res.status(400).json({ error: "URL must start with http or https" }); return;
        }
        url = trimmed;
      } catch {
        res.status(400).json({ error: "Invalid URL" }); return;
      }
    }
    await db
      .insert(vslTemplateLinks)
      .values({ slug, url, updatedAt: new Date() })
      .onConflictDoUpdate({
        target: vslTemplateLinks.slug,
        set: { url, updatedAt: new Date() },
      });
    res.json({ ok: true, slug, url });
    return;
  } catch (err: any) {
    console.error("vsl-template-links PUT failed:", err);
    res.status(500).json({ error: err?.message || "Failed" });
    return;
  }
});

// ----------------------------------------------------------------
// INSTAGRAM CAROUSEL CREATOR
// Generate slide-by-slide tweet-style copy from a hook + offer info, then
// render the slides as 1080x1350 PNGs (cover slide + N tweet slides) and
// stream them back as a downloadable zip.
//
// Endpoints:
//   POST /api/portal/carousel/upload   — multer image upload -> {url}
//   POST /api/portal/carousel/generate — OpenAI -> {slides: [...]}
//   POST /api/portal/carousel/render   — slides + assets -> zip stream
// ----------------------------------------------------------------

const CAROUSEL_FORBIDDEN_TOKENS = /(\u2014|\u2013|\*|\bbig\b|\bleverage\b)/i;

portalRouter.post(
  "/portal/carousel/upload",
  requireAuth,
  requireActive,
  upload.single("image"),
  async (req: any, res) => {
    try {
      if (!req.file) { res.status(400).json({ error: "No image file provided" }); return; }
      const allowedTypes = ["image/jpeg", "image/png", "image/gif", "image/webp"];
      if (!allowedTypes.includes(req.file.mimetype)) {
        res.status(400).json({ error: "Invalid file type. Allowed: JPG, PNG, GIF, WebP" }); return;
      }
      const bucketId = process.env.DEFAULT_OBJECT_STORAGE_BUCKET_ID;
      const privateDir = process.env.PRIVATE_OBJECT_DIR;
      if (!bucketId || !privateDir) {
        res.status(500).json({ error: "Object storage not configured" }); return;
      }
      const allowedExts = ["jpg", "jpeg", "png", "gif", "webp"];
      const rawExt = (req.file.originalname.split(".").pop() || "").toLowerCase();
      const ext = allowedExts.includes(rawExt) ? rawExt : "png";
      const fileName = `carousel-${crypto.randomUUID()}.${ext}`;
      const objectPath = `${privateDir}/${fileName}`;
      const bucket = objectStorageClient.bucket(bucketId);
      const file = bucket.file(objectPath);
      await file.save(req.file.buffer, {
        contentType: req.file.mimetype,
        metadata: { cacheControl: "public, max-age=31536000" },
      });
      const servePath = `/api/portal/images/${fileName}`;
      res.json({ url: servePath, fileName }); return;
    } catch (err: any) {
      req.log?.error({ err }, "carousel upload failed");
      res.status(500).json({ error: err?.message || "Failed to upload image" }); return;
    }
  },
);

portalRouter.post("/portal/carousel/generate", requireAuth, requireActive, async (req: any, res) => {
  try {
    const { hook, offerInfo, tone, slideCount, includeCover } = req.body || {};
    if (!hook || typeof hook !== "string" || !hook.trim()) {
      res.status(400).json({ error: "A hook is required" }); return;
    }
    const count = Math.max(3, Math.min(15, Number(slideCount) || 8));
    const tweetCount = includeCover === false ? count : Math.max(2, count - 1);
    const safeTone = (typeof tone === "string" && tone.trim()) || "punchy, direct, conversational";
    const safeOffer = (typeof offerInfo === "string" && offerInfo.trim()) || "(no offer details supplied)";

    const systemPrompt = `You are a viral Instagram carousel ghostwriter modeled on the @thederekgray tweet-screenshot style.

You write tight, scroll-stopping, tweet-style copy for Instagram carousel slides. Each slide is a single short "tweet" that makes one clear point and lands hard.

HARD RULES:
- NEVER use em dashes (—) or en dashes (–). Use a regular hyphen (-) with spaces around it instead.
- NEVER use markdown asterisks for bold or italic. No * characters at all in the output.
- NEVER use the words "big" or "leverage". Use "large" or "use" instead.
- NEVER write a slide that is just a question.
- NEVER use emojis or hashtags.
- NEVER use the literal phrase "in conclusion" or "to summarise".
- Each tweet body MUST be 30 to 90 words. Two or three short paragraphs separated by a single blank line.
- First tweet slide opens with a punchy claim that pays off the cover hook.
- Last tweet slide ends with a clear, direct call-to-action that fits the offer.
- Tone: ${safeTone}.

You will return STRICT JSON only - no preamble, no code fence, no commentary.`;

    const userPrompt = `Cover hook (this is what slide 1 will say in giant uppercase letters over a photo):
"${hook.trim()}"

Offer / niche / context the carousel is selling or supporting:
${safeOffer}

Produce a JSON object with this exact shape:
{
  "cover": { "headline": "<rewrite the cover hook in punchy uppercase-friendly form, 4-12 words>" },
  "tweets": [ { "body": "<tweet body as a single string with paragraphs separated by a blank line>" }, ... ]
}

Constraints:
- "tweets" must contain exactly ${tweetCount} entries.
- The first tweet pays off the cover hook directly.
- The final tweet contains a clear call-to-action pointing the reader to the offer described above.
- No em/en dashes, no asterisks, no "big", no "leverage", no emojis, no hashtags.

Return ONLY the JSON object. Nothing else.`;

    const openai = new OpenAI({
      baseURL: process.env.AI_INTEGRATIONS_OPENAI_BASE_URL,
      apiKey: process.env.AI_INTEGRATIONS_OPENAI_API_KEY,
    });

    const completion = await openai.chat.completions.create({
      model: "gpt-4o",
      response_format: { type: "json_object" },
      messages: [
        { role: "system", content: systemPrompt },
        { role: "user", content: userPrompt },
      ],
      max_completion_tokens: 4096,
    });

    const raw = completion.choices[0]?.message?.content || "";
    let parsed: { cover?: { headline?: string }; tweets?: Array<{ body?: string }> };
    try {
      parsed = JSON.parse(raw);
    } catch (e) {
      req.log?.error({ raw }, "carousel generate: could not parse JSON");
      res.status(502).json({ error: "AI returned invalid JSON. Try again." }); return;
    }

    const scrub = (s: string) =>
      (s || "")
        .replace(/\u2014/g, " - ")
        .replace(/\u2013/g, " - ")
        .replace(/\*+([^*]+)\*+/g, "$1")
        .replace(/\*/g, "")
        .replace(/\bbig\b/gi, (m) => (m === "BIG" ? "LARGE" : m === "Big" ? "Large" : "large"))
        .replace(/\bleverage\b/gi, (m) => (m === "LEVERAGE" ? "USE" : m === "Leverage" ? "Use" : "use"));

    const slides: CarouselSlide[] = [];
    if (includeCover !== false) {
      slides.push({
        type: "cover",
        headline: scrub(parsed.cover?.headline || hook),
        subhint: "(Swipe left for the breakdown)",
      });
    }
    for (const t of parsed.tweets || []) {
      if (t?.body) slides.push({ type: "tweet", body: scrub(t.body) });
    }

    res.json({ slides });
    void saveToolGeneration({
      portalUserId: req.portalUser.id,
      toolSlug: "carousel",
      label: hook.trim().slice(0, 160),
      input: { hook: hook.trim(), offerInfo: safeOffer, tone: safeTone, slideCount: count, includeCover: includeCover !== false },
      output: { slides },
    });
    return;
  } catch (err: any) {
    req.log?.error({ err }, "carousel generate failed");
    res.status(500).json({ error: err?.message || "Failed to generate carousel copy" }); return;
  }
});

portalRouter.post("/portal/carousel/render", requireAuth, requireActive, async (req: any, res) => {
  try {
    const { slides, displayName, handle, verified, profileImageUrl } = req.body || {};
    if (!Array.isArray(slides) || slides.length === 0) {
      res.status(400).json({ error: "At least one slide is required" }); return;
    }
    if (slides.length > 20) {
      res.status(400).json({ error: "Maximum 20 slides per render" }); return;
    }
    if (!displayName || typeof displayName !== "string") {
      res.status(400).json({ error: "displayName is required" }); return;
    }
    if (!handle || typeof handle !== "string") {
      res.status(400).json({ error: "handle is required" }); return;
    }

    // Validate every slide and reject forbidden tokens up front so the user
    // sees a clean error rather than a sanitized but surprising PNG.
    const cleanSlides: CarouselSlide[] = [];
    for (const [i, s] of slides.entries()) {
      if (!s || typeof s !== "object") {
        res.status(400).json({ error: `Slide ${i + 1} is malformed` }); return;
      }
      if (s.type === "cover") {
        if (!s.headline || typeof s.headline !== "string") {
          res.status(400).json({ error: `Cover slide ${i + 1} is missing a headline` }); return;
        }
        cleanSlides.push({
          type: "cover",
          headline: s.headline,
          subhint: typeof s.subhint === "string" ? s.subhint : undefined,
          backgroundImageUrl: typeof s.backgroundImageUrl === "string" ? s.backgroundImageUrl : undefined,
        });
      } else if (s.type === "tweet") {
        if (!s.body || typeof s.body !== "string") {
          res.status(400).json({ error: `Tweet slide ${i + 1} is missing body copy` }); return;
        }
        cleanSlides.push({
          type: "tweet",
          body: s.body,
          bottomImageUrl: typeof s.bottomImageUrl === "string" ? s.bottomImageUrl : undefined,
        });
      } else {
        res.status(400).json({ error: `Slide ${i + 1} has unknown type` }); return;
      }
    }

    const assets: CarouselAssets = {
      displayName: String(displayName).slice(0, 60),
      handle: String(handle).slice(0, 32),
      verified: !!verified,
      profileImageUrl: typeof profileImageUrl === "string" ? profileImageUrl : undefined,
    };

    const zipBuf = await renderCarouselToZip(cleanSlides, assets);
    const filename = `carousel-${Date.now()}.zip`;
    res.setHeader("Content-Type", "application/zip");
    res.setHeader("Content-Disposition", `attachment; filename="${filename}"`);
    res.setHeader("Content-Length", String(zipBuf.length));
    res.send(zipBuf); return;
  } catch (err: any) {
    req.log?.error({ err }, "carousel render failed");
    res.status(500).json({ error: err?.message || "Failed to render carousel" }); return;
  }
});

// silence unused-warn for the regex (used as a future server-side guard hook)
void CAROUSEL_FORBIDDEN_TOKENS;

// ----------------------------------------------------------------
// Script Writer OS - Job status + history
// ----------------------------------------------------------------
// All 9 SOPs (green-screen, hook-demo, podcast-clip, speaking-clip,
// selfie-clip, slideshow, carousel, overlay, fastmotion) now return a
// `jobId` immediately and run their OpenAI work in the background. The
// frontend polls this status endpoint every ~1.5s for progress + result,
// and renders a per-SOP "Recent Scripts" panel from the history endpoint.
// Jobs are owner-scoped by clerkId so users can only ever read their own.
// ----------------------------------------------------------------
const SCRIPT_JOB_TYPES: readonly ScriptJobType[] = [
  "green-screen",
  "hook-demo",
  "podcast-clip",
  "speaking-clip",
  "selfie-clip",
  "slideshow",
  "carousel",
  "overlay",
  "fastmotion",
];

// Cross-device / cross-tab resume: the newest in-flight (queued|running)
// job for this user across all SOP types, or null. Registered BEFORE the
// `/jobs/:id` route so "active" is not captured as an `:id` param.
portalRouter.get(
  "/portal/script-writer/jobs/active",
  requireAuth,
  requireActive,
  async (req: any, res) => {
    const job = await getActiveScriptJob(req.clerkId);
    if (!job) { res.json({ ok: true, job: null }); return; }
    res.json({
      ok: true,
      job: {
        id: job.id,
        type: job.type,
        status: job.status,
        progressPct: job.progressPct,
        stage: job.stage,
        label: job.label,
        createdAt: job.createdAt,
        updatedAt: job.updatedAt,
      },
    }); return;
  },
);

portalRouter.get(
  "/portal/script-writer/jobs/:id",
  requireAuth,
  requireActive,
  async (req: any, res) => {
    const idNum = Number(req.params.id);
    if (!Number.isFinite(idNum) || idNum <= 0) {
      res.status(400).json({ error: "Invalid job id" }); return;
    }
    const job = await getScriptJob(req.clerkId, idNum);
    if (!job) { res.status(404).json({ error: "Job not found" }); return; }
    res.json({
      id: job.id,
      type: job.type,
      status: job.status,
      progressPct: job.progressPct,
      stage: job.stage,
      label: job.label,
      result: job.status === "succeeded" ? job.result : null,
      errorMessage: job.errorMessage,
      createdAt: job.createdAt,
      updatedAt: job.updatedAt,
    }); return;
  },
);

portalRouter.get(
  "/portal/script-writer/jobs",
  requireAuth,
  requireActive,
  async (req: any, res) => {
    const type = String(req.query.type || "").trim() as ScriptJobType;
    if (!SCRIPT_JOB_TYPES.includes(type)) {
      res.status(400).json({ error: "Missing or invalid `type` query param." }); return;
    }
    const limit = Math.max(1, Math.min(50, Number(req.query.limit) || 20));
    const jobs = await listScriptJobs(req.clerkId, type, limit);
    res.json({
      ok: true,
      jobs: jobs.map((j) => ({
        id: j.id,
        type: j.type,
        status: j.status,
        progressPct: j.progressPct,
        stage: j.stage,
        label: j.label,
        errorMessage: j.errorMessage,
        createdAt: j.createdAt,
        updatedAt: j.updatedAt,
      })),
    }); return;
  },
);

// ----------------------------------------------------------------
// Script Writer OS - Green Screen
// ----------------------------------------------------------------
// User uploads up to 10 ordered green-screen images (article screenshots,
// notes, other reels, dashboards, etc.) that will sit behind them on
// camera, plus free-text context, plus their CTA "comment word". We
// resolve their brain (own or selected prebuilt) so the script always
// sells THE current offer, then ask gpt-4o vision to:
//   1. Read every image (text, charts, screenshots, what's actually
//      visible) in the supplied 1..N order
//   2. Pick a hook from the proven library (NEVER invent a new formula)
//   3. Write a 60-second green-screen script in the proven structure
//      (Hook -> Proof -> Opportunity -> Mini value -> Future pace -> CTA)
//   4. End with "Comment <COMMENT_WORD> below" so the CTA matches what
//      the user is going to pin in the comments.
// Mounted at POST /api/portal/script-writer/green-screen.
// ----------------------------------------------------------------
portalRouter.post(
  "/portal/script-writer/green-screen",
  requireAuth,
  requireActive,
  upload.array("images", 10),
  async (req: any, res) => {
    try {
      const user = req.portalUser;
      const files = (req.files as Express.Multer.File[]) || [];
      if (files.length === 0) {
        res.status(400).json({ error: "Upload at least one green-screen image." }); return;
      }
      if (files.length > 10) {
        res.status(400).json({ error: "Up to 10 green-screen images allowed." }); return;
      }
      for (const f of files) {
        if (!["image/jpeg", "image/png", "image/gif", "image/webp"].includes(f.mimetype)) {
          res.status(400).json({ error: `Unsupported image type: ${f.mimetype}` }); return;
        }
      }

      const body = req.body || {};
      const influencerId =
        body.influencerId && Number.isFinite(Number(body.influencerId))
          ? Number(body.influencerId)
          : null;
      const rawOfferId = typeof body.offerBrainId === "string" ? body.offerBrainId.trim() : "";
      // Room30 has no curated-brain catalogue: never honour an offerBrainId
      // request from that portal so OS tools never sell an Apex Offer
      // through the Room30 portal, even if a stale client sends one.
      const offerBrainId = rawOfferId && rawOfferId !== "own" && getPortalKey(req) !== "room30" ? rawOfferId : null;
      const context = (typeof body.context === "string" ? body.context : "").trim().slice(0, 1500);
      const commentWordRaw = (typeof body.commentWord === "string" ? body.commentWord : "").trim();
      // Sanitize the comment word - it goes straight into the script CTA.
      // Keep it short, single token-ish, uppercase friendly.
      const commentWord = commentWordRaw
        .replace(/[^\w\-]/g, "")
        .slice(0, 24)
        .toUpperCase();
      if (!commentWord) {
        res.status(400).json({
          error: "Pick a comment word for your CTA (e.g. 'GO', 'START', 'SYSTEM'). One word.",
        }); return;
      }
      if (!context) {
        res.status(400).json({
          error: "Add a sentence of context so we know WHY you're talking about these images.",
        }); return;
      }

      // Resolve brain + offer (mirrors ig-bio-generator).
      let brain: any = null;
      let selectedOffer: { id: string; name: string; tagline: string } | null = null;
      if (offerBrainId) {
        const prebuilt = getPrebuiltBrain(offerBrainId);
        if (!prebuilt || prebuilt.isActive === false || prebuilt.comingSoon) {
          res.status(400).json({
            error: "That offer is no longer available. Pick another from the list.",
          }); return;
        }
        brain = {
          name: prebuilt.brainData.name,
          companyName: prebuilt.brainData.companyName,
          whoDoYouHelp: prebuilt.brainData.whoDoYouHelp,
          howDoYouHelpThem: prebuilt.brainData.howDoYouHelpThem,
          keyAchievements: prebuilt.brainData.keyAchievements,
          generatedBrain: prebuilt.generatedBrain,
        };
        selectedOffer = { id: prebuilt.id, name: prebuilt.name, tagline: prebuilt.tagline };
      } else {
        const [brainRow] = await db
          .select()
          .from(userBrainProfilesTable)
          .where(eq(userBrainProfilesTable.userId, user.id));
        brain = resolveEffectiveBrain(brainRow, getPortalKey(req));
        if (!brain) {
          res.status(400).json({
            error:
              "We couldn't find your Brain yet. Head to Your Brain or pick one of our pre-built offers above.",
          }); return;
        }
      }

      // Optional influencer the script is being written for (voice/persona).
      let influencerName = "";
      let influencerNiche = "";
      if (influencerId) {
        const appUserId = req.appUser?.id as number | undefined;
        const [inf] = appUserId
          ? await db
              .select()
              .from(aiInfluencersTable)
              .where(
                and(
                  eq(aiInfluencersTable.id, influencerId),
                  eq(aiInfluencersTable.clientId, appUserId),
                ),
              )
          : [];
        if (inf) {
          influencerName = inf.name;
          influencerNiche = inf.niche || "";
        }
      }

      // Upload every image to public storage so we can return URLs to the
      // client (record + thumbnail) AND so the model's analysis is anchored
      // to a stable URL, not just an in-memory buffer.
      const bucketId = process.env.DEFAULT_OBJECT_STORAGE_BUCKET_ID;
      const privateDir = process.env.PRIVATE_OBJECT_DIR;
      if (!bucketId || !privateDir) {
        res.status(500).json({ error: "Object storage not configured" }); return;
      }
      const bucket = objectStorageClient.bucket(bucketId);
      const uploadedUrls: string[] = [];
      const inlineImages: Array<{ index: number; b64: string; mime: string }> = [];
      for (let i = 0; i < files.length; i++) {
        const f = files[i];
        const rawExt = (f.originalname.split(".").pop() || "").toLowerCase();
        const ext = ["jpg", "jpeg", "png", "gif", "webp"].includes(rawExt) ? rawExt : "png";
        const fileName = `gs-${crypto.randomUUID()}.${ext}`;
        const file = bucket.file(`${privateDir}/${fileName}`);
        await file.save(f.buffer, {
          contentType: f.mimetype,
          metadata: { cacheControl: "public, max-age=31536000" },
        });
        uploadedUrls.push(`/api/portal/images/${fileName}`);
        inlineImages.push({
          index: i + 1,
          b64: f.buffer.toString("base64"),
          mime: f.mimetype,
        });
      }

      const stripHtml = (s: string) =>
        (s || "").replace(/<[^>]+>/g, " ").replace(/\s+/g, " ").trim();

      const brainContext = `
Owner: ${brain?.name || "Not specified"}
Company / brand: ${brain?.companyName || "Not specified"}
Who they help: ${brain?.whoDoYouHelp || "Not specified"}
How they help them: ${brain?.howDoYouHelpThem || "Not specified"}
Key achievements / proof / specific numbers: ${brain?.keyAchievements || "Not specified"}
`.trim();

      const generatedBrainBlock = brain?.generatedBrain
        ? `FULL BRAIN (canonical positioning, offer, mechanism, proof, audience, tone - the script must sell THIS offer with THIS brain's voice and proof; never invent figures that aren't in here):\n${stripHtml(brain.generatedBrain).slice(0, 6000)}`
        : "(No full brain generated yet - fall back to the fields above.)";

      const offerHeaderBlock = selectedOffer
        ? `SELECTED OFFER (the script's payoff/CTA must point at THIS offer):
Offer name: ${selectedOffer.name}
One-liner: ${selectedOffer.tagline}`
        : "SELECTED OFFER: the owner's own brand / brain (defined below).";

      const influencerBlock = influencerName
        ? `SELECTED AI INFLUENCER (this script is being read by THIS persona on camera):
Name: ${influencerName}
Niche: ${influencerNiche || "(not set)"}`
        : "(No specific AI influencer selected - write in the owner's own voice.)";

      const hookLibrary = getHookLibraryForPrompt({ perCategory: 30 });

      const systemPrompt = `You are an elite Instagram / TikTok green-screen script writer. The creator stands in front of a green-screen background. The background is the image(s) the user uploaded - article screenshots, iPhone Notes lists, dashboards, other people's reels, charts, headlines, etc. The script must be ABOUT WHAT IS IN THOSE IMAGES, in the order supplied. Image 1 is what they will show first, image 2 second, and so on.

PROVEN STRUCTURE (60 seconds, ~150 words):
1. HOOK (0-3s) - one of the proven hook formulas (see HOOK LIBRARY below). Adapt the {placeholders} to the offer/topic. NEVER invent a new hook formula - always start from one of the proven ones.
2. VISUAL PROOF / CONTEXT (3-7s) - one short sentence that points at what's on the green screen ("This article from <source> just dropped...", "Look at this Stripe screenshot...", "These are the 3 steps I just wrote in my Notes...").
3. THE BIG IDEA (7-20s) - problem -> gap -> opportunity, in plain language.
4. MINI VALUE (20-40s) - 2-3 short steps, enough that the viewer feels "they actually know this", but with knowledge gaps. Do NOT over-teach.
5. FUTURE PACE / DESIRE (40-50s) - one line painting the transformation.
6. CTA (50-60s) - the literal sentence: "Comment ${commentWord} below and I'll send you <thing tied to the offer>." Use exactly the comment word ${commentWord} in uppercase.

HARD RULES:
- The hook MUST come from the HOOK LIBRARY. Pick the category that fits the topic, lift one of the proven examples, and adapt the variables. Tell us which category and which formula text you used.
- The whole script must be ABOUT what's actually visible in the images, in the supplied order. If image 1 is a news headline, the script must reference that headline. If image 2 is a Notes app list of 3 steps, those 3 steps become the mini-value section. Never describe images that weren't uploaded.
- Pull every claim, number and proof point from the BRAIN. Never invent revenue figures, client counts or credentials.
- Talk like a smart friend who discovered something early and is simplifying it. Short sentences. Conversational. NO corporate / guru / motivational-speaker tone.
- NEVER use em dashes (\u2014) or en dashes (\u2013). Use a regular hyphen (-) with spaces around it.
- NEVER use markdown asterisks for bold/italic. No * characters.
- NEVER use the words "big" or "leverage". Use "large" or "use" instead.
- No emojis, no hashtags.
- 130-170 words total. Aim for ~60 seconds spoken at a fast Instagram pace.

OUTPUT JSON SHAPE (return ONLY this JSON, no preamble or code fence):
{
  "hookCategory": "hormozi" | "hundredFormulas" | "educational" | "storytelling" | "question" | "curiosity" | "listBased" | "problemSolving" | "relatable" | "tipsTricks",
  "hookFormulaUsed": "<the exact proven formula you started from, copied from the library>",
  "imageReadback": [ { "index": 1, "summary": "<1-sentence read of what is actually on this image>" }, ... ],
  "script": {
    "hook": "<spoken line, 1-2 short sentences>",
    "proof": "<spoken line pointing at the first image>",
    "opportunity": "<2-3 short sentences>",
    "miniValue": "<2-4 short sentences, may include numbered steps if the images are step-based>",
    "futurePace": "<1 short sentence>",
    "cta": "Comment ${commentWord} below and I'll send you <thing tied to the offer>."
  },
  "fullScript": "<the full script as one continuous string, ready to read on a teleprompter, sections separated by single line breaks>",
  "estimatedSeconds": <number 20-65>
}`;

      const userTextParts: any[] = [
        {
          type: "text",
          text: `BRAIN (canonical positioning):
${brainContext}

${generatedBrainBlock}

${offerHeaderBlock}

${influencerBlock}

CREATOR'S FREE-TEXT CONTEXT (why they're talking about these images):
"""
${context}
"""

CTA COMMENT WORD: ${commentWord}

GREEN-SCREEN IMAGES (in the order they will appear on screen, image 1 first):`,
        },
      ];
      for (const img of inlineImages) {
        userTextParts.push({ type: "text", text: `--- Image ${img.index} of ${inlineImages.length} ---` });
        userTextParts.push({
          type: "image_url",
          image_url: {
            url: `data:${img.mime};base64,${img.b64}`,
            detail: "high",
          },
        });
      }
      userTextParts.push({
        type: "text",
        text: `HOOK LIBRARY (proven, total ${PROVEN_HOOK_TOTAL} formulas; pick ONE and adapt):

${hookLibrary}

Now produce the JSON.`,
      });

      const jobId = await enqueueScriptJob({
        clerkId: req.clerkId,
        type: "green-screen",
        inputPayload: {
          context,
          commentWord,
          offerBrainId,
          influencerId,
          imageCount: files.length,
          uploadedImages: uploadedUrls,
        },
        label: (context || `${files.length} images`).slice(0, 80),
        log: req.log,
        work: async (ctx) => {
          await ctx.updateProgress(20, "Reading images and drafting");
          const openai = new OpenAI({
            baseURL: process.env.AI_INTEGRATIONS_OPENAI_BASE_URL,
            apiKey: process.env.OPENAI_API_KEY,
          });
          const completion = await openai.chat.completions.create({
            model: "gpt-4o",
            messages: [
              { role: "system", content: systemPrompt },
              { role: "user", content: userTextParts as any },
            ],
            response_format: { type: "json_object" },
            temperature: 0.8,
            max_tokens: 2500,
          });
          await ctx.updateProgress(90, "Cleaning output");
          const raw = completion.choices[0]?.message?.content || "{}";
          let parsed: any = {};
          try { parsed = JSON.parse(raw); } catch { parsed = {}; }
          const scrub = (s: any) =>
            typeof s === "string"
              ? s.replace(/\u2014/g, " - ").replace(/\u2013/g, " - ").replace(/\*/g, "")
              : s;
          if (parsed?.script && typeof parsed.script === "object") {
            for (const k of Object.keys(parsed.script)) parsed.script[k] = scrub(parsed.script[k]);
          }
          parsed.fullScript = scrub(parsed.fullScript);
          return {
            ok: true,
            uploadedImages: uploadedUrls,
            commentWord,
            offer: selectedOffer,
            ...parsed,
          };
        },
      });
      res.status(202).json({ jobId }); return;
    } catch (err: any) {
      req.log?.error?.({ err: err?.message, stack: err?.stack }, "script-writer green-screen failed");
      res.status(500).json({ error: err?.message || "Failed to generate green-screen script" }); return;
    }
  },
);

// ----------------------------------------------------------------
// Script Writer OS - Hook + Demo
// ----------------------------------------------------------------
// User uploads up to 6 ordered "step" screenshots (the websites/tools
