export async function podcastClipHandler(req: any, res: any) {
    try {
      const body = req.body || {};
      const seed = (typeof body.context === "string" ? body.context : "").trim().slice(0, 1500);
      const context = seed;
      const offerBrainId: any = (body && body.offerBrainId !== undefined) ? body.offerBrainId : null;
      const influencerId: any = (body && body.influencerId !== undefined) ? body.influencerId : null;
      const idea = body.idea && typeof body.idea === "object" ? body.idea : null;
      const ideaText = idea
        ? `${idea.title || ""}\n${idea.angle || ""}\n${idea.contrarianClaim || ""}`.trim()
        : "";
      if (!seed && !ideaText) {
        res.status(400).json({
          error: "Pick one of the generated ideas, or type your own seed context to write the clip from.",
        }); return;
      }

      const targetSecondsRaw = Number(body.targetSeconds);
      const targetSeconds = (PODCAST_LENGTHS as readonly number[]).includes(targetSecondsRaw)
        ? targetSecondsRaw
        : 60;

      const hookTypeRaw = (typeof body.hookType === "string" ? body.hookType : "any").trim();
      const hookType = (PODCAST_HOOK_TYPES as readonly string[]).includes(hookTypeRaw) ? hookTypeRaw : "any";

      const commentWordRaw = (typeof body.commentWord === "string" ? body.commentWord : "").trim();
      const commentWord = commentWordRaw.replace(/[^\w\-]/g, "").slice(0, 24).toUpperCase();

      const ctaModeRaw = (typeof body.ctaMode === "string" ? body.ctaMode : "soft").trim().toLowerCase();
      const ctaMode = ["soft", "comment", "none"].includes(ctaModeRaw) ? ctaModeRaw : "soft";
      if (ctaMode === "comment" && !commentWord) {
        res.status(400).json({
          error: "You picked the 'Comment X' CTA - add a comment word (e.g. 'AI', 'FRAMEWORK').",
        }); return;
      }

      const resolved = await resolvePodcastBrain(req, body);
      if ("error" in resolved) { res.status(400).json({ error: resolved.error }); return; }
      const { brain, selectedOffer, influencerName, influencerNiche } = resolved;

      const brainBlock = buildPodcastBrainBlock(brain);
      const offerBlock = selectedOffer
        ? `SELECTED OFFER (clip should ultimately reinforce THIS offer's worldview, but DO NOT pitch it directly - keep the clip about the idea):
Offer name: ${selectedOffer.name}
One-liner: ${selectedOffer.tagline}`
        : "SELECTED OFFER: the owner's own brand / brain (defined above).";
      const influencerBlock = influencerName
        ? `SELECTED AI INFLUENCER (this is the persona on the mic):
Name: ${influencerName}
Niche: ${influencerNiche || "(not set)"}`
        : "(No specific AI influencer selected - use the owner's own voice.)";

      const ctaBlock =
        ctaMode === "comment"
          ? `END WITH A "Comment ${commentWord} below" SOFT CTA after the punchline. Do not interrupt the punchline - let it land first.`
          : ctaMode === "none"
          ? "DO NOT add a CTA. End on the punchline only."
          : "END WITH A soft, conversational closing line - 'people don't talk about this enough', 'that's the real issue', 'most people aren't ready for that conversation' - NOT a hard 'comment X' CTA.";

      const hookLibrary = getHookLibraryForPrompt({ perCategory: 25 });
      const hookTypeRule =
        hookType === "any"
          ? "Pick whichever hook type fits the idea best (contrarian / truthBomb / polarising / iRealised)."
          : `The hook MUST be the "${hookType}" hook type.`;

      // Calibrate spoken word count to the target length at fast Instagram pace (~2.6 wps).
      const minWords = Math.round(targetSeconds * 2.2);
      const maxWords = Math.round(targetSeconds * 2.9);

      const systemPrompt = `You are an elite podcast clip script writer. The host is recording side-on with a podcast mic visible. The clip should feel effortless, unfiltered, slightly dangerous, highly opinionated, and emotionally charged - like a friend saying "bro... think about this for a second" - NEVER like an educational lecture.

PROVEN STRUCTURE (every section must be present, in order):
1. STRONG OPINION / HOOK (0-3s) - immediate emotional friction
2. CONTRARIAN STATEMENT - flips the conventional take
3. EXPLAIN WHY - the emotional reason the conventional take is wrong
4. STORY / EXAMPLE / ANALOGY - one quick concrete moment, anecdote or analogy (no fake numbers; if you don't have a real number from the brain, use vibes not stats)
5. PRACTICAL TAKEAWAY - the hard-edged "what to actually do" line
6. PUNCHLINE / ENDING - the screenshot-worthy hard truth that ends the clip

${ctaBlock}

${hookTypeRule}

GOLDEN RULE: the clip must make people either AGREE VIOLENTLY or DISAGREE VIOLENTLY. The enemy is "interesting".

HARD RULES:
- The hook MUST come from the HOOK LIBRARY. Pick one and adapt the variables. Tell us which category and which formula.
- Pull every claim, number and proof point from the BRAIN. Never invent revenue figures, client counts or credentials.
- Conversational rhythm. Short sentences. Permission to pause, reflect, interrupt yourself. No "Welcome back to episode 47" energy.
- Target spoken length: ~${targetSeconds} seconds (${minWords}-${maxWords} spoken words total in fullScript).
- NEVER use em dashes (\u2014) or en dashes (\u2013). Use a regular hyphen (-) with spaces.
- NEVER use markdown asterisks. No * characters in the output.
- NEVER use the words "big" or "leverage". Use "large" or "use" instead.
- No emojis, no hashtags.

OUTPUT JSON SHAPE (return ONLY this JSON, no preamble, no code fence):
{
  "hookCategory": "hormozi" | "hundredFormulas" | "educational" | "storytelling" | "question" | "curiosity" | "listBased" | "problemSolving" | "relatable" | "tipsTricks",
  "hookFormulaUsed": "<the exact proven formula you started from, copied from the library>",
  "hookType": "contrarian" | "truthBomb" | "polarising" | "iRealised",
  "topicCluster": "<short label e.g. AI / business / content / money / mindset>",
  "sections": {
    "opinion": "<the spoken opening hook, 1-2 short sentences, ~3 seconds>",
    "contrarian": "<the contrarian flip, 1-2 short sentences>",
    "why": "<emotional reason it's wrong, 2-4 short sentences>",
    "story": "<one quick story / example / analogy, 2-4 short sentences>",
    "takeaway": "<the practical hard-edged 'what to actually do' line, 1-2 short sentences>",
    "punchline": "<the screenshot-worthy ending line, 1 sentence>",
    "cta": "<${ctaMode === "none" ? "empty string" : ctaMode === "comment" ? `'Comment ${commentWord} below' style soft CTA` : "soft conversational closing line - NOT a 'comment X' CTA"}>"
  },
  "fullScript": "<all sections in order, separated by single line breaks, ready for the host to read>",
  "estimatedSeconds": <number close to ${targetSeconds}>,
  "screenshotLine": "<the single sharpest screenshot-worthy line from anywhere in the clip - used by the editor for the captions overlay>"
}`;

      const userPrompt = `${brainBlock}

${offerBlock}

${influencerBlock}

${ideaText
  ? `SELECTED IDEA TO TURN INTO A CLIP:
"""
${ideaText}
"""
`
  : ""}${seed
  ? `CREATOR'S SEED CONTEXT (what they want to talk about):
"""
${seed}
"""
`
  : ""}TARGET LENGTH: ${targetSeconds} seconds (${minWords}-${maxWords} spoken words)
HOOK TYPE: ${hookType}
CTA MODE: ${ctaMode}${ctaMode === "comment" ? ` (comment word: ${commentWord})` : ""}

HOOK LIBRARY (proven, total ${PROVEN_HOOK_TOTAL} formulas; pick ONE and adapt):

${hookLibrary}

Now produce the clip script as JSON.`;

      const jobId = await enqueueScriptJob({
        clerkId: req.clerkId,
        type: "podcast-clip",
        inputPayload: {
          context,
          ideaTitle: idea?.title || null,
          targetSeconds,
          hookType,
          ctaMode,
          commentWord: ctaMode === "comment" ? commentWord : null,
          offerBrainId,
          influencerId,
        },
        label: (idea?.title || context || "Podcast clip").slice(0, 80),
        log: req.log,
        work: async (ctx) => {
          await ctx.updateProgress(20, "Drafting podcast clip");
          const openai = new OpenAI({
            baseURL: process.env.AI_INTEGRATIONS_OPENAI_BASE_URL,
            apiKey: process.env.OPENAI_API_KEY,
          });
          const completion = await openai.chat.completions.create({
            model: "gpt-4o",
            messages: [
              { role: "system", content: systemPrompt },
              { role: "user", content: userPrompt },
            ],
            response_format: { type: "json_object" },
            temperature: 0.9,
            max_tokens: 2500,
          });
          await ctx.updateProgress(90, "Cleaning output");
          const raw = completion.choices[0]?.message?.content || "{}";
          let parsed: any = {};
          try { parsed = JSON.parse(raw); } catch { parsed = {}; }
          podcastScrubDeep(parsed);
          const VALID_OUT_HOOKS = new Set(["contrarian", "truthBomb", "polarising", "iRealised"]);
          if (!VALID_OUT_HOOKS.has(parsed?.hookType)) parsed.hookType = "contrarian";
          return {
            ok: true,
            offer: selectedOffer,
            targetSeconds,
            hookType,
            ctaMode,
            commentWord: ctaMode === "comment" ? commentWord : null,
            ...parsed,
          };
        },
      });
      res.status(202).json({ jobId }); return;
    } catch (err: any) {
      req.log?.error?.({ err: err?.message, stack: err?.stack }, "script-writer podcast-clip failed");
      res.status(500).json({ error: err?.message || "Failed to generate podcast clip script" }); return;
    }
}
